var e=JSON.parse(`{"wrist-circles":{"name":"Cerchi di polso","description":"Mantieni una posizione eretta con i gomiti morbidi e i polsi davanti a te. Disegna cerchi lenti con entrambi i polsi, quattro conti in una direzione e quattro nell'altra, tenendo le dita rilassate.","goodFor":"Riscalda i polsi e gli avambracci che svolgono la maggior parte del lavoro con ogni oggetto.","alignmentCues":["I gomiti rimangono fermi; si muovono solo i polsi.","Mantieni i cerchi grandi e fluidi."],"commonMistakes":["Affrettare i cerchi trasformandoli in movimenti rapidi."]},"arm-circles":{"name":"Cerchi di braccio","description":"Piedi alla larghezza delle anche, braccia distese. Fai grandi cerchi in avanti con entrambe le braccia per quattro conti, poi all'indietro per quattro, lasciando scivolare le scapole.","goodFor":"Apre le spalle per le rotazioni del bastone e il lavoro con l'anello sopra la testa.","alignmentCues":["I costoli rimangono in basso mentre le braccia passano sopra la testa.","Esala durante la fase discendente."]},"shoulder-rolls":{"name":"Rotazioni delle spalle","description":"Braccia rilassate ai lati. Solleva le spalle verso le orecchie, arrota indietro e in basso, e ripeti in un movimento lento e continuo.","goodFor":"Rilascia la tensione che rende i lanci rigidi e corti."},"neck-rolls":{"name":"Mezzi cerchi del collo","description":"Abbassa il mento verso il petto e muovi lentamente la testa da una spalla all'altra in un semicerchio. Evita di inclinare la testa all'indietro.","goodFor":"Allenta il collo prima di guardare in alto durante i lanci prolungati.","avoidIf":["Lesioni al collo o vertigini quando si muove la testa."]},"hip-circles":{"name":"Cerchi dei fianchi","description":"Mani sui fianchi, ginocchia leggermente piegate. Ruota i fianchi lentamente in una direzione per due battiti e nell'altra per due, mantenendo la testa in posizione orizzontale.","goodFor":"Prepara i fianchi per il movimento intorno alla vita e il corpo per il flusso."},"torso-twists":{"name":"Torcimenti del tronco","description":"Piedi larghi, braccia rilassate. Ruota i costoli a destra e a sinistra e lascia che le braccia oscillino e avvolgano il corpo come maniche vuote.","goodFor":"Attiva la rotazione per i passaggi del bastone e le passate con l'anello."},"knee-bounce":{"name":"Dondolio del ginocchio","description":"Mettiti in piedi con i piedi sotto i fianchi e dondola delicatamente sulle ginocchia ad ogni battito, braccia che oscillano liberamente. Trova la musica nelle gambe.","goodFor":"Immette il ritmo nel tuo corpo prima di prendere un oggetto."},"one-ball-toss":{"name":"Lancio di una palla","description":"Tieni una palla nella mano destra all'altezza della vita. Raccogliela, poi lanciala in un arco che raggiunge appena sopra l'altezza degli occhi e cade nella mano sinistra. Lanciala indietro nello stesso modo. Tieni gli occhi sulla cima dell'arco, non sulle mani.","goodFor":"Costruisce l'arco da cui è composto ogni schema di giocoleria.","alignmentCues":["Gomiti ai lati, avambracci orizzontali.","La cima è alla stessa altezza ad ogni lancio.","Cattura all'altezza della vita e lascia che la mano ceda un po'."],"commonMistakes":["Lanciare in avanti così devi fare un passo dopo la palla.","Guardare le mani invece della cima."]},"two-ball-exchange":{"name":"Scambio di due palle","description":"Una palla in ogni mano. Lancia la palla destra nel suo arco; quando raggiunge la cima, lancia la palla sinistra sotto di essa, verso l'interno. Cattura entrambe e fai una pausa. Poi inizia con la mano sinistra.","goodFor":"Insegna lo scambio: il secondo lancio avviene quando il primo raggiunge la cima.","alignmentCues":["Secondo lancio alla cima, mai in anticipo.","Lancia la seconda palla all'interno della prima."],"commonMistakes":["Passare la seconda palla attraverso invece di lanciarla.","Lanciare entrambe contemporaneamente."]},"cascade":{"name":"Cascata di tre palle","description":"Due palle nella mano destra, una nella sinistra. Lancia dalla destra; quando raggiunge la cima, lancia dalla sinistra; quando questa raggiunge la cima, lancia di nuovo dalla destra. Ogni lancio avviene sul battito, incrociando nell'altra mano in un arco a forma di otto.","goodFor":"Il modello fondamentale della giocoleria.","modifications":["Pratica il flash: tre lanci, tre catture, fermati."],"deepen":["Giocola a un ritmo più veloce con picchi più bassi.","Conta 20 catture senza far cadere."],"alignmentCues":["Lancia dall'interno, cattura dall'esterno.","Picchi allineati, all'altezza degli occhi.","Stai contro una parete se continui a camminare in avanti."],"commonMistakes":["Lanciare in avanti e inseguire il pattern.","Affrettarsi non appena un lancio va storto."]},"reverse-cascade":{"name":"Cascata Inversa","description":"La cascade capovolta: ogni palla viene lanciata dall'esterno, sopra il pattern, e lasciata cadere al centro nell'altra mano.","goodFor":"Allena i lanci dall'esterno e apre a trucchi come il Mills Mess.","alignmentCues":["I lanci formano un arco sopra la palla in arrivo.","Prendi al centro."]},"siteswap-423":{"name":"423","description":"Un pattern a tre palle: un lancio alto su se stesso (4), una palla tenuta (2), poi un lancio di cascade (3). Il 4 va su dallo stesso lato; il 2 viene semplicemente trattenuto per un battito.","goodFor":"Il tuo primo trucco in siteswap: insegna lanci alti e pause."},"siteswap-441":{"name":"441","description":"Due lanci alti che rimangono sullo stesso lato (4, 4) seguiti da un rapido passaggio (1) da una mano all'altra.","goodFor":"Sviluppa il timing tra lanci alti e passaggi veloci."},"two-in-one":{"name":"Due in una Mano","description":"Gioca con due palle in una mano in colonne laterali o piccoli cerchi esterni, un lancio ogni altro battito. Pratica ogni mano.","goodFor":"Il blocco di base per il gioco a quattro palle."},"siteswap-531":{"name":"531","description":"Un lancio molto alto e incrociato (5), un lancio di cascade (3) e un rapido passaggio (1). Il 5 va su mentre le altre due palle continuano a lavorare sotto.","goodFor":"Controllo dell'altezza e un trucco spettacolare a tre palle."},"shower":{"name":"Doccia a Tre Palle","description":"Le palle viaggiano in cerchio: la mano destra lancia ogni palla in alto verso sinistra, e la mano sinistra passa ciascuna palla dritta di nuovo a destra.","goodFor":"Modello circolare classico; allena i passaggi veloci da mano a mano."},"mills-mess":{"name":"Mills Mess","description":"Una cascade a tre palle in cui le braccia continuano a incrociarsi e s'incrociano, quindi ogni lancio viene dall'altro lato del corpo. I percorsi delle palle tracciano un modello intrecciato.","goodFor":"Un classico che piace a tutti e che affina la coordinazione."},"four-ball-fountain":{"name":"Fontana a quattro palle","description":"Ogni mano fa roteare due palle nella propria colonna, le mani alternano i lanci in modo che il pattern non si incroci mai.","goodFor":"Il tuo primo pattern con quattro palle."},"sync-fountain":{"name":"Fontana sincrona","description":"Quattro palle con entrambe le mani che lanciano esattamente nello stesso momento, ognuna verso il proprio lato.","goodFor":"Sviluppa la simmetria e porta a trucchi sincroni."},"five-ball-cascade":{"name":"Cascata a cinque palle","description":"La cascata con cinque palle: lanci alti e veloci in un pattern alto e incrociato. Preparati a mesi di pratica.","goodFor":"Un traguardo per i giocolieri dedicati."},"tennis":{"name":"Tennis","description":"Una cascata in cui una palla, la \\"palla da tennis\\", percorre sempre la parte superiore del pattern invece che al centro. Qualunque mano la tenga, la lancia verso l'esterno in modo che voli sopra come un colpo di rincorsa sopra una rete.","goodFor":"Primo passo verso i lanci esterni mantenendo il ritmo di una cascata normale.","alignmentCues":["Mantieni una palla in vista come palla da tennis.","Lanciala dall'esterno, alla stessa altezza delle altre."],"commonMistakes":["Perdere di vista quale palla passa sopra.","Lanciare la palla superiore più in alto delle altre."]},"half-shower":{"name":"Mezza doccia","description":"Una mano lancia ogni palla sopra la testa mentre l'altra la lancia sotto. Le due traiettorie si separano in un percorso alto esterno e uno basso interno, e le palle si inseguono in un ciclo.","goodFor":"Dividere le mani in due ruoli mantenendo un ritmo uniforme.","alignmentCues":["La mano che lancia sopra lancia verso l'esterno e un po' più in alto.","La mano che lancia sotto mantiene i lanci stretti e interni."],"commonMistakes":["Entrambe le mani che tornano a lanci di cascata normale.","Collisioni al centro quando le traiettorie hanno la stessa altezza."]},"claw-cascade":{"name":"Cascata a artiglio","description":"La cascata col palmo rivolto verso il basso. Ogni mano si alza e afferra la palla dall'alto, poi tira giù e gira per lanciare. Le mani sembrano artigliare le palle.","goodFor":"Sviluppa presa attiva e un forte movimento del polso.","alignmentCues":["Allunga la mano per raggiungere la palla, dita divaricate.","Tira giù e gira il polso in un unico movimento."],"commonMistakes":["Afferrare tardi, così la palla colpisce il dorso della mano.","Lanciare basso perché la rotazione richiede troppo tempo."]},"chops":{"name":"Colpi","description":"Dopo ogni presa, la mano porta la palla in alto attraverso il corpo e la taglia verso il basso, lanciando dal lato opposto. Le braccia si incrociano come se stessero tagliando, e le palle cadono in una cascata stretta sotto.","goodFor":"Grandi portate di braccio con il ritmo della cascata ancora sotto.","alignmentCues":["Afferra in alto, porta attraverso, taglia verso il basso e lancia.","Lancia dal lato opposto del corpo."],"commonMistakes":["Portare troppo lontano, così la presa successiva è tardiva.","Braccia che si scontrano al centro."]},"penguin-cascade":{"name":"Cascade del Pinguino","description":"Braccia pendenti lungo i fianchi con i palmi rivolti verso il basso. Ogni presa avviene bassa e di lato, e i lanci partono dall'alto dell'anca. Sembrerai un pinguino che sbatte le ali al ritmo.","goodFor":"Lanci e prese guidati dal polso lontano dalla posizione abituale della mano.","alignmentCues":["Gomiti dritti, mani ai fianchi.","Lancia dal polso, palmi rivolti indietro."],"commonMistakes":["Flettere i gomiti indietro in una cascata normale.","Lanci che si spostano in avanti perché il polso è piegato."]},"under-the-leg":{"name":"Sotto la Gamba","description":"Una cascata in cui ogni sesto lancio va sotto la gamba destra. Solleva il ginocchio quando arriva la palla, raggiungi sotto la coscia e lancia verso l'alto dall'esterno, poi abbassa il piede per la presa successiva.","goodFor":"Il primo lancio con il corpo: sollevamento della gamba e portata del braccio sincronizzati a un singolo battito.","alignmentCues":["Solleva il ginocchio prima del lancio, non durante.","Lancia un po' più in alto per coprire la portata extra."],"commonMistakes":["Inclinare in avanti verso la gamba invece di sollevare il ginocchio.","Affrettarsi con il lancio successivo dopo che la gamba scende."]},"behind-the-back":{"name":"Dietro la schiena","description":"Ogni sesto lancio, la mano destra fa un arco dietro la vita e lancia la palla sopra la spalla opposta, facendola atterrare nel pattern davanti. Gli altri lanci rimangono una cascata normale.","goodFor":"Lanciare a occhi chiusi in un pattern che non si può vedere.","alignmentCues":["Fare oscillare la mano dietro presto, mentre la palla atterra.","Mirare sopra la spalla lontana, un po' più in alto del normale."],"commonMistakes":["Lanciare troppo in avanti in modo che la palla cada davanti a te.","Ruotare tutto il tronco."]},"over-the-shoulder":{"name":"Sopra la spalla","description":"Ogni sesto lancio, la mano destra manda la palla in alto dalla parte anteriore, su e indietro sopra la spalla sinistra. La mano sinistra fa un arco dietro l'anca e la prende a occhi chiusi, poi lancia la sua prossima palla in alto accanto all'anca. Tutto il resto è una cascata normale.","goodFor":"Un ricevimento a occhi chiusi dietro la schiena, sincronizzato con il senso piuttosto che con la vista.","alignmentCues":["Lanciare abbastanza in alto da superare la testa, appena dietro la spalla sinistra.","Portare la mano che riceve dietro l'anca presto, con il palmo rivolto verso l'alto."],"commonMistakes":["Girare la testa per cercare la palla.","Lanciare troppo in basso in modo che la palla tocchi la testa o la spalla."]},"knee-bounce-cascade":{"name":"Bounce del ginocchio","description":"Ogni sesto lancio, la mano destra fa cadere la palla sul ginocchio destro mentre il ginocchio sale. La palla rimbalza sulla parte superiore della coscia, in alto e attraverso verso la mano sinistra, e il piede torna giù per il prossimo ricevimento.","goodFor":"Equilibrarsi su una gamba mentre il ginocchio si unisce al pattern sul battito.","alignmentCues":["Sollevare il ginocchio per incontrare la palla, a livello della coscia.","Fare cadere la palla, non lanciarla giù."],"commonMistakes":["Calciare la palla in modo che voli in avanti.","Inclinarsi verso il ginocchio invece di sollevarlo."]},"head-bounce-cascade":{"name":"Bounce della testa","description":"Ogni sesto lancio va sopra la testa. Inclina la testa all'indietro in modo che la palla cada sulla fronte, poi annuisci in basso e in avanti verso la mano sinistra. Gli altri lanci rimangono una cascata normale sotto.","goodFor":"Seguire una palla dritta sopra di te mentre le mani continuano a mantenere la cascata.","alignmentCues":["Inclina la testa all'indietro presto e tieni gli occhi sulla palla.","Piega leggermente le ginocchia per ammorbidire il rimbalzo."],"commonMistakes":["Colpire la palla con la testa invece di lasciarla cadere.","Perdere la cascata mentre guardi in su."]},"crossed-arm-cascade":{"name":"Cascata a Braccia Incrociate","description":"Incrocia le avambraccia con la mano destra sul lato sinistro e mantienile incrociate. Gioca una cascata da quella posizione. I lanci sembrano specchiati anche se il pattern appare normale.","goodFor":"Rompendo l'abitudine di dove si trova ogni mano.","alignmentCues":["Mantieni l'incrocio ai polsi, non ai gomiti.","I lanci raggiungono l'altezza degli occhi come al solito."],"commonMistakes":["Sganciarsi tra i lanci.","Le mani che si scontrano mentre cambiano lato."]},"burkes-barrage":{"name":"Assalto di Burke","description":"Basato su 423. La palla lanciata come un 4 viene afferrata e trasportata, il 2 è un breve sollevamento nella stessa mano, e il 3 viene tagliato giù nel pattern. Le braccia si intrecciano in una fioritura movimentata.","goodFor":"Combinare trasporti e afferrate su una siteswap che già conosci.","alignmentCues":["Impara prima il tempo di 423, poi aggiungi il trasporto.","Il 2 lascia appena la mano."],"commonMistakes":["Lanciare il 2 così in alto da rompere il ritmo.","Dimenticarsi del taglio sul 3."]},"rubensteins-revenge":{"name":"Vendetta di Rubenstein","description":"Un intreccio di trasporti su 52233. Un lancio alto guadagna tempo mentre le mani afferrano, tagliano e si incrociano, poi il pattern si risolve in una cascata. Imparalo lentamente, una mano alla volta.","goodFor":"Un'esibizione che allena trasporti, afferrate e braccia incrociate insieme.","alignmentCues":["Il 5 è l'unico lancio alto.","Impara il percorso della mano senza la palla alta."],"commonMistakes":["Panicarsi durante i trasporti e lanciare prematuramente.","Il lancio alto che si sposta in avanti."]},"siteswap-42":{"name":"Due palle 42","description":"Due palle: ogni mano lancia una palla alta a se stessa e tiene l'altra per un battito. Le palle alte salgono in colonne su ciascun lato mentre le mani si alternano. Un modo tranquillo per imparare i lanci su se stessi.","goodFor":"Lanci su se stessi a quattro altezze, il blocco di base per due in una mano.","alignmentCues":["I lanci rimangono sul proprio lato.","Tieni il 2 fermo nel palmo."],"commonMistakes":["I lanci che si spostano attraverso il centro.","Lanciare per sbaglio la palla tenuta."]},"snake":{"name":"Serpente","description":"Tre palle lanciate come cinque alte incrociate con un battito vuoto dopo ciascuna. Le palle seguono una dopo l'altra lungo la stessa traiettoria alta, come un serpente che scivola sopra la testa.","goodFor":"Lanci alti costanti senza la pressione di un ritmo completo a cinque palle.","alignmentCues":["Tutti i cinque alla stessa altezza.","Usa il battito vuoto per riportare la mano in posizione."],"commonMistakes":["I cinque che si spostano in avanti.","Lanciare sul battito vuoto per abitudine."]},"grace":{"name":"Grazia","description":"Un multiplex delicato: una mano lancia due palle contemporaneamente, un lancio incrociato normale e un piccolo passaggio dritto all'altra mano. Poi un battito di pausa e ritorno alla cascata.","goodFor":"Un'introduzione morbida al lancio di due palle da una mano.","alignmentCues":["Lascia andare entrambe le palle insieme.","La palla piccola sale appena."],"commonMistakes":["Lasciare andare le due palle a momenti diversi.","Lanciare la palla piccola troppo in alto."]},"orinoco-flow":{"name":"Flusso Orinoco","description":"Due round di 42 con un lancio di cascata cucito alla fine, così i lanci su se stessi cambiano lato ad ogni giro. Onde tra colonne e cascata.","goodFor":"Un passaggio fluido tra lanci su se stessi e lanci incrociati.","alignmentCues":["I quattro dritti in alto accanto a te.","Il 3 è un lancio a cascata normale."],"commonMistakes":["I quattro che si inclinano verso l'interno.","Perdere il conto del ciclo di cinque lanci."]},"relfs-rhythm":{"name":"Ritmo di Relf","description":"Un lancio su se stesso e una pausa, poi tre lanci a cascata. Poiché il ciclo è dispari, il lancio su se stesso atterra sempre sull'altra mano.","goodFor":"Inserire un trucco in una cascata in corso su entrambi i lati.","alignmentCues":["Cascata prima, poi inserire il 42.","Mantenere il quattro sul suo lato."],"commonMistakes":["Eseguirlo solo sulla mano forte.","La cascata che accelera dopo."]},"frostbite":{"name":"Frostbite","description":"Due quattro veloci, un passaggio rapido attraverso, poi due lanci a cascata. Il passaggio scivola sotto mentre i quattro rimangono in alto.","goodFor":"Combinare passaggi veloci con lanci alti in un unico ciclo.","alignmentCues":["Il 1 è un lancio diretto in diagonale.","I quattro rimangono verticali."],"commonMistakes":["Lanciare il 1 invece di passarlo.","Dimenticare il secondo quattro."]},"siteswap-52512":{"name":"52512","description":"Due cinque alti separati da un momento di pausa, poi un cinque, un passaggio veloce e una pausa. Il pattern mescola lanci alti e incrociati con lanci brevi e bassi.","goodFor":"Controllo preciso alto-basso con tre palle.","alignmentCues":["I cinque raggiungono tutti la stessa altezza.","I due rimangono nella mano."],"commonMistakes":["Lanciare i 2.","Cinque irregolari."]},"high-low-shower":{"name":"Doccia Alta-Bassa","description":"Una doccia con un tocco in più: una palla va molto in alto mentre le altre scorrono basse e veloci sotto. Il ritmo suona come un galoppo.","goodFor":"Grande contrasto di altezza e mani veloci in un pattern a tre palle.","alignmentCues":["Il sette va in alto e dritto.","I uno sono passaggi piatti."],"commonMistakes":["I sette che si spostano in avanti.","I uno che arco troppo in alto."]},"siteswap-612":{"name":"612","description":"Un lancio alto su se stessi, un passaggio veloce e una pausa. Il sei va su accanto a te sullo stesso lato, mentre le altre due palle si scambiano sotto.","goodFor":"Lanci alti su se stessi mescolati con passaggi bassi veloci.","alignmentCues":["Il sei rimane sul suo lato.","Passa il 1 piatto e veloce."],"commonMistakes":["Il sei che attraversa.","Tieni troppo a lungo il 2."]},"three-in-one":{"name":"Tre in una Mano","description":"Tre palle giocolate con solo la mano destra in colonne alte o una piccola fontana. Ogni lancio è alto, quindi c'è tempo per prendere e lanciare di nuovo.","goodFor":"Controllo con una mano e coerenza di altezza.","alignmentCues":["I lanci raggiungono il picco ben sopra la testa.","Mantieni la mano in movimento in un piccolo cerchio."],"commonMistakes":["I lanci che si spostano verso l'esterno.","I lanci troppo bassi per mantenere tre in gioco."]},"columns":{"name":"Colonne","description":"Tre palle che salgono in colonne verticali. Entrambe le mani lanciano le palle esterne insieme, poi la destra lancia la palla centrale da sola. Su, su, su, come pistoni.","goodFor":"Primi lanci simultanei e base per molti trucchi sincroni.","alignmentCues":["Le colonne esterne salgono insieme.","La colonna centrale dritta verso l'alto dal centro."],"commonMistakes":["Le colonne inclinate in modo che le palle collidano.","Tempismo irregolare nella coppia."]},"infinity":{"name":"Infinito","description":"Un modello a colonna in cui il lancio singolo va di traverso invece che in alto, così la palla centrale cambia lato ad ogni ciclo. Le palle tracciano una figura a otto.","goodFor":"Cambiare un modello sincrono tra i lati.","alignmentCues":["Coppia dritta in alto, singolo di traverso.","I lati si alternano ad ogni ciclo."],"commonMistakes":["Il lancio singolo che va dritto in alto per abitudine.","La coppia che si allontana."]},"rainbow-cross":{"name":"Croce dell'Arcobaleno","description":"Due palle si incrociano a coppie, poi una va dritta in alto al centro. Le traiettorie incrociate formano un arcobaleno sopra la testa.","goodFor":"Lanci sincroni incrociati senza collisioni.","alignmentCues":["Un lancio incrociato leggermente davanti all'altro.","Il lancio centrale va dritto in alto."],"commonMistakes":["Le palle incrociate che si colpiscono.","Il lancio centrale inclinato."]},"crossunder":{"name":"Crossunder","description":"Ogni lancio incrocia: una coppia incrociata, poi un lancio singolo che cambia lato ad ogni ciclo. Le palle si avvolgono sopra e sotto l'una all'altra.","goodFor":"Controllo sincrono di tutti i lanci incrociati.","alignmentCues":["Mantenere i lanci incrociati in piani leggermente diversi.","Altezza uniforme in tutto il ciclo."],"commonMistakes":["Scontri al centro.","Il lancio singolo troppo corto."]},"yo-yo":{"name":"Yo-Yo","description":"Una mano lancia colonne mentre l'altra mano tiene una palla e si muove su e giù sotto una di esse, come se le due palle fossero legate da un filo.","goodFor":"Un'illusione che insegna a tenere una palla in movimento contro una colonna.","alignmentCues":["La palla tenuta segue l'ombra della palla della colonna.","Le colonne rimangono verticali."],"commonMistakes":["La palla tenuta che rimane indietro.","Le colonne che si allontanano."]},"box":{"name":"Box","description":"Le palle tracciano un quadrato. Una mano lancia una palla dritta in alto mentre l'altra passa una palla attraverso, poi i ruoli si scambiano. Lati alti, parte superiore e inferiore piatte.","goodFor":"Un classico schema sincronizzato che allena i passaggi orizzontali.","alignmentCues":["I passaggi vanno dritti attraverso all'altezza della mano.","I verticali salgono dritti in alto."],"commonMistakes":["I passaggi che arcurano troppo in alto.","Le colonne che si inclinano verso l'interno."]},"broken-box":{"name":"Box Rotto","description":"Un quadrato che cambia lato ad ogni lancio: il lancio verticale e il passaggio trasversale alternano mano, quindi il quadrato continua a piegarsi su se stesso.","goodFor":"Rapido cambio di ruolo sincronizzato.","alignmentCues":["Alternare il verticale ad ogni battito.","Passare piatto e veloce."],"commonMistakes":["Ripetere il verticale sullo stesso lato.","Affrettare il passaggio."]},"als-slide":{"name":"Scivolata di Al","description":"Un lancio alto incrociato abbinato a un passaggio piatto, poi una pausa e un altro lancio alto incrociato. Le palle scivolano attraverso la parte superiore e inferiore in una forma arrotolata e fluida.","goodFor":"Lanci incrociati sincronizzati misti a passaggi e pause.","alignmentCues":["I quattro incrociati raggiungono il picco insieme.","Tieni fermo il 2."],"commonMistakes":["Lanciare la palla tenuta.","Urto al centro."]},"factory":{"name":"Factory","description":"Una mano funziona come un nastro trasportatore, portando le palle a livello della vita, mentre l'altra mano lancia colonne. Le palle descrivono un ciclo simile a una macchina.","goodFor":"Coordinazione di portare e lanciare in un ritmo sincrono.","alignmentCues":["La mano che trasporta si muove in un ampio arco.","Le verticali rimangono alte."],"commonMistakes":["La mano che trasporta fa cadere le palle nella colonna.","Colonne inclinate."]},"broken-shower":{"name":"Doccia Rotta","description":"Una doccia sincrona: la mano destra lancia in alto mentre la sinistra passa in basso nello stesso momento. Le palle descrivono un giro stretto.","goodFor":"Una versione sincrona del ciclo della doccia.","alignmentCues":["Entrambe le mani rilasciano insieme.","Arco alto per la destra, passaggio piatto per la sinistra."],"commonMistakes":["Rilascio uno dopo l'altro.","Passaggio che sale verso la palla alta."]},"crossed-arm-shower":{"name":"Doccia a Braccia Incrociate","description":"La doccia eseguita con i polsi incrociati. I lanci alti provengono dal lato sinistro del corpo e i passaggi rapidi tornano sotto.","goodFor":"Controllo della doccia in una posizione di braccio insolita.","alignmentCues":["Rimanere incrociati per tutto il tempo.","Passaggio vicino al corpo."],"commonMistakes":["Decrocio per fare le prese.","Passaggi troppo alti."]},"siteswap-534":{"name":"534","description":"Un modello a quattro palle che mescola un cinque incrociato, un tre a cascata e un quattro auto. Si sente come un 423 a quattro palle e si collega perfettamente alla fontana.","goodFor":"Il trucco a quattro palle più popolare, e un modo per entrare in siteswap più alti.","alignmentCues":["Cinque più alti, tre più bassi.","Quattro rimane sul suo lato."],"commonMistakes":["Pianificazione delle altezze.","Affrettare il tre."]},"siteswap-552":{"name":"552","description":"Due cinque incrociati e una pausa. Quattro palle vengono giocolate in un ritmo da cinque palle con un battito per respirare.","goodFor":"Lanci a cinque altezze con tempo per recuperare.","alignmentCues":["Entrambi i cinque identici.","Mantieni il 2 fermo."],"commonMistakes":["Lanciare la pausa.","I cinque che si spostano in avanti."]},"siteswap-5551":{"name":"5551","description":"Tre cinque di fila e un passaggio veloce. Un buon passo verso una cascata di cinque palle.","goodFor":"Praticare serie di cinque con quattro palle.","alignmentCues":["I cinque tutti alla stessa altezza.","Passaggio piatto e veloce per il 1."],"commonMistakes":["I cinque che scendono.","Lanciare il 1 in alto."]},"siteswap-55550":{"name":"55550","description":"Quattro cinque e una mano vuota. Una cascata di cinque palle con una palla mancante, che la rende una grande prova per cinque palle.","goodFor":"L'ultimo passo prima della cascata di cinque palle.","alignmentCues":["Usa il vuoto per stabilizzarti.","I cinque coerenti."],"commonMistakes":["Lanciare nel vuoto.","I cinque che si spostano."]},"siteswap-633":{"name":"633","description":"Un lancio alto da sé stesso, poi due lanci a cascata. Il sei rimane in alto mentre la cascata scorre sotto.","goodFor":"Lanci alti da sé stesso intrecciati in un ritmo a quattro palle.","alignmentCues":["Il sei rimane sopra la propria mano.","I tre rimangono bassi."],"commonMistakes":["Il sei che si sposta lateralmente.","I tre troppo alti."]},"siteswap-53":{"name":"53","description":"Una mano lancia in alto incrociando cinque, mentre l'altra lancia in basso tre a cascata. Una doccia metà e metà con quattro palle.","goodFor":"Controllo dell'altezza tra le due mani.","alignmentCues":["Mano destra alta, mano sinistra bassa.","Ritmo uniforme."],"commonMistakes":["Le altezze che convergono.","Affrettare i tre."]},"wimpy":{"name":"Modello Wimpy","description":"Quattro palle con ogni coppia che si incrocia contemporaneamente. Gli archi si scambiano lato ad ogni battito in un incrocio ampio.","goodFor":"Sincronia di incrocio a quattro palle.","alignmentCues":["Una mano lancia leggermente in avanti.","Rilascio insieme."],"commonMistakes":["Scontro al centro.","Rilascio sfasato."]},"four-ball-shower":{"name":"Doccia a quattro palle","description":"Quattro palle in cerchio: lanci molto alti da una mano e passaggi piatti dall'altra.","goodFor":"Coerenza dei lanci alti a quattro palle.","alignmentCues":["I sette dritti e alti.","Passaggi veloci e piatti."],"commonMistakes":["Sette che si spostano in avanti.","Passaggi che salgono."]},"tsunami":{"name":"Tsunami","description":"Un sette alto, una pausa, un quattro auto, un passaggio e un sei alto auto. Onde di altezza si infrangono sul modello.","goodFor":"Controllo avanzato di quattro palle con altezze miste.","alignmentCues":["Impara i lanci lentamente in ordine.","Sette e sei salgono entrambi in alto."],"commonMistakes":["Altezze inconsistenti.","Perdere il conto."]},"siteswap-645":{"name":"645","description":"La versione a cinque palle di 534: un sei alto auto, un quattro auto e un cinque incrociato.","goodFor":"Un primo trucco dalla cascata a cinque palle.","alignmentCues":["Il sei è il più alto.","Il quattro rimane sul suo lato."],"commonMistakes":["Altezze appiattite.","Deriva."]},"siteswap-744":{"name":"744","description":"Un sette incrociato molto alto seguito da due quattro auto.","goodFor":"Inserimento di lanci alti in cinque palle.","alignmentCues":["Sette dritto e alto.","Quattro verticali."],"commonMistakes":["Sette che deriva.","Quattro che incrocia."]},"five-ball-shower":{"name":"Doccia a Cinque Palle","description":"Cinque palle in un ciclo: nove alte da una mano e passaggi piatti di ritorno sotto.","goodFor":"Altezza e precisione al massimo livello.","alignmentCues":["Nove dritte e costanti.","Passaggi piatti."],"commonMistakes":["Nove vaganti.","Passaggi che salgono."]},"five-ball-half-shower":{"name":"Cascata a metà con cinque palle","description":"Lanci sincroni incrociati, una mano più alta dell'altra, con cinque palle.","goodFor":"Controllo sincrono incrociato con cinque palle.","alignmentCues":["Destra più alta, sinistra più bassa.","Rilascio simultaneo."],"commonMistakes":["Altezze che convergono.","Scontri."]},"martins-one-count":{"name":"Schema di Martin","description":"Un multiplex: un sei alto e una palla trattenuta rilasciati insieme, poi una pausa e un cinque incrociato.","goodFor":"Tempo del multiplex con cinque palle.","alignmentCues":["Il multiplex si rilascia in modo pulito.","Il cinque incrocia."],"commonMistakes":["Divisione del multiplex.","Il sei che deriva."]},"six-ball-fountain":{"name":"Fontana con sei palle","description":"Tre palle in ogni mano, giocolate in alte fontane affiancate.","goodFor":"Il traguardo del numero di sei palle.","alignmentCues":["Ogni mano gestisce la propria fontana.","Lanci alti e costanti."],"commonMistakes":["Le fontane che si avvicinano l'una all'altra.","Lanci troppo bassi."]},"club-swing":{"name":"Giro singolo del bastone","description":"Tieni un bastone per il manico, con il pomello infilato nel polso della mano. Fallo oscillare dall'alto della vita in modo che giri una volta in aria e arrivi per il manico nell'altra mano. Lancialo indietro nello stesso modo.","goodFor":"Imparare la singola rotazione da cui è composto ogni pattern con i bastoni.","alignmentCues":["Solleva dal gomito, lascia che il polso faccia girare il bastone.","Cattura il manico all'altezza della vita."],"commonMistakes":["Fare un movimento brusco del polso facendo girare troppo il bastone.","Lanciare in avanti in modo che il manico cada lontano."]},"club-exchange":{"name":"Scambio di due bastoni","description":"Un bastone in ogni mano. Lancia una rotazione singola con la mano destra; al culmine, lancia il bastone sinistro sotto di esso. Catturali entrambi per i manici e fai una pausa, poi inizia con l'altra mano.","goodFor":"Sincronizzare due bastoni che ruotano senza collisioni.","alignmentCues":["Il secondo bastone va al culmine del primo.","Lancia il secondo bastone all'interno del primo."],"commonMistakes":["I bastoni che si urtano a metà.","Rotazione disuguale tra le mani."]},"club-cascade":{"name":"Cascata di tre bastoni","description":"La cascata con i bastoni, ognuno che ruota una volta. I lanci partono dall'interno del corpo e viaggiano attraverso, con i manici dei bastoni puntati verso di te.","goodFor":"Il pattern di base per tutti i lanci con i bastoni.","alignmentCues":["Lancia dal gomito, mantieni i polsi morbidi.","I bastoni rimangono paralleli al petto."],"commonMistakes":["I bastoni che si inclinano facendoli ruotare di lato.","Ruotare troppo velocemente e colpire il corpo."]},"club-doubles":{"name":"Doppi bastoni","description":"Una cascata di tre bastoni in cui ogni bastone ruota due volte in aria. I lanci sono più alti e lenti, e i bastoni si confondono in grandi cerchi.","goodFor":"Control della rotazione e l'altezza necessaria per quattro clubs.","alignmentCues":["Solleva di più dal braccio, non dal polso.","Mantieni la rotazione doppia fluida ed uniforme."],"commonMistakes":["Flettere il polso e sovraspinare.","Lanciare i doppioni troppo bassi."]},"club-flats":{"name":"Club Flats","description":"Una cascata in cui i clubs non ruotano affatto. Ogni club fluttua con l'impugnatura verso il basso, spinto verso l'alto da un polso dritto, e viene preso in posizione verticale.","goodFor":"Controllo del polso e un facile contrasto con i lanci rotanti.","alignmentCues":["Blocca il polso e spingi dal gomito.","Il club rimane verticale per tutto il percorso."],"commonMistakes":["Rotazioni accidentali a metà.","Lanciare troppo in alto in modo che il club vacilli."]},"club-under-leg":{"name":"Club Sotto la Gamba","description":"Una cascata di clubs in cui ogni sesto lancio viene passato sotto la gamba destra. Solleva il ginocchio, fai passare il club sotto la coscia e lascia che ruoti verso l'alto nel pattern.","goodFor":"Il primo lancio con il corpo con i clubs.","alignmentCues":["Ginocchio in alto presto.","Un po' di altezza in più sul lancio con la gamba."],"commonMistakes":["Colpire la gamba con il club.","Curvarsi invece di sollevare il ginocchio."]},"club-behind-back":{"name":"Club Dietro la Schiena","description":"Una cascata di clubs in cui ogni sesto lancio viene fatto dietro la vita e mandato sopra la spalla opposta nel pattern.","goodFor":"Lanci ciechi di clubs dietro il corpo.","alignmentCues":["Fai passare il braccio dietro presto.","Punta sopra la spalla lontana."],"commonMistakes":["Il club atterra troppo davanti.","Torcere il tronco."]},"club-four-fountain":{"name":"Fontana a quattro club","description":"Due club in ogni mano, ogni mano lancia doppie nel proprio getto. I club non si incrociano mai al centro.","goodFor":"Il traguardo dei quattro club.","alignmentCues":["Doppie dalla propria parte.","Le mani si alternano in modo uniforme."],"commonMistakes":["I club che si spostano verso il centro.","Girare in modo irregolare tra le mani."]},"ring-cascade":{"name":"Cascata a tre anelli","description":"Il cascade con gli anelli tenuti di lato, come un volante visto di profilo. Ogni anello vola attraverso il modello senza girare, così i bordi tagliano l'aria in modo pulito.","goodFor":"Un modo semplice per provare gli anelli e sentire come fluttuano.","alignmentCues":["Tieni l'anello di lato verso di te.","Lascia andare con il polso dritto."],"commonMistakes":["Anelli che oscillano a causa di un polso inclinato.","Lanciarli di fronte in modo che prendano il vento."]},"ring-pancakes":{"name":"Pancake a anello","description":"Un cascade di anelli in cui ogni anello si capovolge in piano in cima al lancio e torna di lato per il ricevimento, come una frittella girata in padella.","goodFor":"Controllo del polso e un'esibizione spettacolare con gli anelli.","alignmentCues":["Una rapida rotazione del polso al momento del rilascio.","Ricevi l'anello di nuovo di lato."],"commonMistakes":["Capovolgimento eccessivo.","Lanciare basso in modo che l'anello non possa girare."]},"ring-four-fountain":{"name":"Fontana a quattro anelli","description":"Due anelli in ogni mano, lanciati in getti separati, con i bordi che tagliano dritti su e giù.","goodFor":"Quattro oggetti con un oggetto leggero e fluttuante.","alignmentCues":["Gli anelli rimangono in verticale.","Ogni mano segue la propria colonna."],"commonMistakes":["Anelli che si toccano al centro.","Lanci che si spostano in avanti."]},"hoop-juggle-single":{"name":"Lancio singolo dell'anello","description":"Tieni un anello per il bordo, appeso accanto a te. Lancialo in un arco morbido all'altra mano in modo che viaggi in verticale e arrivi alla stessa altezza da cui è partito.","goodFor":"Imparare come vola un anello di dimensioni normali prima di aggiungerne altri.","alignmentCues":["Mantieni l'anello in verticale rispetto al petto.","Lancialo dalla spalla, non dal polso."],"commonMistakes":["Lanciarlo di faccia in modo che voli via.","Lanciare basso e afferrare."]},"hoop-juggle-exchange":{"name":"Scambio di due anelli","description":"Un anello in ogni mano. Lancialo con la mano destra; quando raggiunge il punto più alto, lancialo con la sinistra da sotto. Gli anelli si incrociano da vicino, uno davanti all'altro.","goodFor":"Tempo di due anelli e evitare che si scontrino.","alignmentCues":["Il secondo anello al culmine del primo.","Lancialo leggermente in avanti."],"commonMistakes":["Anelli che si colpiscono.","Lanciare entrambi troppo velocemente."]},"hoop-juggle-cascade":{"name":"Cascata di tre anelli","description":"La cascata con anelli di dimensioni normali. Le mani rimangono distanziate, i lanci sono ampi e lenti, e ogni anello ruota in verticale nel pattern.","goodFor":"Il pattern base per il giocolaggio con anelli.","alignmentCues":["Braccia distese, gomiti morbidi.","Ogni anello nello stesso piano."],"commonMistakes":["Anelli che si spostano in avanti.","Affrettare i lanci."]},"hoop-juggle-reverse":{"name":"Cascata Inversa con Anello","description":"Anelli lanciati dall'esterno sopra la testa e catturati dall'interno, la cascata inversa su larga scala.","goodFor":"Lanci dall'esterno con anelli.","alignmentCues":["Lancia dall'esterno, sopra la testa.","Cattura vicino al centro."],"commonMistakes":["Anelli che atterrano troppo larghi.","Archi irregolari."]},"hoop-juggle-shower":{"name":"Doccia con Anello","description":"Tre anelli in cerchio: lanci alti da una mano e passaggi rapidi dietro.","goodFor":"Altezza e controllo del passaggio con anelli.","alignmentCues":["Lanci alti in verticale e attraverso.","Passa vicino al corpo."],"commonMistakes":["Lanci alti che deviano.","Passaggi che salgono."]},"hoop-juggle-two-in-one":{"name":"Due Anelli in una Mano","description":"Due anelli giocolati solo dalla mano destra, che salgono in colonne accanto a te.","goodFor":"Controllo di un anello con una mano.","alignmentCues":["Le colonne rimangono verticali.","Lancia in alto per guadagnare tempo."],"commonMistakes":["Anelli che si allontanano.","Troppo bassi."]},"hoop-juggle-423":{"name":"Anello 423","description":"Il siteswap 423 con tre anelli: un quattro auto, un due tenuto e un tre incrociato.","goodFor":"Varietà di siteswap con anelli.","alignmentCues":["Il quattro rimane sul suo lato.","Tieni il 2."],"commonMistakes":["Lancia il 2.","Quattro che si allontanano."]},"hoop-juggle-441":{"name":"Anello 441","description":"Due quattro autoreferenziali e un passaggio veloce con gli anelli. Il passaggio scivola sotto la coppia alta.","goodFor":"Passaggi veloci tra lanci alti di anelli.","alignmentCues":["Quattro verticali.","Passaggio piatto."],"commonMistakes":["Passaggio lanciato.","Quattro che si allontanano."]},"hoop-juggle-four":{"name":"Fontana a Quattro Anelli","description":"Due anelli in ogni mano, lanciati in fontane affiancate.","goodFor":"Il traguardo dei quattro anelli.","alignmentCues":["Ogni lato separato.","Ritmo uniforme."],"commonMistakes":["Anelli che si allontanano insieme.","Lanci troppo bassi."]},"hoop-juggle-under-leg":{"name":"Anello sotto la gamba","description":"Una cascata di anelli con ogni sesto lancio passato sotto la gamba destra sollevata.","goodFor":"Lanci corpo con un grande oggetto.","alignmentCues":["Solleva il ginocchio in alto.","Lancia un po' più in alto."],"commonMistakes":["L'anello che tocca il piede.","Inclinazione in avanti."]},"hoop-juggle-back-throw":{"name":"Lancio all'indietro dell'anello","description":"Una cascata di cerchi in cui ogni sesto lancio va dietro la schiena e sopra la spalla lontana.","goodFor":"Lanci a occhi chiusi con cerchi.","alignmentCues":["Oscilla dietro presto.","Sopra la spalla lontana."],"commonMistakes":["Il cerchio atterra davanti.","Torcere."]},"hoop-juggle-body-hoop":{"name":"Giocoleria durante il waist hooping","description":"Mantieni un cerchio in movimento in vita mentre giocoli altri tre in cascata. I fianchi mantengono il loro ritmo sotto le braccia.","goodFor":"Dividere l'attenzione tra body hooping e giocoleria.","alignmentCues":["I fianchi guidano il body hoop, le braccia rimangono indipendenti.","Mantieni il piano di giocoleria davanti al body hoop."],"commonMistakes":["Il body hoop rallenta mentre ti concentri sulla giocoleria.","Le braccia che scendono nel body hoop."]},"pass-one-ball":{"name":"Passaggio di una palla","description":"Stai di fronte al tuo partner a circa due metri e mezzo di distanza. Lancia una palla dalla mano destra in un arco morbido alla mano sinistra del partner. Lui la passa alla sua destra e la lancia indietro alla tua sinistra, e tu la passi alla tua destra di nuovo.","goodFor":"Imparare l'altezza e la distanza di un passaggio prima di qualsiasi giocoleria.","alignmentCues":["Lancia dritto attraverso, senza incrociare.","Il punto più alto è appena sopra l'altezza della testa, a metà strada tra voi.","Guarda il tuo partner, non la palla nella tua mano."],"commonMistakes":["Lanciare verso il viso del partner invece che in un arco.","Mirare alla sua mano destra, così il passaggio incrocia."]},"pass-hand-across":{"name":"Passaggio di due palle","description":"Due palle ciascuno. Entrambi passate dalla destra nello stesso battito. Ogni mano sinistra cattura il passaggio in arrivo e lo passa dritto alla destra, pronto per il prossimo passaggio. Niente viene lanciato a se stessi, quindi si tratta solo di sincronizzare i passaggi.","goodFor":"Passare su un battito comune prima di aggiungere la cascata.","alignmentCues":["Passa insieme: mani destre sul conto.","Cattura con la mano sinistra, attraverso basso e veloce."],"commonMistakes":["Uno di voi passa troppo presto, così i passaggi si incrociano in aria a momenti diversi.","Lanciare la mano attraverso invece di passarla."]},"pass-six-count":{"name":"Sei-Conto","description":"Entrambi juggle una cascata di tre palle e passate ogni sesto lancio, sempre dalla mano destra a quella sinistra del partner. Tra i passaggi avete cinque lanci personali per stabilizzare il pattern.","goodFor":"Il primo pattern completo di passaggio: molto tempo tra i passaggi.","alignmentCues":["Contate ad alta voce: passaggio, due, tre, quattro, cinque, sei.","Tenete i vostri lanci personali alla stessa altezza del passaggio.","Guardate il vostro partner, non le vostre mani."],"commonMistakes":["Perdere il conto e passare sul battito sbagliato.","Passare troppo corto, così il vostro partner deve afferrare."]},"pass-four-count":{"name":"Quattro-Conto","description":"Passate ogni quarto lancio, ogni lancio destro. Passate, lancio personale, lancio personale, lancio personale, poi passate di nuovo. Questo è il riscaldamento standard per il passaggio di club e la base per la maggior parte delle variazioni.","goodFor":"Il pattern di passaggio quotidiano; la maggior parte dei trucchi parte da qui.","alignmentCues":["Le mani destre passano insieme.","Tre lanci personali, poi il passaggio torna di nuovo."],"commonMistakes":["Ridurre i lanci personali per fare spazio al passaggio.","Ruotare le spalle per lanciare invece di usare l'avambraccio."]},"pass-three-count":{"name":"Tre-Conto","description":"Passate ogni terzo lancio, così i passaggi alternano le mani: destra, poi sinistra, poi destra. Ogni passaggio con la mano sinistra va dritto attraverso alla mano destra del vostro partner.","goodFor":"Passare con entrambe le mani e prendere i passaggi con entrambe.","alignmentCues":["I passaggi con la mano sinistra vanno dritti attraverso, come quelli con la destra.","Mantenete la stessa altezza del passaggio da entrambe le mani."],"commonMistakes":["Un passaggio debole con la mano sinistra che cade corto.","Incrociare il passaggio sinistro sulla mano sinistra del partner."]},"pass-two-count":{"name":"Due-Conteggio","description":"Ogni lancio con la mano destra è un passaggio e ogni lancio con la mano sinistra è un auto-lancio. Passaggio, auto-lancio, passaggio, auto-lancio. Il doppio dei passaggi rispetto a un quattro-conto con la stessa tecnica di piedi.","goodFor":"Ritmo di passaggio veloce e uniforme; la porta d'ingresso ai pattern con sette oggetti.","alignmentCues":["La mano destra passa, la mano sinistra auto-lancia.","Mantieni l'auto-lancio interno, sotto il passaggio in arrivo."],"commonMistakes":["Lasciare che gli auto-lanci scendano sempre più in basso.","Catturare i passaggi troppo vicino al corpo."]},"pass-left-two-count":{"name":"Due-Conteggio Mano Sinistra","description":"Il due-conto riflesso: ogni lancio con la mano sinistra è un passaggio, dritto verso la mano destra del partner, e la mano destra lancia auto-lanci.","goodFor":"Migliorare il passaggio con la mano debole.","alignmentCues":["Il passaggio sinistro va dritto, senza incrociare.","Stessa altezza e spinta dei passaggi con la mano destra."],"commonMistakes":["Passare corto dalla mano debole.","Ritornare per abitudine ai passaggi con la mano destra."]},"pass-ultimates":{"name":"Ultimates","description":"Ogni lancio è un passaggio. Le mani destra passano dritto verso le mani sinistre e le mani sinistre passano dritto verso le mani destre; nessuno lancia un auto-lancio. Le palle formano un flusso costante tra voi.","goodFor":"Precisione e ritmo nei passaggi sotto pressione.","alignmentCues":["Ogni lancio va attraverso: destra, sinistra, destra, sinistra.","Cattura e passaggio in un unico movimento fluido."],"commonMistakes":["Tenere una palla e interrompere il flusso.","I passaggi diventano più piatti man mano che aumenta il ritmo."]},"club-pass-four-count":{"name":"Quattro-Conteggio Club","description":"Il quattro-conto con i bastoni. Ogni passaggio è una singola rotazione lanciata dalla mano destra alla mano sinistra del partner, arrivando per prima la maniglia. Tre auto-lanci singoli tra i passaggi.","goodFor":"L'inizio standard di ogni sessione di passaggio con i bastoni.","alignmentCues":["Passa accanto all'anca destra con un movimento dritto in avanti.","Una singola rotazione: la maniglia dovrebbe atterrare nella mano del tuo partner."],"commonMistakes":["Eccessiva rotazione, così il passaggio arriva con il pomello per primo.","Passaggio attraverso il corpo verso destra del tuo partner."]},"club-pass-two-count":{"name":"Passaggio del bastone a due colpi","description":"Ogni lancio con la mano destra è un passaggio singolo e ogni lancio con la mano sinistra è un auto-lancio. Il ritmo fondamentale del passaggio di club.","goodFor":"Ritmo costante di passaggio di club.","alignmentCues":["Passaggio, auto-lancio, passaggio, auto-lancio, sui battiti pari.","Mantieni l'auto-lancio sinistro stretto e interno."],"commonMistakes":["Perdita della rotazione durante l'auto-lancio sinistro.","Passaggi che vagano a sinistra e a destra."]},"club-pass-three-count":{"name":"Passaggio del bastone a tre colpi","description":"I passaggi di club ogni terzo lancio, quindi alternano mano. I passaggi con la mano sinistra vanno dritti attraverso verso destra del tuo partner.","goodFor":"Passaggi di club dalla mano debole.","alignmentCues":["Stesso movimento da entrambe le mani.","Destra, sinistra, destra: contala."],"commonMistakes":["Passaggi con la mano sinistra con troppo poca rotazione.","Girare il corpo per il passaggio sinistro."]},"club-pass-doubles":{"name":"Passaggio del bastone a quattro colpi con doppie","description":"Un quattro-count in cui ogni passaggio è una doppia rotazione, lanciata più in alto in modo che atterri un battito dopo. Per fare spazio, la mano sinistra tiene il club per un battito dopo il passaggio invece di lanciarlo.","goodFor":"Il passaggio doppio, il primo passo verso il passaggio di sette club.","alignmentCues":["Un passaggio doppio è più alto e più lento: due giri completi.","Tieni il club sinistro durante il passaggio, poi continua."],"commonMistakes":["Lanciare il doppio come un singolo, così che rotoli eccessivamente.","Lanciare il club sinistro invece di tenerlo."]},"club-pass-ultimates":{"name":"Passaggio del bastone con ultimates","description":"Ogni lancio è un passaggio singolo di club, alternando destra e sinistra. Sei club scorrono tra voi senza auto-lanci.","goodFor":"Precisione nel passaggio di club a velocità massima.","alignmentCues":["Cattura e passaggio in un unico movimento.","Passaggi dritti: destra a sinistra, sinistra a destra."],"commonMistakes":["Passaggi che si spostano verso il centro e si scontrano.","Tenere un club e interrompere il flusso."]},"club-pass-seven-doubles":{"name":"Sette-Club Incrocio Doppio","description":"Sette club tra voi. La vostra mano destra passa un doppio incrociato alla mano destra del partner ogni due lanci, e la loro mano sinistra risponde un lancio dopo con un doppio incrociato alla vostra mano sinistra. I singoli riempiono gli spazi.","goodFor":"Primo schema a sette club, basato su doppie.","alignmentCues":["I vostri doppie incrociati vanno alla mano destra del partner.","Catturate il loro doppio con la vostra mano sinistra, subito dopo il vostro passaggio."],"commonMistakes":["Passare dritto invece di incrociare.","Doppie troppo basse per completare due giri."]},"staff-wheel-spin":{"name":"Giro a Ruota a Due Mani","description":"Tenete il bastone al centro con entrambe le mani, palme verso il basso, all'altezza del petto. Giratelo al vostro fianco come una ruota, passando la rotazione tra le mani, mantenendolo accanto al corpo.","goodFor":"Prima rotazione del bastone; sviluppa presa e rotazione del polso.","alignmentCues":["Il bastone rimane parallelo al vostro corpo, senza inclinarsi.","Presà morbida: lasciatelo rotolare attraverso le dita."],"props":["bastone"],"commonMistakes":["Stringere troppo, facendo fermare la rotazione.","Inclinare il piano in avanti."]},"staff-front-spin":{"name":"Mulino a Vento Anteriore","description":"Fate ruotare il bastone davanti a voi come una elica, nel piano verticale, passandolo dolcemente da mano a mano attorno al suo centro.","goodFor":"Aggiunge il piano verticale e il passaggio mano su mano.","props":["bastone"]},"staff-figure-8":{"name":"Intreccio a 8","description":"Fai ruotare il bastone nel piano della ruota sul lato destro, poi incrocialo sul lato sinistro e fai ruotare lì, tracciando un otto davanti a te.","goodFor":"Collega entrambi i lati del corpo; la spina dorsale del flusso del bastone.","alignmentCues":["Cambia lato quando le punte superano il pavimento.","Ruota un po' il busto ad ogni lato."],"props":["bastone"]},"staff-pass-through":{"name":"Passaggio","description":"Fai ruotare nel piano della parete ma lascia andare ogni mezzo giro: una mano lascia il bastone e l'altra lo prende al centro, così il bastone passa tra le mani.","goodFor":"Insegna il tempo di rilascio e presa.","props":["bastone"]},"staff-one-hand-spin":{"name":"Giro a una mano","description":"Fai ruotare il bastone davanti a te con una mano, facendolo rotolare sul dorso della mano e attraverso le dita. Pratica con entrambe le mani.","goodFor":"Forza delle dita e del polso; libera l'altra mano per i trucchi.","props":["bastone"]},"staff-helicopter":{"name":"Elicottero sopra la testa","description":"Solleva il bastone sopra la testa e fai ruotare in piano orizzontale con una mano, come le pale di un elicottero.","goodFor":"Introduce il piano orizzontale.","props":["bastone"]},"staff-butterfly":{"name":"Farfalla","description":"Fai ruotare davanti a te, poi piega il bastone dietro la spalla e riportalo in avanti, alternando davanti e dietro su ogni lato come ali.","goodFor":"Mobilità delle spalle e una transizione fluida da davanti a dietro.","props":["bastone"]},"staff-behind-back-pass":{"name":"Passaggio dietro la schiena","description":"Passa il bastone rotante da una mano all'altra dietro la schiena in fondo alla rotazione, poi riportalo in avanti.","goodFor":"Passaggi avvolti e spettacolari.","props":["bastone"]},"staff-isolation":{"name":"Isolamento del bastone","description":"Tieni il bastone vicino a un'estremità e fai girare la mano intorno al centro del bastone, in modo che il centro sembri rimanere fisso in aria mentre il bastone ruota attorno ad esso.","goodFor":"Lavoro sull'illusione e percorsi precisi della mano.","props":["bastone"]},"staff-antispin-flower":{"name":"Antispin a quattro petali","description":"Fai girare la mano in un senso mentre il bastone ruota nell'altro senso tre volte più velocemente, in modo che il bastone disegni un fiore a quattro petali.","goodFor":"Il fiore VTG caratteristico; controllo profondo del tempo.","props":["bastone"]},"staff-neck-roll":{"name":"Rotazione del collo","description":"Lascia cadere il bastone sulla parte posteriore delle spalle e lascia che rotoli lungo il collo fino all'altra mano. Inizia lentamente con un bastone imbottito.","goodFor":"Contatto con il bastone: il bastone si muove sul corpo senza mani.","avoidIf":["Dolore al collo."],"props":["bastone"]},"staff-reverse-wheel":{"name":"Rotazione inversa della ruota","description":"La rotazione della ruota in senso inverso: l'estremità anteriore del bastone si alza e viaggia all'indietro sopra la cima. Entrambe le mani rimangono al centro e lo fanno rotolare, esattamente come nella rotazione in avanti.","goodFor":"Equilibrio tra entrambi i sensi di rotazione in modo che ogni mossa successiva funzioni in entrambi i modi.","alignmentCues":["Stessa ruota piatta accanto a te, solo il senso cambia.","Guida con le nocche che rotolano all'indietro."],"props":["bastone"],"commonMistakes":["Il piano che si sposta attraverso il tuo corpo.","Ritornare alla rotazione in avanti senza accorgersene."]},"staff-reverse-front-spin":{"name":"Rotazione inversa frontale","description":"Una rotazione frontale a due mani che va nella direzione opposta. L'estremità superiore cade verso destra invece che verso sinistra.","goodFor":"Entrambi i sensi della rotazione frontale prima di passare o intrecciare.","alignmentCues":["Mantieni il bastone quadrato davanti al petto.","Le mani si scambiano nello stesso modo, solo al contrario."],"props":["bastone"],"commonMistakes":["Le estremità si inclinano verso di te.","Perdere il ritmo durante lo scambio delle mani."]},"staff-one-hand-wheel":{"name":"Girata a una mano","description":"Fai ruotare il bastone accanto a te nel piano della ruota con una sola mano, facendolo rotolare sul dorso della mano e attraverso le dita.","goodFor":"Controllo con una mano accanto al corpo: la base delle isolazioni a ruota e del doppio bastone.","alignmentCues":["Il bastone passa appena fuori dall'anca.","Il gomito rimane vicino alle costole."],"props":["bastone"],"commonMistakes":["L'estremità che sfiora la gamba.","Il polso che si blocca."]},"staff-wheel-pass":{"name":"Passaggio della ruota","description":"Una rotazione a ruota che cambia mano ogni mezzo giro. Ogni mano prende il bastone quando è in posizione orizzontale, lo porta in giro e lo passa.","goodFor":"Cambi di mano fluidi accanto al corpo.","alignmentCues":["Prendi in posizione orizzontale.","La mano libera aspetta vicino."],"props":["bastone"],"commonMistakes":["Afferrare prima che il bastone sia in posizione orizzontale.","Il piano che si allontana ad ogni passaggio."]},"staff-two-hand-helicopter":{"name":"Elicottero a due mani","description":"Il bastone ruota in piano sopra la testa con entrambe le mani, passando una mano sopra l'altra come un rotore.","goodFor":"Una prima occhiata delicata al piano del pavimento.","alignmentCues":["Braccia morbide, bastone appena sopra la testa.","Le mani si scambiano davanti al viso."],"props":["bastone"],"commonMistakes":["Il bastone inclinato in avanti.","Le spalle che si incurvano."]},"staff-overhead-pass":{"name":"Passaggio sopra la testa","description":"L'elicottero passa da una mano all'altra sopra la testa, ogni mano lo porta per mezzo giro.","goodFor":"Cambi di mano nel piano del pavimento.","alignmentCues":["Passa quando il bastone punta in avanti e indietro.","Mantieni i gomiti morbidi."],"props":["bastone"],"commonMistakes":["Lasciare cadere il bastone dietro la testa.","Afferrare troppo presto."]},"staff-one-hand-reverse":{"name":"Giro inverso con una mano","description":"Una rotazione frontale a una mano che gira nell'altro senso, rotolando prima sul lato del pollice.","goodFor":"Controllo a una mano in entrambe le direzioni.","alignmentCues":["Stessa piano, stessa velocità, invertito.","I dita si rilassano mentre il bastone rotola."],"props":["bastone"],"commonMistakes":["Tensione al polso.","La rotazione rallenta su una metà."]},"staff-reverse-helicopter":{"name":"Elicottero inverso","description":"L'elicottero a una mano che gira nell'altro senso sopra la testa.","goodFor":"Entrambe le direzioni sopra la testa.","alignmentCues":["Pale allineate.","La mano rimane sopra la fronte."],"props":["bastone"],"commonMistakes":["Inclinazione in avanti.","Braccio completamente dritto."]},"staff-extension":{"name":"Estensione","description":"Tieni il bastone vicino a un'estremità e lascia che descriva un grande cerchio intorno alla tua mano, che si muove appena. L'estremità lontana traccia un grande anello davanti a te.","goodFor":"Grandi forme e rotazione del polso necessaria per le isolazioni.","alignmentCues":["La mano è il centro del cerchio.","Ruota il polso, non agitare il braccio."],"props":["bastone"],"commonMistakes":["Oscillazione dalla spalla.","Il cerchio che si appiattisce in un ovale."]},"staff-wheel-extension":{"name":"Estensione con ruota","description":"Un'estensione accanto al corpo: il bastone descrive una grande ruota intorno alla mano all'altezza dell'anca.","goodFor":"Grandi cerchi nel piano della ruota.","alignmentCues":["Mantieni il cerchio fuori dalla gamba.","Il polso ruota, il braccio rimane fermo."],"props":["bastone"],"commonMistakes":["Toccare il piede.","Inclinarsi lontano dal bastone."]},"staff-floor-extension":{"name":"Estensione sopra la testa","description":"Un'estensione piatta sopra la testa: il bastone descrive un cerchio intorno alla mano sollevata come una lunga elica.","goodFor":"Allungamento sopra la testa e una forma drammatica nel piano del pavimento.","alignmentCues":["Mano sopra la testa.","L'elica rimane orizzontale."],"props":["bastone"],"commonMistakes":["Il bastone che scende dietro.","Braccio che si sposta in avanti."]},"staff-wheel-isolation":{"name":"Isolamento della ruota","description":"L'isolamento accanto al corpo: il centro del bastone rimane fisso mentre la mano ruota intorno ad esso.","goodFor":"Controllo dell'isolamento in un secondo piano.","alignmentCues":["Scegli un punto accanto all'anca come centro.","La mano si muove in un piccolo cerchio."],"props":["bastone"],"commonMistakes":["Centro che si sposta.","Piano che si inclina."]},"staff-floor-isolation":{"name":"Isolamento sopra la testa","description":"Un isolamento piano sopra la testa, il bastone che ruota attorno a un punto fisso mentre la mano circonda.","goodFor":"Isolamenti sopra la testa.","alignmentCues":["Punto fisso sopra di te.","Piccolo cerchio della mano."],"props":["bastone"],"commonMistakes":["Centro che si sposta.","Cerchio della mano che cresce."]},"staff-isolation-pass":{"name":"Passaggio di isolamento","description":"Un isolamento passato tra le mani ogni mezzo giro, in modo che il punto fisso rimanga fermo mentre le mani si scambiano.","goodFor":"Controllo dell'isolamento a due mani.","alignmentCues":["Passa in fondo al cerchio.","Mantieni il centro fisso durante il passaggio."],"props":["bastone"],"commonMistakes":["Centro che salta durante il passaggio.","Mani che si scontrano."]},"staff-antispin-3":{"name":"Antispin a Tre Petali","description":"Il cerchio della mano va in una direzione mentre il bastone ruota nell'altra, disegnando un fiore con tre petali.","goodFor":"Il primo fiore antispin.","alignmentCues":["Cerchio della mano lento e rotondo.","Il bastone ruota in senso opposto."],"props":["bastone"],"commonMistakes":["Petali irregolari.","Cerchio della mano che crolla."]},"staff-antispin-5":{"name":"Antispin a Cinque Petali","description":"Un fiore antispin più preciso con cinque petali, la mano che ruota più lentamente contro la rotazione.","goodFor":"Tempismo antispin preciso.","alignmentCues":["Conta i petali.","La mano si muove lentamente."],"props":["bastone"],"commonMistakes":["Petali che si fondono.","La mano che si affretta."]},"staff-wheel-antispin":{"name":"Antispin a Ruota","description":"Un fiore antispin disegnato accanto al corpo nel piano della ruota.","goodFor":"Fiori in un secondo piano.","alignmentCues":["Piano verticale.","Petali uniformi."],"props":["bastone"],"commonMistakes":["Piano inclinato.","Petali che si spostano in avanti."]},"staff-floor-antispin":{"name":"Antispin sopra la testa","description":"Un fiore antispin disegnato in piano sopra la testa.","goodFor":"Fiori sopra la testa.","alignmentCues":["Piano livellato.","Mano sopra la testa."],"props":["bastone"],"commonMistakes":["Inclinazione.","Petali irregolari."]},"staff-inspin-3":{"name":"Inspin a tre petali","description":"La mano descrive un cerchio nello stesso senso della rotazione, ma più lentamente, e il bastone traccia tre petali puntati verso l'interno.","goodFor":"Il fiore più morbido da imparare.","alignmentCues":["Mano e bastone ruotano nello stesso senso.","Cerchio della mano ampio e lento."],"props":["bastone"],"commonMistakes":["La mano accelera per eguagliare il bastone.","Petali sbilanciati."]},"staff-inspin-4":{"name":"Inspin a quattro petali","description":"Un fiore inspin con quattro petali verso l'interno.","goodFor":"Maggiore controllo dell'inspin.","alignmentCues":["Conta quattro petali.","Mano stabile."],"props":["bastone"],"commonMistakes":["Petali che si fondono.","Mano che si allontana."]},"staff-wheel-inspin":{"name":"Inspin a ruota","description":"Una rotazione interna a tre petali disegnata accanto al corpo.","goodFor":"Rotazioni interne nel piano della ruota.","alignmentCues":["Piano verticale.","Mano lenta."],"props":["bastone"],"commonMistakes":["Inclinazione.","Taglio della gamba."]},"staff-reverse-figure-8":{"name":"Figura 8 inversa","description":"La figura 8 girata nell'altro senso: il bastone sale davanti e scende dietro su ciascun lato.","goodFor":"Entrambe le direzioni della treccia.","alignmentCues":["Incrocio davanti al corpo.","Ogni lato verticale."],"props":["bastone"],"commonMistakes":["Collasso del piano all'incrocio.","Torso rigido."]},"staff-front-weave":{"name":"Intreccio frontale","description":"Una rotazione frontale che si sposta da un lato del corpo all'altro ad ogni giro, con il petto che ruota con essa.","goodFor":"Spostare la rotazione attraverso il corpo.","alignmentCues":["Il petto segue il bastone.","La rotazione rimane quadrata rispetto a te."],"props":["bastone"],"commonMistakes":["I piedi che ruotano troppo.","Inclinazione del piano all'incrocio."]},"staff-overhead-weave":{"name":"Intreccio sopra la testa","description":"Un elicottero a due mani che oscilla da un lato all'altro della testa ad ogni giro.","goodFor":"Intreccio nel piano del pavimento.","alignmentCues":["Lame livellate per tutto il tempo.","Il busto ruota con il bastone."],"props":["bastone"],"commonMistakes":["Abbassamento da un lato.","Testa in mezzo."]},"staff-fountain":{"name":"Fontana","description":"Un intreccio a tempo diviso nel piano della ruota: le estremità schizzano su e oltre su lati alterni come l'acqua di una fontana.","goodFor":"Tempo diviso accanto al corpo.","alignmentCues":["Le estremità salgono su lati alterni.","Mantieni la croce rapida."],"props":["bastone"],"commonMistakes":["Collasso in una figura a 8 piana.","Inclinazione del piano."]},"staff-reel":{"name":"Bobina","description":"Una figura a 8 che cambia mano ad ogni incrocio, il bastone che si avvolge da un lato all'altro.","goodFor":"Combinare intrecci e passaggi.","alignmentCues":["Passa all'incrocio.","Ogni lato in posizione verticale."],"props":["bastone"],"commonMistakes":["Afferrare in anticipo.","Busto rigido."]},"staff-wall-wheel-hybrid":{"name":"Ibrido Parete-Ruota","description":"Ad ogni giro la rotazione cambia tra il piano anteriore e il piano della ruota accanto a te, cambiando quando il bastone è verticale.","goodFor":"Cambiare piano senza fermarsi.","alignmentCues":["Cambia quando il bastone punta dritto verso l'alto.","Il polso ruota di un quarto."],"props":["bastone"],"commonMistakes":["Cambio al livello.","Perdita di velocità durante il cambio."]},"staff-floor-wall-hybrid":{"name":"Ibrido Parete-Pavimento","description":"La rotazione alterna tra davanti a te e sopra la testa, cambiando ogni volta che il bastone è orizzontale.","goodFor":"Collegare rotazioni frontali e elicotteri.","alignmentCues":["Cambia al livello.","Solleva il braccio in modo fluido."],"props":["bastone"],"commonMistakes":["Cambio quando verticale.","Gomito bloccato."]},"staff-floor-wheel-hybrid":{"name":"Ibrido Pavimento-Ruota","description":"Un elicottero che scende in una ruota accanto a te e risale di nuovo ad ogni giro.","goodFor":"L'intero insieme di cambi di piano.","alignmentCues":["Il braccio si alza e si abbassa in modo fluido.","Piani puliti."],"props":["bastone"],"commonMistakes":["Piano centrale confuso.","Diminuzione di velocità."]},"staff-under-leg-pass":{"name":"Passaggio sotto la Gamba","description":"Un passaggio che scende sotto la gamba destra sollevata ogni secondo passaggio.","goodFor":"Aggiungere le gambe ai movimenti di passaggio.","alignmentCues":["Solleva il ginocchio in alto verso il bastone.","Piega in vita con la schiena lunga e siediti sul ginocchio in piedi.","Ritorna su quando il bastone supera la gamba."],"props":["bastone"],"commonMistakes":["Curvare la schiena per raggiungere verso il basso invece di piegarsi in vita.","Lasciare il ginocchio basso così il bastone deve passare sotto.","Affrettare il passaggio sotto la gamba."]},"staff-reverse-behind-back":{"name":"Passaggio inverso dietro la schiena","description":"Il passaggio dietro la schiena che percorre l'altro lato del corpo, la rotazione avviene al contrario.","goodFor":"Portare il bastone intorno al corpo in entrambe le direzioni.","alignmentCues":["La mano dietro aspetta in basso.","Mantieni la rotazione dietro."],"props":["bastone"],"commonMistakes":["Perdere il piano dietro.","Fermare la rotazione."]},"staff-fishtail":{"name":"Coda di pesce","description":"Il bastone oscilla avanti e indietro sulla palma aperta come un pesce che agita la coda, senza mai girarsi completamente.","goodFor":"Controllo con la mano aperta e cambio di direzione della rotazione.","alignmentCues":["Ruota tra pollice e dita.","Piccoli movimenti del polso invertono l'oscillazione."],"props":["bastone"],"commonMistakes":["Stringere troppo.","Oscillazioni troppo ampie."]},"staff-wheel-fishtail":{"name":"Coda di pesce a ruota","description":"Un fishtail accanto al corpo nel piano della ruota.","goodFor":"Fishtails in un secondo piano.","alignmentCues":["Piano verticale.","Mano aperta."],"props":["bastone"],"commonMistakes":["Inclinazione.","Afferrare."]},"staff-steering-wheel":{"name":"Volante","description":"Gira il bastone mano dopo mano con palme piatte e aperte, come se stessi girando un grande volante davanti a te.","goodFor":"Mani rilassate e contatto con palme aperte.","alignmentCues":["Palme piatte, dita morbide.","Mano dopo mano in alto."],"props":["bastone"],"commonMistakes":["Afferrare invece di guidare.","Gomiti sporgenti."]},"staff-palm-spin":{"name":"Palm Spin","description":"Bilancia il centro del bastone sulla palma aperta e sollevata e lascialo ruotare come una elica.","goodFor":"Equilibrio e tocco leggero in alto.","alignmentCues":["Palma piatta e livellata.","Piccoli cerchi mantengono la rotazione."],"props":["bastone"],"commonMistakes":["Palma inclinata.","Spingere invece di spingere leggermente."]},"staff-hand-roll":{"name":"Rotolamento Manuale","description":"Il bastone rotola sul dorso della mano aperta e intorno al pollice senza essere afferrato.","goodFor":"Il primo vero rotolamento a contatto.","alignmentCues":["Mano aperta e morbida.","Lascia che il bastone faccia il lavoro."],"props":["bastone"],"commonMistakes":["Chiudere le dita.","Mano che si muove troppo."]},"staff-forearm-roll":{"name":"Rotazione avambraccio","description":"Rilascia la rotazione sul polso, lascia che il bastone giri sopra di esso, poi riprendilo nella rotazione della mano.","goodFor":"Spostare una rotazione sul braccio e ritorno.","alignmentCues":["Avambraccio livellato e fermo.","Apri la mano al momento dell'atterraggio."],"props":["bastone"],"commonMistakes":["Avambraccio inclinato.","Afferrare troppo presto."]},"staff-elbow-roll":{"name":"Rotazione gomito","description":"La rotazione si sposta sul gomito piegato, gira lì con la mano sollevata, e ritorna nella mano.","goodFor":"Controllo avanzato del contatto.","alignmentCues":["Avambraccio verticale.","Gomito fermo."],"props":["bastone"],"commonMistakes":["Gomito che scende.","Bastone che scivola via."]},"staff-shoulder-roll":{"name":"Rotazione spalla","description":"Una rotazione a ruota sollevata sulla parte superiore della spalla, dove gira accanto alla testa prima di ricadere nella mano.","goodFor":"Rotazioni di contatto in alto sul corpo.","alignmentCues":["Spalla sollevata leggermente.","Testa inclinata lontano."],"props":["bastone"],"commonMistakes":["Testa in mezzo.","Spalla che scende."]},"staff-chest-roll":{"name":"Rotolamento del petto","description":"Il bastone rotola a livello sul petto da una mano all'altra, poi di nuovo indietro.","goodFor":"Contatto corporeo sulla parte anteriore.","alignmentCues":["Petto sollevato.","Il bastone rimane a livello."],"props":["bastone"],"commonMistakes":["Petto che crolla.","Bastone che si inclina."]},"staff-angel-roll":{"name":"Rotolamento dell'angelo","description":"Le braccia si allargano e il bastone rotola sulla parte posteriore delle spalle e lungo entrambe le braccia da una mano all'altra.","goodFor":"Un rotolamento di contatto spettacolare.","alignmentCues":["Braccia a livello, palme verso l'alto.","Scapole strette."],"props":["bastone"],"commonMistakes":["Braccia che scendono.","Testa in avanti."]},"staff-toss":{"name":"Lancio del bastone","description":"Lascia andare una rotazione a una mano sul bastone, lascialo girare una volta in aria e riprendilo nella stessa rotazione.","goodFor":"Lasciare andare e riprendere un bastone che gira.","alignmentCues":["Lascia andare quando è a livello.","Riprendi al centro."],"props":["bastone"],"commonMistakes":["Lancio in avanti.","Cattura di un'estremità."]},"staff-double-toss":{"name":"Lancio doppio","description":"Un lancio più alto con due giri completi prima della cattura.","goodFor":"Altezza e controllo della rotazione in aria.","alignmentCues":["Più sollevamento, stessa rotazione.","Occhi al centro."],"props":["bastone"],"commonMistakes":["Eccessiva rotazione.","Deriva in avanti."]},"staff-flat-toss":{"name":"Lancio piatto","description":"Lancia un elicottero dritto in alto in modo che ruoti in piano in aria, poi catturalo sopra la testa.","goodFor":"Lancio nel piano del pavimento.","alignmentCues":["Rilascio orizzontale.","Cattura sopra la testa."],"props":["bastone"],"commonMistakes":["Inclinazione al rilascio.","Lancio dietro."]},"double-staff-same-time":{"name":"Bastone doppio contemporaneo","description":"Un bastone corto in ogni mano, entrambi che ruotano davanti a te nella stessa direzione e in sincronia.","goodFor":"Il primo schema con due bastoni.","alignmentCues":["Bastoni affiancati, uno leggermente in avanti.","Entrambe le mani alla stessa velocità."],"props":["due bastoni corti"],"commonMistakes":["Bastoni che si urtano.","Una mano in ritardo."]},"double-staff-split-time":{"name":"Tempo doppio staff","description":"Entrambe le bacchette ruotano nella stessa direzione, ma una è in ritardo di un quarto di giro, quindi una è verticale quando l'altra è orizzontale.","goodFor":"Tempo indipendente tra le mani.","alignmentCues":["Una verticale, una orizzontale.","Offset costante."],"props":["due bacchette corte"],"commonMistakes":["Ritornare al tempo simultaneo.","Scontro."]},"double-staff-wheels":{"name":"Ruote doppio staff","description":"Una rotazione a ruota su ciascun lato del corpo, entrambe che ruotano in avanti insieme.","goodFor":"Doppia bacchetta accanto al corpo.","alignmentCues":["Ogni ruota fuori dall'anca.","Stessa velocità."],"props":["due bacchette corte"],"commonMistakes":["Ruote che si inclinano verso l'interno.","Mani che si allontanano."]},"double-staff-split-wheels":{"name":"Ruote doppio staff split","description":"Ruote su entrambi i lati, con un quarto di giro di distanza, come gambe che camminano.","goodFor":"Tempo diviso accanto al corpo.","alignmentCues":["Una in alto, una orizzontale.","Offset costante."],"props":["due bacchette corte"],"commonMistakes":["Sincronizzazione.","Inclinazione."]},"double-staff-windmill":{"name":"Mulino a vento con doppio bastone","description":"Ruote su entrambi i lati che ruotano in direzioni opposte, come un mulino a vento visto di lato.","goodFor":"Direzioni opposte con le due mani.","alignmentCues":["Una in avanti, una indietro.","Velocità uniforme."],"props":["due bastoni corti"],"commonMistakes":["Entrambi che si spostano nella stessa direzione.","Velocità irregolare."]},"double-staff-reverse":{"name":"Doppio bastone inverso","description":"Giri frontali con tempo diviso e entrambi i bastoni che girano al contrario.","goodFor":"Entrambe le direzioni con due bastoni.","alignmentCues":["Mantenere lo spostamento.","Stesso piano per entrambi."],"props":["due bastoni corti"],"commonMistakes":["Scontro.","Perdita dello spostamento."]},"double-staff-helicopters":{"name":"Elicotteri con doppio bastone","description":"Un elicottero sopra ogni spalla, entrambi che ruotano in sincrono.","goodFor":"Doppio bastone sopra la testa.","alignmentCues":["Pale allineate.","Braccia rilassate."],"props":["due bastoni corti"],"commonMistakes":["Pale che si toccano.","Braccia che si affaticano e si abbassano."]},"double-staff-isolations":{"name":"Isolazioni con doppio bastone","description":"Un'isolazione in ogni mano contemporaneamente, entrambi i centri fissi uno accanto all'altro.","goodFor":"Due isolazioni contemporaneamente.","alignmentCues":["Due punti fissi.","Le mani ruotano insieme."],"props":["due bastoni corti"],"commonMistakes":["I centri che si allontanano.","Una mano che rimane indietro."]},"hoop-waist":{"name":"Hoop in vita","description":"Stai in piedi con un piede leggermente davanti all'altro. Tieni l'anello contro la parte bassa della schiena, lancialo intorno alla vita e fai pulsare l'addome in avanti e indietro (non in cerchi) ogni volta che l'anello passa davanti a te.","goodFor":"La prima abilità con l'anello; sviluppa il ritmo del tronco.","modifications":["Usa un anello più grande e pesante: gira più lentamente."],"alignmentCues":["Oscilla avanti e indietro, non in cerchi.","Spingi sull'anello mentre passa davanti all'addome."],"props":["anello"],"commonMistakes":["Muovere i fianchi come una danzatrice di hula hoop.","Un anello troppo piccolo o leggero."]},"hoop-hand-spin":{"name":"Rotazione a mano","description":"Tieni l'anello davanti a te con la mano all'interno, pollice in alto. Spingilo in una rotazione attorno alla parte palmare della mano, mantenendo l'anello piatto davanti a te.","goodFor":"Fondamento per l'anello fuori dal corpo.","props":["anello"]},"hoop-chest":{"name":"Hoop sul petto","description":"Alza le braccia sopra la testa e fai girare l'anello intorno al petto, oscillando la gabbia toracica avanti e indietro mantenendo i fianchi fermi.","goodFor":"Isola la gabbia toracica e sviluppa il controllo della parte superiore del corpo.","props":["anello"]},"hoop-lasso":{"name":"Lasso","description":"Tieni l'anello sopra la testa e fai girare in cerchio sopra la testa come un lasso, facendo ruotare l'anello intorno alla mano.","goodFor":"Controllo del piano del pavimento sopra la testa.","props":["anello"]},"hoop-wedgie":{"name":"Wedgie","description":"Fai girare l'anello nel piano della parete e afferralo nella piega tra pollice e dita, lasciandolo rotolare e oscillare lì prima di farlo girare di nuovo.","goodFor":"Controllo della presa e transizione fluida.","props":["anello"]},"hoop-knees":{"name":"Knee Hooping","description":"Con i piedi uniti, mantieni l'anello che gira attorno alle ginocchia pulsando avanti e indietro con le ginocchia.","goodFor":"Hooping della parte inferiore del corpo e pratica dell'ascensore.","props":["anello"]},"hoop-pass":{"name":"Passaggio da Mano a Mano","description":"Fai girare l'anello davanti a te e passalo da una mano all'altra ad ogni giro, mantenendo il piano stabile.","goodFor":"Collegamenti di trucchi fuori dal corpo su entrambi i lati.","props":["anello"]},"hoop-isolation":{"name":"Isolamento con Anello","description":"Muovi la mano intorno all'anello in modo che il suo centro rimanga fisso nell'aria davanti a te mentre l'anello gira attorno a quel punto.","goodFor":"L'illusione classica dell'anello.","props":["anello"]},"hoop-escalator":{"name":"Escalator","description":"Mantieni l'anello in rotazione mentre lo fai scendere dalla vita alle ginocchia e risalire al petto, una zona del corpo per ogni barra.","goodFor":"Unisce ogni zona del corpo in un flusso continuo.","props":["anello"]},"hoop-neck":{"name":"Hoop Isolation","description":"Inclina leggermente la testa e lascia che un anello leggero ruoti intorno al collo, guidato da piccoli impulsi della testa e delle spalle.","goodFor":"Una mossa spettacolare che allena piccole pulsazioni precise.","avoidIf":["Dolore al collo."],"props":["anello"]},"hoop-reverse-waist":{"name":"Hoop inverso in vita","description":"Fare l'anello intorno alla vita nell'altro senso. Cambia il piede che è davanti, lancia l'anello nella nuova direzione e mantieni la stessa pulsazione avanti-indietro.","goodFor":"Equilibrare entrambe le direzioni in modo che ogni mossa successiva funzioni in entrambi i modi.","alignmentCues":["Cambia il piede davanti.","Stessa pulsazione, nuova direzione."],"props":["anello"],"commonMistakes":["Ruotare i fianchi.","Abbandonare troppo presto il lato debole."]},"hoop-hips":{"name":"Hoop in vita","description":"Lascia che l'anello scivoli dalla vita alle ossa dei fianchi e mantienilo lì con una pulsazione più bassa e più piccola dal bacino.","goodFor":"Controllo sotto la vita e un passo verso le ginocchia.","alignmentCues":["Ginocchia morbide.","Pulsazione dal bacino, non dalla pancia."],"props":["anello"],"commonMistakes":["Lasciarlo scivolare più in basso.","Pulsazione troppo grande."]},"hoop-thighs":{"name":"Hoop in coscia","description":"Con i piedi vicini, mantieni l'anello che gira intorno alle cosce superiori usando un rapido e piccolo rimbalzo del ginocchio.","goodFor":"Ritmo delle gambe e il collegamento tra fianchi e ginocchia.","alignmentCues":["Piedi uniti.","Rimbalzi rapidi e piccoli."],"props":["anello"],"commonMistakes":["Piedi separati.","Saltellare troppo lentamente."]},"hoop-reverse-chest":{"name":"Hoop inverso sul petto","description":"Il cerchio ruota in direzione opposta, braccia alzate e costole che guidano il movimento.","goodFor":"Entrambe le direzioni in alto sul corpo.","alignmentCues":["Braccia in alto e fuori strada.","Cassa toracica che oscilla avanti e indietro."],"props":["cerchio"],"commonMistakes":["Braccia che scendono nel cerchio.","Coscia che fa il lavoro."]},"hoop-shoulder":{"name":"Hoop sulla spalla","description":"Il cerchio ruota attorno alle spalle e al torace superiore con le braccia alzate sopra la testa.","goodFor":"Il cerchio sul corpo superiore.","alignmentCues":["Braccia dritte verso l'alto.","Piccole pulsazioni delle spalle."],"props":["cerchio"],"commonMistakes":["Braccia che si piegano verso l'interno.","Il cerchio che scivola verso il petto."]},"hoop-arm":{"name":"Hoop sul braccio","description":"Alza un braccio dritto verso l'alto e fai ruotare il cerchio attorno all'avambraccio, la mano traccia un piccolo cerchio per mantenerlo in movimento.","goodFor":"Il cerchio sul membro e la sensazione di lasso con braccio alzato.","alignmentCues":["Braccio dritto, mano sopra la testa.","Piccolo cerchio della mano."],"props":["cerchio"],"commonMistakes":["Circondare tutto il braccio.","Braccio che si sposta in avanti."]},"hoop-elbow":{"name":"Rotazione del gomito","description":"Il braccio è tenuto di lato, piegato al gomito, e l'anello ruota attorno alla articolazione del gomito.","goodFor":"Controllo del membro lontano dal corpo.","alignmentCues":["Braccio superiore livellato.","Piccoli cerchi al gomito."],"props":["anello"],"commonMistakes":["Gomito che scende.","Anello che scivola sulla spalla."]},"hoop-foot":{"name":"Leg Hooping","description":"Solleva una gamba e fai ruotare l'anello attorno alla tibia, con il piede che traccia piccoli cerchi per mantenerlo in movimento.","goodFor":"Equilibrio e controllo della gamba.","alignmentCues":["Gamba di appoggio forte.","Piccoli cerchi con il piede."],"props":["anello"],"commonMistakes":["Perdita di equilibrio.","Cerchi troppo grandi."]},"hoop-full-escalator":{"name":"Escalatore completo","description":"Fai scorrere l'anello dalla parte delle ginocchia fino alle spalle e poi torna indietro senza fermarti.","goodFor":"L'intero corpo in un movimento continuo.","alignmentCues":["Aumenta il ritmo mentre sali.","Braccia che si alzano mentre l'anello sale."],"props":["anello"],"commonMistakes":["Perdita di controllo durante il passaggio da vita a petto.","Braccia che intralciano."]},"hoop-vortex":{"name":"Vortex","description":"Lancia l'anello sopra la testa, lascialo scendere intorno alle spalle e al petto, e riprendilo in vita in una discesa a spirale.","goodFor":"Collegare il giocolaggio fuori dal corpo e dentro il corpo.","alignmentCues":["Mantieni la velocità del lasso mentre lo rilasci.","Inizia a pulsare prima che cada."],"props":["anello"],"commonMistakes":["Rilasciare troppo lentamente.","L'anello che si inclina durante la discesa."]},"hoop-duck-out":{"name":"Duck Out","description":"Fai salire l'anello dalla vita oltre il petto, afferralo sopra la testa in un lasso, poi portalo giù in una rotazione a mano davanti.","goodFor":"Allontanarsi dal corpo in modo pulito.","alignmentCues":["Solleva con le costole.","Afferra sopra la testa sul ritmo."],"props":["anello"],"commonMistakes":["Afferrare troppo presto.","Perdere velocità."]},"hoop-drop-in":{"name":"Drop In","description":"Da un lasso sopra la testa, lascia andare e riprendi l'anello sul petto, poi lascialo cadere in vita.","goodFor":"Il modo più semplice per tornare dal corpo al corpo.","alignmentCues":["Braccia in alto mentre scende.","Riprendi con un pulsare."],"props":["anello"],"commonMistakes":["Fallo cadere troppo velocemente.","Braccia che si stringono."]},"hoop-chest-lift":{"name":"Chest Lift","description":"Solleva l'anello dalla vita al petto e indietro con un impulso più forte.","goodFor":"Spostamento tra zone del corpo.","alignmentCues":["Impulso più veloce per salire.","Braccia in alto presto."],"props":["anello"],"commonMistakes":["Perderlo durante il cambio.","Braccia che cadono."]},"hoop-knee-drop":{"name":"Knee Drop","description":"Lascia che l'anello scenda dalla vita alle ginocchia, tienilo lì, poi rimbalzalo di nuovo in alto fino alla vita.","goodFor":"Transizioni della parte inferiore del corpo.","alignmentCues":["Piedi uniti per le ginocchia.","Rimbalzo più grande per salire."],"props":["anello"],"commonMistakes":["Piedi divaricati.","Perderlo durante la salita."]},"hoop-side-spin":{"name":"Side Spin","description":"Una rotazione della mano accanto al corpo nel piano della ruota, l'anello che gira come una ruota accanto a te.","goodFor":"Il piano della ruota per gli anelli.","alignmentCues":["Anello piatto accanto a te.","Mano all'altezza dell'anca."],"props":["anello"],"commonMistakes":["Anello che colpisce la gamba.","Piano inclinato."]},"hoop-reverse-hand-spin":{"name":"Giro a mano inverso","description":"La rotazione della mano che gira nell'altro senso davanti a te.","goodFor":"Entrambe le direzioni fuori dal corpo.","alignmentCues":["Stesso piano, altra direzione.","Il pollice rimane in alto."],"props":["anello"],"commonMistakes":["Oscillazioni.","Rallentamento."]},"hoop-reverse-lasso":{"name":"Lasso inverso","description":"Il lasso sopra la testa che gira nell'altra direzione.","goodFor":"Entrambe le direzioni del lasso.","alignmentCues":["Anello livellato.","Piccolo cerchio della mano."],"props":["anello"],"commonMistakes":["Inclinazione.","Grandi cerchi del braccio."]},"hoop-palm-spin":{"name":"Rotazione palmo sopra la testa","description":"Una rotazione della mano sollevata sopra la testa sulla palma aperta, l'anello che gira di fronte a te.","goodFor":"Rotazioni in alto fuori dal corpo.","alignmentCues":["Braccio lungo.","Palma aperta."],"props":["anello"],"commonMistakes":["L'anello che si allontana dietro.","Braccio piegato."]},"hoop-coin-flip":{"name":"Lancio della moneta","description":"Bilancia l'anello in verticale sulle punte delle dita e fai un colpetto in modo che ruoti attorno al suo centro verticale come una moneta lanciata.","goodFor":"Controllo fine delle dita e un nuovo asse.","alignmentCues":["Anello verticale.","Fai scattare, poi lascialo girare."],"props":["anello"],"commonMistakes":["Anello che si inclina.","Afferrare."]},"hoop-cateye":{"name":"Occhio di gatto","description":"Tieni l'anello sul lato del bordo e fai oscillare intorno al suo centro verticale, in modo che dalla parte anteriore si restringa e si allarghi come un occhio di gatto.","goodFor":"Movimenti di oscillazione e un'illusione sorprendente.","alignmentCues":["Mano ferma sul bordo.","Oscilla in modo uniforme."],"props":["anello"],"commonMistakes":["Mano in movimento.","Oscillazione irregolare."]},"hoop-weave":{"name":"Intreccio","description":"Una rotazione della mano che scorre da un lato all'altro del corpo, con il piano che ruota con il torace.","goodFor":"Spostare la rotazione attraverso il corpo.","alignmentCues":["Il torace ruota con esso.","Continua a farlo girare."],"props":["anello"],"commonMistakes":["Fermarsi a metà.","Inclinazione."]},"hoop-halo":{"name":"Aureola","description":"L'anello orbita in piano attorno alla testa, la mano sollevata che percorre il bordo sopra di te.","goodFor":"Orbite a livello della testa.","alignmentCues":["Anello livellato attorno alla testa.","Mano vicina alla testa."],"props":["anello"],"commonMistakes":["L'anello che scende in avanti.","Abbassare la testa."]},"hoop-toss":{"name":"Lancio dell'anello","description":"Lancia una rotazione della mano dritta in alto, continuando a girare, e riprendila nella rotazione.","goodFor":"Liberare e riprendere un anello in rotazione.","alignmentCues":["Lancia dritto in alto.","Riprendi dove l'hai lanciato."],"props":["anello"],"commonMistakes":["Lanciare in avanti.","Afferrare il bordo in ritardo."]},"hoop-boomerang":{"name":"Boomerang","description":"Lancia l'anello verso il basso e lontano con una rotazione all'indietro in modo che rotoli sul pavimento e torni da te.","goodFor":"Rotazione all'indietro e un divertente trucco sul pavimento.","alignmentCues":["Fai scattare il polso all'indietro.","Lancia basso e in avanti."],"props":["anello"],"commonMistakes":["Rotazione all'indietro insufficiente.","Lanciare troppo in alto."]},"hoop-jump-through":{"name":"Salto attraverso","description":"Tieni l'anello con entrambe le mani come una corda per saltare: fallo passare sopra la testa e salta attraverso mentre passa sotto i piedi.","goodFor":"Ritmo, coordinazione e un impulso cardio.","alignmentCues":["Piccolo salto, ginocchia morbide.","Fai oscillare dai polsi."],"props":["cerchio"],"commonMistakes":["Saltare troppo presto.","Grandi movimenti delle braccia."]},"hoop-behind-back-pass":{"name":"Passaggio dietro la schiena","description":"Una rotazione della mano passata dietro la schiena da una mano all'altra, poi di nuovo attraverso la parte anteriore.","goodFor":"Passaggio tutto intorno al corpo.","alignmentCues":["Mantienilo in rotazione dietro.","La mano in attesa si allunga indietro."],"props":["cerchio"],"commonMistakes":["Il cerchio si ferma dietro.","Il cerchio colpisce la schiena."]},"hoop-under-leg-pass":{"name":"Passaggio sotto la gamba","description":"Un passaggio da mano a mano che scende sotto la gamba destra sollevata.","goodFor":"Aggiungere le gambe ai passaggi.","alignmentCues":["Solleva il ginocchio in alto verso il cerchio.","Piega ai fianchi con la schiena lunga e siediti sul ginocchio in piedi.","Rialzati mentre il cerchio esce dall'altro lato."],"props":["cerchio"],"commonMistakes":["Arrotondare la schiena per raggiungere verso il basso invece di piegarsi ai fianchi.","Lasciare il ginocchio basso così il cerchio colpisce la coscia.","Affrettarsi."]},"hoop-corkscrew":{"name":"Spirale","description":"Un lasso che si avvolge verso il basso fino ai fianchi e poi risale, il cerchio traccia una spirale.","goodFor":"Muovere un lasso attraverso i livelli.","alignmentCues":["Piega le ginocchia per scendere.","Mantieni l'anello orizzontale."],"props":["anello"],"commonMistakes":["L'anello inclinato verso il basso.","La rotazione rallenta."]},"hoop-barrel-roll":{"name":"Rotazione barile","description":"Una rotazione della mano che percorre una volta intorno al corpo ogni quattro battiti, l'anello che rotola intorno a te.","goodFor":"Flusso completo fuori dal corpo.","alignmentCues":["Ruota con l'anello.","Continua a ruotare per tutto il tempo."],"props":["anello"],"commonMistakes":["L'anello che si impiglia nel corpo.","La rotazione si blocca dietro."]},"hoop-chest-roll":{"name":"Rotazione petto","description":"Lascia una rotazione della mano sul petto e lascia che rotoli fino all'altra mano.","goodFor":"La prima rotazione dell'anello.","alignmentCues":["Petto sollevato.","Braccia aperte mentre rotola."],"props":["anello"],"commonMistakes":["Petto che crolla.","Afferrare troppo presto."]},"hoop-back-roll":{"name":"Rotazione schiena","description":"L'anello rotola sulla parte posteriore delle spalle da una mano all'altra.","goodFor":"Rotazioni dietro il corpo.","alignmentCues":["Scapole unite.","Testa leggermente in avanti."],"props":["anello"],"commonMistakes":["Curvatura della schiena.","Anello che cade."]},"hoop-isopop":{"name":"Iso Pop","description":"Un'isolazione che si ferma e fa uscire l'anello di lato ogni due battiti prima di continuare.","goodFor":"Accenti e pause nelle isolazioni.","alignmentCues":["Fai il pop sul battito.","L'isolazione rimane pulita tra i pop."],"props":["anello"],"commonMistakes":["Pop troppo grandi.","Centro che vaga."]},"hoop-wheel-isolation":{"name":"Isolamento laterale","description":"Un'isolazione accanto al corpo nel piano della ruota.","goodFor":"Isolazioni in un secondo piano.","alignmentCues":["Centro fisso accanto a te.","La mano ruota intorno ad esso."],"props":["anello"],"commonMistakes":["Centro che si allontana.","Inclinazione."]},"hoop-floor-isolation":{"name":"Isolamento piano","description":"Un'isolazione con l'anello disteso a terra, il centro fisso mentre la mano ruota.","goodFor":"Isolazioni nel piano del pavimento.","alignmentCues":["Anello livellato.","Centro fisso."],"props":["anello"],"commonMistakes":["Inclinazione.","Centro che si sposta."]},"doubles-hand-spins":{"name":"Giri a doppia mano","description":"Un anello in ogni mano, entrambi che ruotano davanti a te in immagine speculare.","goodFor":"La prima mossa a doppio anello.","alignmentCues":["Anelli uno accanto all'altro.","Coincidenza della velocità."],"props":["due anelli"],"commonMistakes":["Collisione degli anelli.","Uno che rallenta."]},"doubles-offset-spins":{"name":"Giri a doppia mano con offset","description":"Rotazioni a doppio anello nella stessa direzione, con mezzo giro di distanza.","goodFor":"Tempo indipendente tra le mani.","alignmentCues":["Uno in alto mentre l'altro è in basso.","Stessa direzione."],"props":["due anelli"],"commonMistakes":["Sincronizzazione.","Collisione."]},"doubles-side-spins":{"name":"Giri a doppia mano laterali","description":"Un anello che ruota accanto a ciascun fianco nel piano della ruota.","goodFor":"Doppio anello nel piano della ruota.","alignmentCues":["Anelli verticali.","Lontano dalle gambe."],"props":["due anelli"],"commonMistakes":["Colpire le gambe.","Inclinazione."]},"doubles-floor-spins":{"name":"Lassos doppi","description":"Un lasso sopra la testa in ogni mano, immagine speculare.","goodFor":"Doppie sopra la testa.","alignmentCues":["Entrambi allo stesso livello.","Piccoli cerchi con le mani."],"props":["due cerchi"],"commonMistakes":["Cerchi che si toccano.","Braccia che si affaticano."]},"doubles-wedgies":{"name":"Wedgies doppi","description":"Un wedgie in ogni mano, entrambi i cerchi che oscillano nelle pieghe del pollice.","goodFor":"Movimenti oscillanti doppi.","alignmentCues":["Pollici fuori.","Oscillazioni uniformi."],"props":["due cerchi"],"commonMistakes":["Cerchi che si scontrano.","Tempo irregolare."]},"doubles-coin-flips":{"name":"Capovolgi monete doppi","description":"Un lancio di moneta su ogni mano contemporaneamente.","goodFor":"Controllo dito doppio.","alignmentCues":["Entrambi in posizione verticale.","Scatto insieme."],"props":["due cerchi"],"commonMistakes":["Inclinazione.","Scontro."]},"doubles-isolations":{"name":"Isolazioni doppie","description":"Un'isolazione in ogni mano, entrambi i centri fissi uno accanto all'altro.","goodFor":"Due isolazioni contemporaneamente.","alignmentCues":["Due centri fermi.","Le mani ruotano insieme."],"props":["due cerchi"],"commonMistakes":["Centri che si allontanano.","I cerchi che si scontrano."]},"doubles-toss":{"name":"Lancio doppio","description":"Lancia in alto entrambi i cerchi in rotazione insieme e riprendili in rotazione doppia.","goodFor":"Rilasci doppio.","alignmentCues":["Lancia dritto in alto insieme.","Riprendi dove hai lanciato."],"props":["due cerchi"],"commonMistakes":["Lanci disuguali.","Avanzamento in avanti."]},"doubles-waist-and-hand":{"name":"Rotazione della cintura e della mano","description":"Mantieni un cerchio in rotazione in vita mentre fai ruotare un secondo cerchio nella mano sinistra.","goodFor":"Dividere l'attenzione tra corpo e mano.","alignmentCues":["I fianchi mantengono il loro ritmo.","La rotazione della mano davanti al cerchio del corpo."],"props":["due cerchi"],"commonMistakes":["Il cerchio del corpo rallenta.","Il cerchio della mano che colpisce il cerchio del corpo."]},"doubles-chest-and-hand":{"name":"Rotazione del petto e della mano","description":"Circondare il torace con un braccio alzato mentre l'altra mano fa girare un secondo cerchio.","goodFor":"Circondare in alto con un trucco con la mano.","alignmentCues":["Un braccio in alto.","Le costole guidano il cerchio del corpo."],"props":["due cerchi"],"commonMistakes":["Il braccio che scende nel cerchio del torace.","Perdere il ritmo."]},"doubles-waist-and-lasso":{"name":"Anello in vita e laccio","description":"Cerchio in vita in basso, laccio sopra la testa: due cerchi a due livelli contemporaneamente.","goodFor":"Due livelli di circondare insieme.","alignmentCues":["I fianchi pulsano, la mano descrive cerchi.","Livello del laccio sopra la testa."],"props":["due cerchi"],"commonMistakes":["Il cerchio del corpo che scende.","Inclinazione del laccio."]},"poi-one-hand-spin":{"name":"Rotazione in avanti con un Poi","description":"Un poi che gira davanti a te come l'ago di un orologio, la testa che sfiora il tuo fianco. Il polso descrive un piccolo cerchio costante e il cavo rimane teso.","goodFor":"Sentire la tensione del cavo e il ritmo di un giro per battito.","alignmentCues":["Piccoli cerchi del polso, grandi cerchi del poi.","Mantenere il cerchio piatto davanti a te, come un pannello di finestra."],"props":["un poi"],"commonMistakes":["Oscillare dalla spalla.","Lasciare che il cerchio si inclini verso di te."]},"poi-wall-spin":{"name":"Rotazione in avanti contro il muro","description":"Entrambi i poi che ruotano insieme davanti a te, uno accanto a ogni spalla, fianco a fianco come due ruote su un asse. Il primo movimento con due poi.","goodFor":"Due poi in sincronia tra loro e con il ritmo.","alignmentCues":["Entrambe le teste raggiungono la cima contemporaneamente.","Mani a distanza di spalla."],"props":["una coppia di poi"],"commonMistakes":["Un poi che rimane indietro rispetto all'altro.","Cerchi che si avvicinano l'uno all'altro."]},"poi-reverse-wall-spin":{"name":"Rotazione Indietro a Parete","description":"La rotazione a muro invertita: le teste salgono lungo l'esterno e scendono lungo il centro.","goodFor":"Entrambe le direzioni prima di intrecci e fiori.","alignmentCues":["Stessi piani piatti, cambia solo la direzione.","Guida i cerchi con il dorso del polso."],"props":["una coppia di poi"],"commonMistakes":["Ritornare alla rotazione in avanti.","Piani inclinati in avanti."]},"poi-split-time":{"name":"Rotazione a Parete con Tempo Diviso","description":"Entrambi i poi ruotano nella stessa direzione, ma con mezzo giro di distacco: quando uno è in alto, l'altro è in basso. Il timing di ogni intreccio si basa su questo.","goodFor":"Tempo indipendente nelle due mani.","alignmentCues":["Su, giù, su, giù: le teste si alternano.","Conta il momento in cui ogni poi raggiunge la cima sul ritmo e sul 'e'."],"props":["una coppia di poi"],"commonMistakes":["Ritornare al tempo simultaneo.","Mani che si muovono a velocità diverse."]},"poi-butterfly":{"name":"Farfalla","description":"Mani vicine davanti, i poi ruotano in direzioni opposte in modo che si incontrino in alto e in basso come le ali di una farfalla.","goodFor":"Tempo in direzioni opposte e mani vicine.","alignmentCues":["Le teste si toccano in alto e in basso.","Caviglie quasi a contatto."],"props":[" coppia di poi"],"commonMistakes":["Teste che si scontrano quando i piani si incrociano.","Mani che si allontanano."]},"poi-reverse-butterfly":{"name":"Farfalla inversa","description":"La farfalla con entrambe le ali che girano in senso opposto: le teste salgono insieme al centro e scendono sui lati.","goodFor":"Equilibrare la farfalla in entrambe le direzioni.","alignmentCues":["Incontro al centro in alto.","Stesse mani vicine come nella farfalla in avanti."],"props":[" coppia di poi"],"commonMistakes":["Teste che si intrecciano in alto.","Una ala che penzola."]},"poi-chase-the-sun":{"name":"Inseguire il sole","description":"Mani unite davanti e tempismo diviso: le due teste seguono l'una l'altra in un grande cerchio, sempre mezzo giro di distanza.","goodFor":"Tempismo diviso con le mani vicine, pronte per i passaggi.","alignmentCues":["Una testa sempre opposta all'altra.","Mani che si muovono come una sola."],"props":[" coppia di poi"],"commonMistakes":["Teste che si avvicinano l'una all'altra.","Mani che si separano."]},"poi-wheels":{"name":"Ruote in avanti","description":"Entrambi i poi che girano accanto a te come le ruote di una bicicletta, le parti superiori che rotolano in avanti.","goodFor":"Il piano della ruota, accanto al corpo.","alignmentCues":["I cerchi corrono paralleli ai tuoi lati.","Gomiti morbidi e vicini."],"props":[" coppia di poi"],"commonMistakes":["I poi che sfiorano le gambe.","Le ruote che si allargano verso l'esterno."]},"poi-reverse-wheels":{"name":"Ruote all'indietro","description":"Le ruote che rotolano all'indietro accanto a te, le teste che salgono davanti e scendono dietro.","goodFor":"Entrambe le direzioni nel piano della ruota.","alignmentCues":["Stesse ruote, invertite.","Spalle basse e rilassate."],"props":[" coppia di poi"],"commonMistakes":["Le ruote che si allontanano dalla parte posteriore del corpo.","Caviglie rigide."]},"poi-fountain":{"name":"Fontana","description":"Ruote in tempo diviso: un poi sale mentre l'altro scende, come l'acqua in una fontana accanto a te.","goodFor":"Tempo diviso nel piano della ruota, la base della tessitura camminata.","alignmentCues":["Uno su, uno giù.","Mantieni il ritmo uniforme tra le mani."],"props":[" coppia di poi"],"commonMistakes":["Il tempo che collassa in tempo simultaneo.","Le ruote che si inclinano verso l'interno."]},"poi-opposite-wheels":{"name":"Ruote opposte","description":"Una ruota rotola in avanti mentre l'altra rotola indietro. Le teste si incrociano in alto e in basso.","goodFor":"Coordinazione con le mani che girano in direzioni opposte.","alignmentCues":["Entrambe raggiungono la cima insieme.","Ogni mano mantiene la propria direzione."],"props":[" coppia di poi"],"commonMistakes":["Entrambe le mani che cambiano direzione nello stesso senso.","Una ruota che si restringe."]},"poi-overhead":{"name":"Rotazione aerea sul pavimento","description":"Entrambi i poi che descrivono cerchi orizzontali sopra la testa come pale di elicottero, pendendo leggermente più in basso ai lati mentre girano.","goodFor":"Il piano del pavimento e le spalle stabili sopra la testa.","alignmentCues":["Mani appena sopra la testa.","Lascia che il piano dei poi si estenda; non forzare."],"props":[" coppia di poi"],"commonMistakes":["Spalle che si incurvano.","Poi che si abbassano davanti."]},"poi-low-floor":{"name":"Rotazione a bassa altezza sul pavimento","description":"Il piano del pavimento portato alle anche: i poi descrivono cerchi all'altezza della vita accanto a te.","goodFor":"Il piano del pavimento basso utilizzato in ibridi pavimento-muro.","alignmentCues":["Mani ai lati delle anche.","Mantieni i cerchi orizzontali."],"props":[" coppia di poi"],"commonMistakes":["Poi che colpiscono le cosce.","Inclinazione in avanti."]},"poi-three-beat-weave":{"name":"Intreccio a tre battiti","description":"La mossa caratteristica dei poi: i poi a tempo diviso che oscillano da un lato all'altro del corpo, le braccia che si incrociano e si disincrociano mentre i piani cambiano lato.","goodFor":"La mossa fluida da cui ogni manipolatore di poi sviluppa il suo stile.","alignmentCues":["Ruota le spalle con la trama.","I piani si inclinano leggermente verso ciascun lato."],"props":[" coppia di poi"],"commonMistakes":["Mani che rimangono al centro.","Poi che si colpiscono a vicenda al punto di incrocio."]},"poi-reverse-three-beat-weave":{"name":"Intreccio a Tre Battiti Inverso","description":"Intreccio a tre battiti con entrambi i poi che ruotano in senso inverso. Le braccia si incrociano sopra invece che sotto.","goodFor":"Intrecci in entrambe le direzioni.","alignmentCues":["Stesso modello da un lato all'altro, rotazione inversa.","Mantenere le mani all'altezza del petto."],"props":[" coppia di poi"],"commonMistakes":["Teste che si scontrano in alto.","Intreccio che si restringe su un lato."]},"poi-two-beat-weave":{"name":"Intreccio a Due Battiti","description":"Un intreccio più veloce che cambia lato ad ogni battito. Incroci più rapidi lo rendono più movimentato e compatto.","goodFor":"Cambi di lato rapidi.","alignmentCues":["Giri delle spalle più piccoli e veloci.","Incrocio dei polsi vicino al petto."],"props":[" coppia di poi"],"commonMistakes":["Ritornare al tempo a tre battiti.","Perdere la divisione."]},"poi-five-beat-weave":{"name":"Intreccio a Cinque Battiti","description":"Un intreccio più lungo e ampio: i poi trascorrono più giri su ogni lato prima di incrociare di nuovo.","goodFor":"Mantenere la forma dell'intreccio su frasi più lunghe.","alignmentCues":["Giri delle spalle ampi.","Mantenere gli incroci fluidi."],"props":[" coppia di poi"],"commonMistakes":["Incrocio troppo presto.","Piani che si appiattiscono."]},"poi-behind-back-weave":{"name":"Intreccio dietro la schiena","description":"Ogni coppia di battiti, il poi destro descrive un arco dietro la schiena e ritorna davanti senza interrompere il ritmo.","goodFor":"Passaggi del corpo che cambiano l'aspetto di un semplice schema.","alignmentCues":["Allunga basso dietro i fianchi.","Guarda avanti, fidati del ritmo."],"props":["una coppia di poi"],"commonMistakes":["Il poi che colpisce la schiena.","Il poi anteriore si ferma mentre quello posteriore continua."]},"poi-crossers":{"name":"Incrociatori","description":"Giri simultanei sul muro mentre le braccia si incrociano davanti a te e si riaprono, i poi che si scambiano lato ad ogni battito.","goodFor":"Incrocio delle braccia con i poi in sincronia.","alignmentCues":["Incrocio ai polsi.","Mantieni entrambi i poi in sincronia."],"props":["una coppia di poi"],"commonMistakes":["I cavi che si intrecciano mentre le braccia si incrociano.","Un poi che si ferma."]},"poi-reels":{"name":"Rulli","description":"Entrambi i poi ruotano insieme da un lato del corpo per un periodo, poi si spostano sull'altro lato.","goodFor":"Muovere entrambi i poi come un'unica unità intorno al corpo.","alignmentCues":["Le mani rimangono vicine.","Ruota il corpo per affrontare ogni lato."],"props":["una coppia di poi"],"commonMistakes":["Le mani che si separano durante il passaggio.","Passaggio fuori tempo."]},"poi-thread-the-needle":{"name":"Passa l'ago","description":"Poi a tempo diviso in direzione opposta con braccia incrociate: un poi passa attraverso lo spazio appena lasciato dall'altro.","goodFor":"Tempo preciso tra le due mani.","alignmentCues":["Incrocio quando si apre lo spazio.","Mantieni i cerchi stretti."],"props":[" coppia di poi"],"commonMistakes":["I poi si scontrano a metà incrocio.","Il tempo si sposta al tempo simultaneo."]},"poi-buzzsaw":{"name":"Sega","description":"Mani premute insieme e entrambi i poi che ruotano come uno solo, i cavi affiancati come una singola lama rotante.","goodFor":"Abbinare esattamente i due poi.","alignmentCues":["Palme unite, polsi rilassati.","Un cerchio, due teste."],"props":[" coppia di poi"],"commonMistakes":["Le teste si separano.","Le mani si allontanano."]},"poi-one-hand-isolation":{"name":"Isolamento con un Poi","description":"La mano ruota in senso opposto alla testa alla stessa velocità, così il centro del cavo sembra fisso in aria mentre il poi ruota intorno ad esso.","goodFor":"La prima illusione: un punto fisso nello spazio.","alignmentCues":["La mano sempre opposta alla testa.","Guarda il centro del cavo, non la testa."],"props":["un poi"],"commonMistakes":["Il cerchio della mano troppo piccolo, quindi il punto si sposta.","Aumento di velocità in alto."]},"poi-isolation":{"name":"Isolazioni","description":"Isolazioni in entrambe le mani contemporaneamente, i due punti fissi affiancati davanti a te.","goodFor":"Controllo dell'illusione a due mani.","alignmentCues":["Entrambe le mani di fronte alle loro teste.","Gomiti morbidi, spalle abbassate."],"props":[" coppia di poi"],"commonMistakes":["Una mano perde l'isolamento.","I punti si spostano in avanti."]},"poi-split-isolation":{"name":"Isolazioni Tempo-Split","description":"Isolazioni a mezzo giro di distanza: una mano in alto mentre l'altra è in basso, i punti fermi che rimangono stabili.","goodFor":"Tempo di isolamento in tempo diviso.","alignmentCues":["Le mani alternano posizione superiore e inferiore.","I punti rimangono allo stesso livello tra loro."],"props":[" coppia di poi"],"commonMistakes":["Le mani si sincronizzano.","I punti affondano."]},"poi-wheel-isolation":{"name":"Isolazioni Ruota-Piano","description":"Isolazioni accanto a te nel piano della ruota, i punti fermi che fluttuano ai tuoi lati.","goodFor":"Isolamenti in un secondo piano.","alignmentCues":["I punti allineati con i fianchi.","Le mani descrivono un cerchio parallelo ai tuoi lati."],"props":[" coppia di poi"],"commonMistakes":["I piani si torcono verso l'esterno.","Le mani troppo vicine al corpo."]},"poi-extension":{"name":"Estensioni","description":"Braccio e cavo in una linea retta, la mano che descrive un ampio cerchio in modo che il poi tracci il cerchio più grande possibile.","goodFor":"Forme grandi e aperte e la metà di estensione del cateye.","alignmentCues":["Allunga dalla spalla.","Mano e testa su una linea dal centro."],"props":["coppia di poi"],"commonMistakes":["Flettere il polso.","Cerchi che collassano in basso."]},"poi-cateye":{"name":"Cateye","description":"Una mano si isola mentre l'altra si estende. I due percorsi si sovrappongono in una forma a mandorla, come l'occhio di un gatto.","goodFor":"Mischia due percorsi di mano diversi contemporaneamente.","alignmentCues":["Mano isolata stretta, mano estesa ampia.","Entrambe partono in alto insieme."],"props":["coppia di poi"],"commonMistakes":["Entrambe le mani fanno la stessa cosa.","Forma sbilanciata."]},"poi-one-hand-antispin":{"name":"Un-Poi Antispin","description":"La mano descrive un cerchio in un senso mentre il poi ruota in senso opposto, tre giri per ogni cerchio della mano, disegnando un fiore a quattro petali.","goodFor":"La sensazione di antispin prima dei fiori con due poi.","alignmentCues":["Cerchio della mano ampio e lento.","Ogni punta del petalo all'esterno del cerchio della mano."],"props":["un poi"],"commonMistakes":["Il poi che si ribalta in una rotazione normale.","Petali irregolari."]},"poi-antispin-flower":{"name":"Quattro Petali Antispin","description":"Fiori antispin in entrambe le mani contemporaneamente, due fiori a quattro petali che sbocciano fianco a fianco.","goodFor":"Il fiore classico dei poi.","alignmentCues":["Le mani descrivono un cerchio insieme.","I petali si allineano: in alto, di lato, in basso, di lato."],"props":["coppia di poi"],"commonMistakes":["Una mano che cade in rotazione.","Fiori che si spostano in avanti."]},"poi-split-antispin":{"name":"Tempo di Split Antigiro","description":"Fiori a quattro petali con i poi a mezza rotazione di distanza, i petali di un fiore che riempiono gli spazi dell'altro.","goodFor":"Tempo dei fiori in tempo diviso.","alignmentCues":["Mani opposte l'una all'altra sui loro cerchi.","Petali che si intrecciano."],"props":["coppia di poi"],"commonMistakes":["Collasso in tempo uguale.","Mani che ruotano a velocità diverse."]},"poi-three-petal-antispin":{"name":"Tre Petali Antispin","description":"Un fiore a tre petali: due antispin per ogni cerchio della mano, creando un fiore triangolare.","goodFor":"Cambiare il numero di petali modificando la velocità della mano.","alignmentCues":["Mano più veloce rispetto a quella a quattro petali.","Petali in tre punti equidistanti."],"props":["coppia di poi"],"commonMistakes":["Ritorno a quattro petali.","Cerchio della mano che si restringe."]},"poi-five-petal-antispin":{"name":"Antispin a Cinque Petali","description":"Quattro antispin per ogni cerchio della mano, un fiore a cinque petali con una mano più lenta e ampia.","goodFor":"Controllo preciso del rapporto mano-poi.","alignmentCues":["Mano molto lenta.","Contare quattro giri dei poi per ogni cerchio della mano."],"props":["coppia di poi"],"commonMistakes":["Perdere il conto dei petali.","Mano che si ferma."]},"poi-wheel-antispin":{"name":"Ruota-Piano Antispin","description":"Fiori a quattro petali antispin accanto a te nel piano della ruota.","goodFor":"Fiori nel piano della ruota.","alignmentCues":["Fiori paralleli ai tuoi lati.","Mani che descrivono un cerchio accanto ai fianchi."],"props":["una coppia di poi"],"commonMistakes":["Piani che si inclinano verso l'interno.","Petali che sfiorano le gambe."]},"poi-overhead-antispin":{"name":"Antispin sopra la testa","description":"Fiori antispin piatti sopra la testa, i petali che si aprono sopra di te.","goodFor":"Fiori nel piano del pavimento.","alignmentCues":["Mani appena sopra la testa.","Petali che rimangono orizzontali."],"props":["una coppia di poi"],"commonMistakes":["Fiori che si inclinano in avanti.","Spalle che si affaticano e si abbassano."]},"poi-antispin-and-spin":{"name":"Antispin e Spin","description":"La mano destra traccia un fiore antispin a quattro petali mentre la sinistra mantiene una rotazione semplice in avanti.","goodFor":"Indipendenza delle mani: due forme diverse contemporaneamente.","alignmentCues":["La mano che ruota rimane stretta.","La mano che disegna il fiore descrive un cerchio ampio."],"props":["una coppia di poi"],"commonMistakes":["Entrambe le mani che imitano l'una l'altra.","I poi rallentano durante la rotazione."]},"poi-inspin-flower":{"name":"Quattro Petali Inspin","description":"La mano descrive un cerchio lentamente nello stesso senso dei poi, cinque rotazioni per ogni cerchio della mano, tracciando anelli che puntano verso l'interno.","goodFor":"Fiori inspin, il corrispettivo dell'antispin.","alignmentCues":["Mano e poi ruotano nello stesso senso.","Gli anelli dei petali sono rivolti verso il centro."],"props":["una coppia di poi"],"commonMistakes":["Il cerchio della mano troppo veloce.","Anelli irregolari."]},"poi-three-petal-inspin":{"name":"Tre Petali Inspin","description":"Inspin con quattro rotazioni per ogni cerchio della mano, tracciando un fiore a tre petali.","goodFor":"Cambiare il numero di petali in inspin.","alignmentCues":["La mano leggermente più veloce dei quattro petali.","Tre anelli, equidistanti."],"props":["una coppia di poi"],"commonMistakes":["Conteggio errato.","Anelli che si appiattiscono."]},"poi-wall-wheel-hybrid":{"name":"Ibrido Parete-Ruota","description":"Ad ogni giro i poi cambiano piano, davanti poi di lato, ruotando quando la testa passa dritta verso il basso.","goodFor":"Cambiare piano senza interrompere la rotazione.","alignmentCues":["Cambia quando i poi puntano verso il pavimento.","Ruota il polso, non tutto il braccio."],"props":["una coppia di poi"],"commonMistakes":["Cambio a metà cerchio.","I poi che oscillano tra i piani."]},"poi-wheel-floor-hybrid":{"name":"Ibrido Ruota–Pavimento","description":"I poi alternano tra ruotare accanto a te e spazzare in piano, cambiando mentre puntano in avanti.","goodFor":"Un secondo ibrido con un piano orizzontale.","alignmentCues":["Cambia quando il poi punta in avanti.","Mantieni le mani all'altezza dei fianchi."],"props":["una coppia di poi"],"commonMistakes":["I poi che si abbassano durante il cambio.","Perdita del ritmo."]},"poi-floor-wall-hybrid":{"name":"Ibrido Pavimento–Parete","description":"Dall'alto in piano a verticale davanti e dietro, cambiando mentre i poi puntano ai lati.","goodFor":"Collegare i piani sopra e a parete.","alignmentCues":["Cambia quando i poi puntano ai lati.","Alza e abbassa le mani in modo fluido."],"props":["una coppia di poi"],"commonMistakes":["I poi che colpiscono la testa.","Cambiamenti irregolari."]},"poi-top-stall":{"name":"Stall","description":"I poi salgono in alto, si fermano un istante dritti sopra la mano, e ricadono lungo la stessa traiettoria.","goodFor":"Fermarsi e invertire: la base per combo di stall e iperloop.","alignmentCues":["Alza la mano quando il poi raggiunge il picco.","Lascialo pendere, poi guidalo indietro."],"props":["un solo poi"],"commonMistakes":["Il cavo che si allenta e si avvolge.","Affrettare la pausa."]},"poi-stalls":{"name":"Doppio Stall","description":"Entrambi i poi si fermano insieme in alto e si invertono, uno accanto all'altro.","goodFor":"Controllo della sosta con due mani.","alignmentCues":["Entrambi raggiungono il picco nello stesso momento.","Le mani si alzano insieme."],"props":["una coppia di poi"],"commonMistakes":["Un poi si ferma in ritardo.","I poi si scontrano durante la discesa."]},"poi-side-stall":{"name":"Side Stalls","description":"I poi si fermano ai lati invece che in alto, ciascuno si ferma all'altezza della spalla prima di tornare indietro.","goodFor":"Soste in un punto diverso del cerchio.","alignmentCues":["Fermata quando i poi puntano lateralmente.","Braccia morbide."],"props":["una coppia di poi"],"commonMistakes":["I poi cadono invece di fermarsi.","Tempo che si allontana."]},"poi-chasing-stalls":{"name":"Inseguimento dei mulini","description":"Soste con mezzo battito di distanza: un poi si ferma in alto mentre l'altro è ancora in salita.","goodFor":"Soste in tempo diviso.","alignmentCues":["Una sosta, poi l'altra.","Mantieni le mani all'altezza del petto."],"props":["una coppia di poi"],"commonMistakes":["Entrambi si fermano insieme.","Affrettare la seconda sosta."]},"poi-hyperloop":{"name":"Hyperloop","description":"Una sosta in cui il piano si capovolge in alto, così i poi fanno un giro e scendono sull'altro lato del cerchio.","goodFor":"Cicli tridimensionali dalla posizione di arresto.","alignmentCues":["Ruota il polso in cima alla posizione di arresto.","Mantieni il cavo teso."],"props":["un poi"],"commonMistakes":["Capovolgimento prima che il poi raggiunga il picco.","Allentamento del cavo."]},"poi-arm-wrap":{"name":"Avvolgimento braccio","description":"Il poi si avvolge attorno all'avambraccio opposto tenuto in avanti, ruotando più velocemente su un cavo più corto, poi si svolge tornando a un cerchio completo.","goodFor":"Il primo avvolgimento e come gli avvolgimenti accelerano il poi.","alignmentCues":["Mantieni il braccio di supporto fermo e orizzontale.","Mantieni la mano in movimento dietro il supporto."],"props":["un poi"],"commonMistakes":["Movimento del braccio di supporto.","Svolgimento nella direzione sbagliata."]},"poi-leg-wrap":{"name":"Avvolgimento gamba","description":"Solleva il ginocchio e lascia che il poi si avvolga attorno alla coscia, poi abbassa la gamba mentre si svolge.","goodFor":"Avvolgimenti sul corpo.","alignmentCues":["Ginocchio in alto quando il poi arriva.","Mantieni la gamba di appoggio dritta."],"props":["un poi"],"commonMistakes":["Sollevamento del ginocchio in ritardo.","Perdita di equilibrio."]},"poi-neck-wrap":{"name":"Avvolgimento collo","description":"Da una rotazione sopra la testa, porta la mano verso il basso in modo che il poi si avvolga attorno alla nuca e si svolga tornando sopra la testa.","goodFor":"Un avvolgimento spettacolare che collega le rotazioni sopra la testa.","avoidIf":["Usa i poi da pratica con teste morbide; non imparare mai gli avvolgimenti al collo con quelli di fuoco."],"alignmentCues":["Mentolo livellato, collo lungo.","Guida il cavo alla base del collo."],"props":["un poi"],"commonMistakes":["Avvolgimento sulla testa.","Cavo troppo allentato."]},"poi-cord-wrap":{"name":"Avvolgimento con corda","description":"Da una farfalla, i due cavi si avvolgono l'uno sull'altro in basso, le teste ruotano su cavi corti prima di svolgersi.","goodFor":"Avvolgimenti tra i due poi.","alignmentCues":["Incontra i cavi in fondo alla farfalla.","Mantieni le mani ferme mentre si avvolgono."],"props":["paio di poi"],"commonMistakes":["Mani che si allontanano.","Avvolgimento intrecciato."]},"poi-toss":{"name":"Lancio del poi","description":"Lascia andare il manico mentre il poi sale. Ruota nell'aria e riprendi il manico quando torna indietro.","goodFor":"Lasciata e presa.","avoidIf":["Pratica i lanci con i poi morbidi e con spazio intorno a te."],"alignmentCues":["Lascia andare in fase di salita.","Guarda il manico, non la testa."],"props":["un poi"],"commonMistakes":["Lasciando troppo tardi.","Afferrando il cavo invece del manico."]},"poi-high-toss":{"name":"Lancio alto","description":"Un lancio più alto con un giro in più nell'aria prima della presa.","goodFor":"Lanci più grandi con più rotazione.","alignmentCues":["Una spinta più decisa al rilascio.","Prendi quando l'impugnatura gira."],"props":["un poi"],"commonMistakes":["Lancio che si sposta in avanti.","Afferrare bruscamente al momento del ricevimento."]},"poi-double-toss":{"name":"Lancio doppio","description":"Entrambi i poi lanciati in momenti separati, uno dopo l'altro, e ripresi nella rotazione.","goodFor":"Tempismo del lancio con entrambe le mani.","alignmentCues":["Rilascia uno, poi l'altro.","Prendi nello stesso ordine."],"props":["una coppia di poi"],"commonMistakes":["Rilasciare entrambi contemporaneamente.","Guardare un poi e perdere l'altro."]},"shake-out":{"name":"Scuotimento","description":"Metti giù gli oggetti e scuoti le mani e gli avambracci. Lascia cadere le spalle.","goodFor":"Un breve reset tra sessioni intense."},"breathe":{"name":"Respira e ripristina","description":"Metti giù gli oggetti, stai comodo e lascia che le braccia pendano. Prenditi un momento prima della prossima sessione.","goodFor":"Riduce il battito cardiaco e elimina la frustrazione dopo i caduti."}}`),t={"warmup-mobility":{name:`Riscaldamento fluido`,description:`Caviglie, spalle, colonna vertebrale e anche rilassate a un ritmo costante. Usalo prima di qualsiasi sessione con oggetti.`,focus:`Riscaldamento · mobilità`},"first-throws":{name:`Primi lanci`,description:`Una palla che arco da mano a mano all'altezza degli occhi, poi lo scambio a due palle da cui cresce ogni schema.`,focus:`Giocoleria · fondamenta`},"cascade-builder":{name:`Costruttore di cascade`,description:`Scambi di due palle di seguito fino a quando la terza palla si unisce: serie di cascade brevi, ripristino, ripeti.`,focus:`Giocoleria · fondamenta`},"juggling-tempo-ladder":{name:`Scala del tempo del giocolaggio`,description:`Cascade a tre tempi, un po' più veloce ad ogni gradino. Lanci più bassi per i gradini più veloci.`,focus:`Giocoleria · tempo`},"siteswap-sampler":{name:`Campionatore di siteswap`,description:`Cascade in 423, 441 e 531, con il cascade inverso e lo shower come pulizia del palato. Ogni schema inizia e finisce con il cascade.`,focus:`Giocoleria · schemi`},"four-ball-session":{name:`Sessione a quattro palle`,description:`Due in una mano per ogni lato, la fontana a quattro palle, poi la fontana sincrona.`,focus:`Giocoleria · numeri`},"juggling-combo-flow":{name:`Flusso di combinazioni di giocolaggio`,description:`Una lunga sequenza fluida: cascade, cascade inverso, Mills mess e i siteswap intrecciati in un unico pezzo di musica.`,focus:`Giocoleria · combinazioni`},"cascade-tricks":{name:`Trucchi con cascade`,description:`Tennis, mezzo shower e artigli, ognuno inserito in una cascade in corso e poi rimosso.`,focus:`Giocoleria · variazioni`},"juggling-body-throws":{name:`Lanci con il corpo`,description:`Sotto la gamba, dietro la schiena, tagli e pinguini: il cascade lanciato intorno al corpo.`,focus:`Giocoleria · lanci sul corpo`},"sync-shapes":{name:`Forme sincrone`,description:`Colonne, incrocio arcobaleno, scatola e yo-yo: tre palle lanciate due alla volta.`,focus:`Giocoleria · schemi sincroni`},"club-foundations":{name:`Fondamenti del club`,description:`Giri singoli, scambio di due club e cascata di tre club, con finiture a piatto.`,focus:`Giocoleria · club`},"passing-with-a-partner":{name:`Passaggio con un partner`,description:`Di fronte al partner, passate: un pallone in traverso, poi due ciascuno, poi il sei-count, il quattro-count e il due-count.`,focus:`Giocoleria · passaggio`},"club-passing-session":{name:`Passaggio del club`,description:`Quattro-count di club per riscaldarsi, due-count e tre-count per il ritmo, poi passaggi doppi.`,focus:`Giocoleria · passaggio con club`},"hoop-juggling-session":{name:`Giocoleria con cerchio`,description:`Anelli di dimensione completa lanciati di lato: lanci singoli, scambio, cascata e la sua versione inversa.`,focus:`Giocoleria · anelli`},"staff-first-spins":{name:`Primi giri del bastone`,description:`Giro della ruota accanto al corpo, poi giro davanti. Giri lenti e uniformi, uno per battito.`,focus:`Bastone · fondamenta`},"staff-foundations":{name:`Fondamenti del bastone`,description:`Giro della ruota, giro davanti, otto e passaggio mano a mano collegati sul ritmo.`,focus:`Bastone · fondamenta`},"staff-flow-weave":{name:`Intreccio fluido del bastone`,description:`Otto in farfalla, giri a una mano e elicottero, uniti in modo che il bastone non si fermi mai.`,focus:`Bastone · flusso`},"staff-isolation-lab":{name:`Laboratorio di isolamento del bastone`,description:`Isolazioni e fiore antispin a ritmo più lento, con passaggi dietro la schiena tra uno e l'altro.`,focus:`Bastone · tecnico`},"staff-advanced-flow":{name:`Flusso avanzato del bastone`,description:`L'intero vocabolario in un unico pezzo lungo: intrecci, avvolgimenti, isolamenti e il rotolamento del collo.`,focus:`Bastone · flusso`},"staff-both-ways":{name:`Bastone in entrambe le direzioni`,description:`Ogni rotazione di base in avanti e poi al contrario, più l'elicottero a due mani sopra la testa.`,focus:`Bastone · direzione e piani`},"staff-contact-lab":{name:`Laboratorio contatto bastone`,description:`Contatto con mano aperta e corpo: fishtails, volante, rotolamenti di mano e avambraccio, e un lancio finale.`,focus:`Bastone · contatto`},"double-staff-session":{name:`Sessione doppio bastone`,description:`Un bastone corto in ogni mano: stesso tempo, tempo diviso, ruote e ruote divise.`,focus:`Bastone · doppio bastone`},"hoop-first-spins":{name:`Primi giri con l'anello`,description:`Hoop intorno alla vita con una spinta avanti-indietro, poi far girare l'hoop attorno a una mano.`,focus:`Hoop · fondamenta`},"hoop-body-flow":{name:`Flusso anello sul corpo`,description:`Muovere l'hoop fino al petto e giù fino alle ginocchia e ritorno alla vita, senza fermarsi.`,focus:`Hoop · sul corpo`},"hoop-off-body":{name:`Anello fuori dal corpo`,description:`Rotazioni di mano, lasso, wedgies e passaggi, finendo con isolamenti che tengono l'hoop fermo nello spazio.`,focus:`Hoop · fuori dal corpo`},"hoop-full-flow":{name:`Flusso completo anello`,description:`Sul corpo e fuori dal corpo insieme: scale mobili, hoop intorno al collo e i trucchi fuori dal corpo in un unico flusso.`,focus:`Hoop · flusso`},"hoop-body-zones":{name:`Zone del corpo con anello`,description:`Vita in entrambe le direzioni, poi fianchi, cosce e petto, sollevando e abbassando l'hoop tra le zone.`,focus:`Anello · sul corpo`},"hoop-tricks-session":{name:`Trucchi con l'anello`,description:`Giri laterali, il lancio della moneta, la treccia, un lancio e il ritorno sul corpo.`,focus:`Anello · fuori dal corpo`},"hoop-doubles-session":{name:`Doppi anelli`,description:`Due anelli: giri a mano specchiati e sfalsati, giri laterali e un anello in vita con un giro a mano.`,focus:`Anello · doppio`},"poi-foundations":{name:`Fondamenti dei poi`,description:`Un poi, poi due: giri a muro avanti e indietro, ruote accanto a te, tempo diviso e farfalla.`,focus:`Poi · primi giri`},"poi-weave-session":{name:`Intrecci con i poi`,description:`Tempo diviso in tre battute di intreccio, in entrambe le direzioni, poi intreccio a due battute, rulli e incroci.`,focus:`Poi · intrecci`},"poi-flower-lab":{name:`Laboratorio dei fiori con i poi`,description:`Estensioni e isolazioni, poi antispin con un poi e due, e un fiore inspin per concludere.`,focus:`Poi · fiori`},"daily-mixed-flow":{name:`Flusso misto quotidiano`,description:`Un po' di ogni arte: cascata, giri di bastone e anello, con un movimento di mobilità tra i prop.`,focus:`Misto · pratica`}},n=JSON.parse(`{"start-here":{"title":"Inizia qui: la tua prima settimana di flusso","summary":"Scegli un prop, pratica dieci minuti al giorno sul ritmo, e lascia che l'albero di sblocco ti dica cosa viene dopo.","imageAlt":"Figura 3D che lancia una palla da giocoleria da una mano all'altra","body":["Le arti del flusso sembrano magia dall'esterno: palle sospese in aria, un bastone che diventa una macchia, un anello che orbita attorno a una danzatrice che a malapena sembra muoversi. Dall'interno sono una pila di piccole abilità, ognuna imparabile in un pomeriggio, sovrapposte fino a quando la pila sembra senza sforzo. La tua prima settimana riguarda la base di quella pila.","Scegli un prop per iniziare. Il giocoliere insegna tempismo e coordinazione occhio-mano; il bastone insegna piani e cambi di mano fluidi; l'anello insegna il ritmo attraverso tutto il corpo. Puoi imparare tutti e tre, ma uno alla volta mantiene la tua attenzione dove c'è progresso. L'albero dei premi mostra ogni movimento per ogni arte, dal primo lancio o giro ai pattern avanzati, e sblocca i successivi quando padroneggi quelli su cui si basano.","Pratica poco e spesso. Dieci minuti concentrati al giorno battono un'ora la domenica, perché la coordinazione si consolida tra le sessioni, specialmente durante il sonno. Una breve routine dalla pagina Routine, un riscaldamento e qualche passo contato del tuo movimento attuale costituiscono una pratica completa.","Pratica sul ritmo fin dal primo giorno. Ogni movimento in SynthFlow è contato in battute a un certo tempo, con musica o percussioni generate che si adattano. Il ritmo ti dà qualcosa a cui aggrapparti quando il prop non collabora, e rende misurabile il progresso: una sequenza pulita a 90 BPM questa settimana, 100 la prossima.","Aspettati cadute. Tutti cadono, anche i professionisti in prova. Una caduta ti dice quale lancio o presa ha bisogno di attenzione; non dice nulla sul talento. Raccogli il prop, aspetta il prossimo battito, e riprova. Alla fine della settimana avrai un movimento che puoi fare senza pensare, ed è in quel momento che inizia il flow."]},"counting-and-the-beat":{"title":"Conteggi, battute e battito","summary":"Perché ogni movimento è contato in battute a un certo tempo, e come sincronizzare i tuoi lanci e giri con la musica.","imageAlt":"Figura 3D che giocola una cascata di tre palle con archi disegnati sopra le mani","body":["La musica è composta da battiti raggruppati in battute, di solito quattro battiti per battuta. I movimenti del Flow sono composti da cicli: un lancio da ogni mano, mezzo giro del bastone, un'orbita dell'anello. Quando un ciclo coincide con il battito, il movimento e la musica diventano una cosa sola. Ecco perché SynthFlow misura ogni passo della routine in battute piuttosto che in secondi, e perché ogni movimento indica quante battute richiede un ciclo.","In una cascata di tre palle ogni lancio cade su un battito, alternando destra e sinistra. In un mezzo giro del bastone di solito un battito basta. In un giro in vita di solito un'orbita per battito a un tempo rilassato. I numeri nel nome del giocatore indicano cosa accade su ogni battito, e la figura 3D si muove esattamente sullo stesso ritmo dell'audio, così puoi copiarla in tempo.","Il tempo si misura in battiti al minuto (BPM). Ogni movimento ha una gamma confortevole: abbastanza lento da mantenere la pulizia, abbastanza veloce da far mantenere il moto al prop. Al di sotto della gamma i prop rotanti si fermano e i lanci diventano così alti da disperdersi; al di sopra inizi a correre e a far cadere. Il costruttore ti avvisa quando un passo è fuori dalla gamma del movimento.","Inizia ogni passo sul battito iniziale, il \\"uno\\" della battuta. Il conto all'indietro ti dà una battuta per far muovere il prop prima che inizino le battute contate. Se perdi il ritmo, non inseguirlo: fermati, ascolta il prossimo \\"uno\\", e riprova. I musicisti chiamano questo trovare la cima della battuta, e funziona anche per gli artisti del flow.","Contare ad alta voce per qualche sessione aiuta più di quanto sembri. Dire \\"uno, due, tre, quattro\\" mentre giocoli lega il ritmo al tuo respiro e alla tua voce, così sopravvive quando il pattern diventa difficile. Una volta che i numeri vivono nel tuo corpo, spegni i conti vocali nelle Impostazioni e lascia che la musica ti porti."]},"tempo-ladders":{"title":"Scale di tempo: lento è fluido, fluido è veloce","summary":"Salire di qualche BPM alla volta da un tempo che riesci a eseguire correttamente, e tornare indietro non appena la forma si rompe.","imageAlt":"Figura 3D che fa girare un bastone davanti al corpo nel piano della parete","body":["Una scala di tempo è lo stesso movimento ripetuto a tempi crescenti: otto battute a 80 BPM, otto a 88, otto a 96, e così via. È il modo più affidabile per rendere un movimento più veloce senza renderlo più disordinato, e diverse routine integrate sono basate su questo concetto.","Inizia da un gradino che riesci a eseguire correttamente, anche se sembra troppo facile. Il punto del gradino più basso non è la sfida; è esercitare la forma corretta in modo che sia questa a velocizzarsi. Salire di poco, circa dal cinque al dieci percento. Salti grandi cambiano il movimento: i lanci diventano più bassi, le rotazioni più superficiali, e finisci per esercitarti su un trucco diverso.","Smetti di salire quando la forma si rompe, non quando perdi. Osserva i segni precoci: i picchi che diventano irregolari, il bastone che si allontana dal suo piano, l'anello che sale o scende. Questi sono i segnali per tornare di un gradino indietro e ripeterlo. Finire una scala con una ripetizione pulita a un tempo appena al di sotto del tuo limite insegna al tuo corpo quel tempo; finire con un incidente insegna l'incidente.","I tempi lenti sono più difficili di quanto sembrino per gli oggetti rotanti, perché l'oggetto ha meno quantità di moto per portarlo avanti. Se un bastone o un anello si ferma in fondo alla sua portata, mantieni il tempo e ingrandisci leggermente il movimento, oppure eseguilo a metà tempo con la musica: un ciclo ogni due battiti.","Segui il tuo tempo massimo pulito per ogni movimento in Progresso. Vedere quel numero salire lentamente nel corso delle settimane è una buona motivazione, e mostra anche quando un movimento ha raggiunto un plateau e ha bisogno di un esercizio diverso piuttosto che più dello stesso."]},"siteswap-notation":{"title":"Siteswap: giocoleria scritta con numeri","summary":"Ogni numero indica quanti battiti dopo viene lanciata di nuovo una palla; i numeri dispari attraversano, i numeri pari rimangono, e la media è il numero di palle.","imageAlt":"Figura 3D che giocola il siteswap 441 con due lanci alti e un rapido scatto","body":["I modelli di giocoleria sono difficili da descrivere con le parole e facili da descrivere con i numeri. Siteswap, sviluppato indipendentemente a metà degli anni '80 da giocolieri a Cambridge, al Caltech e a Santa Cruz, scrive un modello come una sequenza ripetuta di cifre. È il modo in cui i giocolieri condividono i modelli, verificano se un'idea può funzionare e scoprono trucchi che nessuno ha provato. SynthFlow lo utilizza per animare ogni modello di giocoleria con lo stesso motore.","Immagina le mani che lanciano alternativamente ad ogni battito: destra, sinistra, destra, sinistra. Ogni cifra in un siteswap indica quanti battiti dopo il lancio di questa palla verrà lanciata di nuovo. Un 3 ritorna tre battiti dopo; poiché tre è dispari, atterra nell'altra mano. Una cascata di tre palle è semplicemente 3, 3, 3, 3 per sempre, scritta semplicemente come 3. Un 4 ritorna quattro battiti dopo nella stessa mano, che è la fontana di quattro palle.","I numeri piccoli hanno significati speciali. Un 2 ritorna nella stessa mano due battiti dopo, il che in pratica significa tenere la palla per un momento. Un 1 attraversa all'altra mano sul battito successivo, un rapido passaggio dritto. Uno 0 è una mano vuota. I numeri più grandi indicano lanci più alti: un 5 è un lancio alto che attraversa.","Leggi un modello cifra per cifra. In 441, due lanci rimangono sul loro lato mentre una terza palla attraversa sotto di loro. In 531, un lancio alto che attraversa va in alto mentre un lancio di cascata e un passaggio mantengono in movimento le altre due palle. In 423, un lancio di altezza fontana, una palla tenuta e un lancio di cascata si alternano.","Il teorema della media ti dice quante palle un modello richiede: somma le cifre e dividi per il numero di cifre. 441 somma a 9 su tre cifre, quindi tre palle. Se la media non è un numero intero, la sequenza non può essere giocolata. Un secondo controllo è che nessuna palla può atterrare nella stessa mano nello stesso battito, che è come i giocolieri individuano i modelli impossibili prima di provarli.","Siteswap ha anche una notazione per quando entrambe le mani lanciano insieme, scritta tra parentesi come (4,4), e per lanciare due palle da una mano contemporaneamente, scritta tra parentesi quadre. Non hai bisogno di tutto questo per giocolare bene, ma una volta che i numeri ti diventano chiari, ogni nuovo nome di modello inizia a spiegarsi da solo. Apri il glossario Flow per i numeri singoli."]},"passing-basics":{"title":"Basics del passaggio: giocoleria con un partner","summary":"Fatti fronte a un partner, lancia con le mani destra insieme, passa dritto all'altra mano sinistra e conta: sei conti, quattro conti, due conti.","imageAlt":"Due giocolieri 3D di fronte l'uno all'altro, che si passano le palle dritto tra di loro","body":["Il passaggio è il giocolaggio con qualcun altro. Due giocolieri stanno di fronte l'uno all'altro, ognuno esegue una cascata, e di tanto in tanto uno dei lanci va dall'altro lato invece che a se stesso. È una delle cose più sociali nel giocolaggio: il passaggio di club è come molti giocolieri trascorrono la serata di un festival, e trasforma la pratica in una conversazione.","Stai a circa due metri e mezzo di distanza per le palle, un po' più lontano per i club. Entrambi iniziate a giocolare sullo stesso conto, con le mani destra che lanciano insieme. Il passaggio standard è dritto: lascia la vostra mano destra e atterra nella mano sinistra del partner, direttamente di fronte a voi. Non viene lanciato verso il loro viso. Mirate all'anca sinistra e date un arco che raggiunge il picco appena sopra l'altezza della testa, a metà strada tra voi.","I modelli di passaggio sono denominati in base a quanto spesso si passa. In un sei-conto si passa ogni sesto lancio, il che lascia cinque lanci su se stessi in mezzo per stabilizzarsi. In un quattro-conto, il riscaldamento standard, si passa ogni secondo lancio con la mano destra: passaggio, auto, auto, auto. In un due-conto ogni lancio con la mano destra è un passaggio e ogni lancio con la mano sinistra è un auto. In un tre-conto i passaggi alternano le mani, quindi imparate a passare anche con la mano sinistra. Gli ultimi, o un uno-conto, fanno di ogni lancio singolo un passaggio.","Contate ad alta voce all'inizio. \\"Passaggio, due, tre, quattro\\" vi mantiene sullo stesso ritmo, e nel momento in cui uno di voi si allontana i passaggi smettono di arrivare in tempo. La voce del conto di SynthFlow dice \\"passaggio\\" nei passaggi e \\"auto\\" negli altri lanci sul ritmo, così potete esercitarvi sul ritmo da soli mentre il partner sullo schermo giocola con voi.","Iniziate con una palla. Lanciatela attraverso, fate in modo che il vostro partner la prenda dalla mano sinistra alla destra e la lanci indietro. Poi prendete due palle ciascuno e passate insieme con le mani destra, passando la palla in arrivo dalla sinistra alla destra. Solo allora aggiungete la cascata. La maggior parte dei caduti durante il passaggio avviene a causa di passaggi troppo lunghi o troppo piatti, e entrambi sono più facili da correggere con una palla piuttosto che con sei.","Nella notazione di SynthFlow un modello di passaggio elenca i vostri lanci e quelli del vostro partner, uno per battito, con p che indica un passaggio: il quattro-conto è <3p 3 3 3|3p 3 3 3>. I numeri hanno lo stesso significato della siteswap. Un 4p è un doppio passaggio che atterra un battito dopo, ed è così che si costruiscono i modelli a sette club."]},"planes-and-geometry":{"title":"Piani: parete, ruota e pavimento","summary":"I prop in rotazione vivono in piani piatti; mantenere il piano pulito è la maggior parte di ciò che rende uno staff o un cerchio apparire nitidi.","imageAlt":"Figura 3D che intreccia uno staff in un otto su entrambi i lati del corpo","body":["Uno staff o un cerchio che ruota descrive una superficie piana, chiamata il suo piano. Gli artisti del flusso descrivono tre piani di base rispetto al corpo. Il piano della parete è davanti a te, come un pannello di vetro contro cui potresti appoggiare le palme. Il piano della ruota è accanto a te, come una ruota di carretto che gira lungo il tuo fianco. Il piano del pavimento è orizzontale, parallelo al suolo, come in un elicottero sopra la testa o un lasso.","Piani puliti sono ciò che il pubblico interpreta come abilità. Uno staff che vacilla fuori dal suo piano sembra incerto anche se non cade mai; un cerchio che rimane perfettamente piatto durante un passaggio sembra senza sforzo. La maggior parte della pratica iniziale riguarda silenziosamente i piani: evitare che i polsi si torcano, evitare che i gomiti si allarghino e lasciare che le spalle muovano l'oggetto piuttosto che le mani.","Molti trucchi sono definiti dal cambiamento di piano. Una treccia a otto muove lo staff dal piano della ruota da un lato al piano della ruota dall'altro. Una farfalla lo piega dietro la spalla e indietro. Una scala mobile fa scorrere un cerchio su e giù lungo il corpo mentre il suo piano rimane orizzontale. Imparare dove ogni movimento inizia e finisce nello spazio è come collegarli in un flusso.","Il visualizzatore 3D può disegnare il piano mentre pratichi. Attivalo quando impari una nuova rotazione e confronta: lo staff si inclina verso di te in alto? Il cerchio si abbassa in avanti? Uno specchio o una telecamera del telefono mostrano la stessa cosa. Guardare di lato è particolarmente utile per i movimenti nel piano della parete, perché l'inclinazione non è visibile di fronte.","I piani aiutano anche con la sicurezza e lo spazio. Prima di una sessione, verifica che ogni piano che utilizzerai sia libero: la parete davanti, le pareti ai lati e il soffitto sopra per i movimenti nel piano del pavimento e sopra la testa. Un piano pulito senza ostacoli è un piano sicuro."]},"spin-and-antispin":{"title":"Spin, antispin e isolazioni","summary":"Il modo in cui l'oggetto ruota rispetto alla mano definisce tre famiglie di movimento: rotazione, antirotazione e isolamento.","imageAlt":"Disegno 3D di una figura che traccia un fiore a quattro petali con uno staff","body":["Quando muovi un oggetto rotante in cerchio, avvengono due rotazioni contemporaneamente: la tua mano percorre un cerchio e l'oggetto ruota attorno al proprio centro. La teoria del flusso nomina i movimenti in base a come queste due rotazioni sono correlate. È lo stesso vocabolario per staff, cerchio e poi, motivo per cui le abilità si trasferiscono così bene tra gli oggetti.","Nella rotazione, a volte chiamata inspin, l'oggetto ruota nella stessa direzione del cerchio della mano. Questa è la direzione naturale; la maggior parte delle prime rotazioni sono inspin senza che nessuno lo chiami così. La forma tracciata è un fiore i cui petali puntano verso l'esterno.","In antispin la prop gira nella direzione opposta al cerchio della mano. All'inizio sembra strano, come accarezzare la testa e grattarsi la pancia contemporaneamente, ma disegna il classico fiore a petali. Il numero di petali dipende da quante volte la prop gira per ogni cerchio della mano: tre rotazioni inverse per cerchio danno quattro petali, che è l'Antispin a Quattro Petali nell'albero del bastone.","Un'isolazione è il caso speciale in cui la mano descrive un cerchio in modo che un punto della prop sembri congelato nello spazio. Con un bastone il centro rimane fermo mentre le estremità descrivono un cerchio attorno a esso; con un anello il centro dell'anello o un punto sul bordo rimane fermo. Le isolazioni sembrano che la prop stia fluttuando e il corpo orbiti attorno a essa. Richiedono percorsi precisi delle mani, il che le rende un ottimo allenamento per tutti gli altri trucchi.","Imparali lentamente e al ritmo. L'antispin beneficia particolarmente di un tempo ben al di sotto della tua velocità normale di rotazione, con conti che indicano dove dovrebbe essere la prop: in alto, di lato, in basso, di lato. Usa il fantasma nella visualizzazione 3D per vedere la posizione del prossimo battito, e la scia per verificare se il tuo fiore ha petali uniformi.","Una volta che spin, antispin e isolazione ti risultano familiari in un piano, prova in un altro. La teoria rimane la stessa e il tuo corpo impara che il piano è solo un'impostazione, un grande passo verso l'improvvisazione del flusso."]},"sequencing":{"title":"Come si costruiscono le routine fluide","summary":"Riscaldamento, pratica un obiettivo alla volta con collegamenti fluidi, mantieni i salti di tempo piccoli e termina con un raffreddamento facile.","imageAlt":"Figura 3D che passa un anello da una mano all'altra davanti al corpo","body":["Una buona routine di flusso ha la stessa forma di un buon set musicale: un inizio che riscalda la stanza, un centro che costruisce tensione e una fine che permette a tutti di respirare. Le routine integrate in SynthFlow seguono questa forma, e il co-pilota del costruttore verifica la tua contro di essa.","Inizia con un riscaldamento. I cerchi del polso, quelli del braccio e i rotolamenti delle spalle portano le articolazioni che caricherai attraverso la loro gamma a un ritmo delicato. Due o tre minuti sono sufficienti per una sessione breve; sessioni più lunghe e giornate fredde meritano di più.","Dedica il blocco di pratica a un solo obiettivo. Scegli un movimento su cui stai lavorando e circondalo con movimenti che si collegano ad esso. Il costruttore mostra come ogni passo si collega a quello precedente: fluisce direttamente dalla stessa posizione della mano, un piccolo riprendere la presa, posare la prop, o costruire su un trucco precedente. Le routine che fluiscono sembrano ballare; le routine piene di posate sembrano una lista.","Mantieni i cambiamenti di tempo piccoli tra i passaggi. Saltare da 80 a 130 BPM reimposta il tuo tempo e favorisce gli errori. Il co-pilota segnala salti di più di un quarto circa, piegando il tempo a metà e doppio, così un passo di cerchio a 70 BPM può stare accanto a una traccia a 140 BPM.","Ritorna alla movimento principale più di una volta. La ripetizione durante una sessione, con altri movimenti in mezzo, costruisce abilità meglio di un lungo blocco, perché ogni ritorno è un tentativo nuovo da un punto di partenza leggermente diverso.","Concludi con un raffreddamento: un movimento semplice a basso tempo, o una breve pausa con alcuni respiri. Abbassa il battito cardiaco e dà alla tua coordinazione una conclusione tranquilla da ricordare. Anticipa la routine prima di eseguirla e rimuovi qualsiasi cosa che sia chiaramente un'ambizione di ieri."]},"effort":{"title":"Quando aumentare il ritmo","summary":"Spingi quando la forma è corretta e sei fresco; allenta quando i picchi vacillano, la presa si stringe o gli errori cominciano a concentrarsi.","imageAlt":"Figura 3D che giocola cinque palle in una cascata alta","body":["Il progresso nel flusso arriva dalla pratica al limite delle tue capacità, ma il limite si muove. Alcuni giorni è più lontano di quanto ti aspetti; altri giorni si è ritirato. Imparare a leggerlo è una capacità che vale quanto qualsiasi trucco.","Spingi quando le basi sono stabili. Se i tuoi picchi sono regolari, il tuo bastone rimane nel suo piano, il tuo cerchio è livellato e la tua respirazione è facile, sali un gradino della scala del tempo o prova il prossimo esercizio della progressione. I primi quindici minuti di una sessione, dopo un riscaldamento, sono di solito il momento migliore per materiale nuovo.","Allenta quando la qualità scende. Gli errori concentrati, una presa più stretta, le spalle che si avvicinano alle orecchie e un respiro trattenuto dicono che il tuo sistema nervoso è stanco. Abbassa il tempo, torna a un movimento che conosci bene, o termina la sessione. Spingere attraverso la fatica ripete principalmente gli errori.","Attenzione anche ai segnali fisici. Lanci e rotazioni ripetuti caricano i polsi, gli avambracci e le spalle. Un dolore che svanisce entro un giorno è un adattamento normale. Dolore acuto, dolore che aumenta durante la pratica, intorpidimento o formicolio sono motivi per fermarsi e riposare; sintomi persistenti meritano una visita medica.","Usa la valutazione sull'effort dopo ogni sessione. Il mago della pratica la legge: diverse sessioni difficili di fila e suggerisce qualcosa di più delicato, diverse sessioni facili e suggerisce un po' di più. Valutazioni oneste danno suggerimenti migliori."]},"drops-are-data":{"title":"I fallimenti sono dati","summary":"Un errore ti dice quale lancio o presa correggere; trattarlo come un fallimento ti insegna solo a irrigidirti.","imageAlt":"Figura 3D che scambia due palle da giocoleria tra le mani","body":["Ogni giocoliere ha un pavimento coperto di palle a un certo punto. Ogni manipolatore di bastone ha sentito il rumore. La differenza tra chi continua a migliorare e chi abbandona raramente è il talento; è come trattano la caduta.","Una caduta è una misurazione. Ti dice quale lancio è andato storto, quale presa hai cercato, quale momento della rotazione ha perso il suo piano. Se la stessa palla continua a cadere davanti a te, i tuoi lanci si stanno spostando in avanti. Se le cadute avvengono dopo sei lanci, qualcosa nel tuo terzo o quarto lancio non va. Guarda dove e quando, poi scegli una cosa da cambiare.","Trattare le cadute come fallimento ha un costo. La paura irrigidisce le spalle e accorcia il respiro, e la tensione rende i movimenti più piccoli e veloci, causando più cadute. La risposta calma — raccogli, respira, aspetta il battito, ricomincia — non è solo piacevole; è la risposta tecnicamente corretta.","Conta le serie pulite, non le cadute. I maestri di SynthFlow padroneggiano un movimento quando hai abbastanza serie pulite e minuti di pratica, quindi le cadute lungo il percorso sono semplicemente parte dei minuti. Alcuni giorni registrerai dieci serie pulite, altri due. Entrambi i giorni contano.","Fai cadere di proposito a volte. Quando impari un nuovo trucco, esegui il primo lancio o la prima metà della rotazione e lascia che cada. Poi aggiungi la presa. Isolare il momento rischioso lo riduce, e impari che il pavimento non è il tuo nemico. È solo dove va il prop quando stai imparando."]},"safety":{"title":"Sicurezza: spazio, oggetti e segnali di allarme","summary":"Pulisci i tuoi piani, scegli attrezzi tolleranti, riscalda e smetti in caso di dolore acuto, intorpidimento o vertigini.","imageAlt":"Figura 3D che fa roteare un bastone sopra la testa con spazio libero intorno","body":["Le arti del flusso hanno un rischio basso rispetto alla maggior parte degli sport, ma gli attrezzi si muovono velocemente e percorrono distanze più lunghe di quanto ti aspetti. Alcune abitudini mantengono la pratica sicura per te, per le persone vicino a te e per i mobili.","Pulisci lo spazio prima di iniziare. Controlla ogni piano che userai: davanti, ai lati e sopra. I bastoni e gli anelli hanno bisogno di più spazio di quanto pensi, di solito un cerchio di almeno la spanna delle braccia più la lunghezza dell'attrezzo in ogni direzione, senza nulla di fragile a portata di mano. Al chiuso, attento alle luci del soffitto e ai ventilatori; all'aperto, attento al terreno irregolare e ai passanti.","Usa attrezzi tolleranti durante l'apprendimento. Le palle da giocoleria a sacchetto di fagioli non rotolano via. I bastoni con estremità imbottite o in schiuma fanno meno male quando ti colpiscono la testa, cosa che accadrà. Un anello più grande e pesante gira più lentamente ed è più facile da mantenere. Passa a attrezzi più veloci o più spettacolari una volta che le basi sono automatiche.","Riscaldati prima di ogni sessione e aumenta gradualmente il volume. Lanciare e far girare sono movimenti ripetitivi, e un carico ripetuto su tessuti freddi è la causa più comune di dolori al polso e al gomito. Se aggiungi molta pratica all'improvviso, aggiungi anche giorni di riposo.","Interrompi se noti segnali di allarme: dolore acuto o elettrico, formicolio o intorpidimento alle mani, dolore che peggiora con il continuo movimento, vertigini o colpo alla testa con sintomi residui. I movimenti del collo e i rolli di contatto richiedono attenzione extra; imparali lentamente con un accessorio imbottito.","Questa app insegna la tecnica, non le cure mediche. Gravidanza, lesioni recenti, condizioni articolari o qualsiasi cosa ti preoccupi sono motivi per consultare un professionista qualificato prima di aggiungere nuovi carichi. Le performance con il fuoco sono una disciplina separata con la propria formazione sulla sicurezza; SynthFlow non la insegna."]},"warm-up":{"title":"Perché gli allenamenti pre-gioco sono importanti per il giocolaggio","summary":"Da due a cinque minuti di mobilità per polsi, braccia, spalle e anche rendono i giri più fluidi e proteggono le articolazioni.","imageAlt":"Figura 3D che fa cerchi lenti al polso con le braccia in avanti","body":["La pratica del flow sembra delicata, ma richiede molto a poche articolazioni. Giocare con i giocolieri ripete lo stesso lancio migliaia di volte; far girare il bastone muove i polsi attraverso la loro gamma completa; l'hooping fa oscillare la colonna vertebrale e i fianchi ad ogni orbita. Un tessuto caldo tollera molto meglio questa ripetizione rispetto a uno freddo.","Un buon riscaldamento per il flow è breve e specifico. I cerchi al polso in entrambe le direzioni preparano le articolazioni che svolgono la maggior parte del lavoro. I cerchi al braccio e i rotoli alle spalle risvegliano il cuffia dei rotatori e le scapole, che controllano il piano di ogni giro. I cerchi alle anche e le torsioni del tronco sono fondamentali per l'hooping. I semicerchi al collo, mai rotoli completi, alleviano la tensione causata dal fissare un motivo in alto.","Muoviti lentamente e al ritmo. I passaggi del riscaldamento in SynthFlow sono contati come tutto il resto, a un ritmo rilassato, così i primi minuti di una sessione allenano anche il tuo senso del tempo. Quando arriva il momento di usare gli accessori, ti stai già muovendo con la musica.","Concludi il riscaldamento con l'accessorio a metà velocità. Alcuni lanci lenti, un lento giro frontale o un grande giro lento dell'hoop collegano il lavoro di mobilità al movimento che stai per praticare, e ti dicono come si sente il tuo corpo oggi.","I riscaldamenti sono anche una transizione mentale. Gli stessi tre minuti all'inizio di ogni sessione diventano un segnale che la pratica è iniziata. Nei giorni impegnativi, il riscaldamento è talvolta l'intera pratica, e conta comunque."]},"anatomy-basics":{"title":"Il corpo dietro i giochi","summary":"Antebracci afferrano e rilasciano, spalle guidano il piano, il core ti mantiene fermo: una mappa in linguaggio semplice per il flow.","imageAlt":"Figura 3D che fa l'hooping in vita con la parte superiore del corpo rilassata","body":["Non hai bisogno di conoscere l'anatomia per giocolare, ma una mappa semplice ti aiuta a capire cosa si affatica, cosa riscaldare e cosa riposare. La sezione Muscoli di Learn ha un modello interattivo; questo articolo è il tour breve.","Le avambraccia fanno la maggior parte del lavoro fine. I muscoli sul lato palmare chiudono le dita e flettono il polso; i muscoli sul dorso dell'avambraccio aprono le dita e estendono il polso. Catturare e rilasciare, afferrare un bastone e farlo rotolare, avvengono tutti qui. La fatica dell'avambraccio è la sensazione più comune dopo una lunga sessione, ed è per questo che il suggerimento di una presa rilassata è così frequente.","Le spalle guidano. I deltoidi sollevano le braccia; il rotatore, quattro piccoli muscoli intorno alla giuntura, mantiene il braccio superiore centrato mentre si muove. I muscoli intorno alle scapole tengono stabile l'intero sistema. Quando un bastone si allontana dal suo piano, la causa è spesso la spalla, non la mano.","Il tronco ti mantiene calmo. Nel giocolaggio, un busto fermo impedisce al pattern di vagare. Nell'anello, i muscoli addominali e quelli della schiena spingono l'anello con piccole pulsazioni avanti e indietro. I fianchi e le gambe sono la tua base: le ginocchia flessibili assorbono i movimenti e ti permettono di spostare il peso senza disturbare il prop.","Anche gli occhi e l'orecchio interno contano. Il giocolaggio ti addestra a guardare i picchi, non le mani; la rotazione addestra l'equilibrio. Sessioni brevi con pause permettono a entrambi di adattarsi senza vertigini. Tratta questa mappa come alfabetizzazione, non come diagnosi, e consulta un professionista per il dolore che non si risolve."]},"biomechanics-safety":{"title":"Caviglie, spalle e carico ripetuto","summary":"Una presa rilassata, i polsi neutri e un aumento graduale del volume mantengono felici le articolazioni che fanno tutto il lavoro.","imageAlt":"Figura 3D che fa girare un bastone con una mano sopra il dorso della mano","body":["Le lesioni da flusso sono raramente drammatiche. Sono quasi sempre da sovraccarico: troppe ripetizioni, troppa presa, troppo poco riposo. La buona notizia è che gli stessi pochi abitudini prevengono la maggior parte di esse.","Rilassa la presa. Una palla da giocoliere ha bisogno solo di una pressione sufficiente per rimanere nella mano; un bastone ha bisogno di un anello allentato di dita in cui può rotolare. Stringere affatica i muscoli dell'avambraccio e carica i tendini al gomito. Se le nocche si sbiancano o gli avambracci bruciano dopo pochi minuti, allenta la presa e abbassa il ritmo.","Mantieni i polsi vicini alla posizione neutrale quando puoi. La rotazione porta i polsi attraverso ampi range, il che va bene in moderazione. Tenere i polsi alla fine del loro range per lunghi periodi, o forzare un polso rigido a ruotare, è ciò che li irrita. Lascia che il gomito e la spalla condividano il movimento.","Lascia che le spalle lavorino, ma non incurvarsi. I grandi cerchi vengono dall'articolazione della spalla; una spalla rialzata stringe e si affatica rapidamente. Controlla nello specchio o in modalità fotocamera che le spalle rimangano basse, specialmente nei movimenti sopra la testa come l'elicottero e il laccio.","Aumenta il volume gradualmente. Se di solito pratichi venti minuti, non saltare a due ore solo perché sta arrivando un festival. Aumenta il tempo totale di una quantità modesta ogni settimana e mantieni almeno un giorno facile. Cambia gli oggetti per distribuire il carico: il lavoro con l'anello riposa i polsi che il giocolaggio affatica.","Il dolore che scompare entro un giorno è un adattamento normale; il dolore che persiste, aumenta o si accompagna a intorpidimento non lo è. Riposa, riduci il volume e cerca consigli professionali se persiste. Questo è un'educazione, non un consiglio medico."]},"choosing-props":{"title":"Scegliere i tuoi primi accessori","summary":"I sacchetti di fagioli per il giocolaggio, un bastone leggero con imbottitura e un grande anello per adulti rendono i primi mesi molto più facili.","imageAlt":"Figura 3D che fa girare un anello intorno a una mano","body":["Gli oggetti adatti per principianti rendono l'apprendimento più veloce e meno frustrante. Non hai bisogno di attrezzature costose, ma alcune scelte sono importanti.","Per il giocolaggio, inizia con tre palline di fagioli da circa 60 a 130 grammi ciascuna. I sacchetti di fagioli non rimbalzano o rotolano via quando cadono, il che evita molte inseguimenti. Dovrebbero stare comodamente nel palmo della mano. Le palline da palcoscenico, più grandi, e le palline di silicone elastiche sono per dopo. Colori abbinati ti aiutano a vedere il pattern; tre colori diversi ti aiutano a seguire le singole palline quando impari i siteswap.","Per il bastone, uno spin staff per principianti è solitamente tra i 1,2 e i 1,5 metri, leggero, con estremità imbottite o in gomma. Come guida approssimativa, dovrebbe arrivare tra il petto e la spalla quando è in piedi. Un bastone più lungo e pesante gira più lentamente e in modo più fluido una volta che hai le basi, ma è più difficile da iniziare e fa più male quando ti colpisce. Una presa al centro aiuta.","Per l'anello, inizia più grande e pesante di quanto pensi. Un anello per principianti adulto arriva solitamente tra la vita e il petto quando è in piedi sul pavimento. Gli anelli più grandi ruotano più lentamente, dandoti tempo per trovare il ritmo per l'anello in vita. Anelli più piccoli e leggeri sono adatti per trucchi veloci fuori dal corpo una volta che sei a tuo agio.","Qualunque cosa tu scelga, assicurati che la gamma di tempi del movimento si adatti all'oggetto. Gli oggetti più pesanti di solito preferiscono tempi più bassi. Se la gamma confortevole dell'app sembra affrettata con il tuo oggetto, imposta il tuo tempo nel costruttore; i conteggi seguono."]},"practice-at-home":{"title":"Praticare a casa e al parco","summary":"Sessioni brevi e quotidiane, uno spazio libero, il bordo di un letto o un divano per prendere le cadute e un incontro in parco quando puoi.","imageAlt":"Figura 3D che muove le braccia tra i round di pratica","body":["La maggior parte degli artisti del flow impara a casa, per pochi minuti alla volta. Un po' di preparazione rende più facile iniziare e continuare la pratica a casa.","Trova il tuo posto. Per il giocolaggio, stare in piedi davanti a un letto o a un divano significa che le palle cadute arrivano all'altezza della vita invece di rotolare sotto i mobili, e ti impedisce anche di camminare in avanti. Per bastone e cerchio, trova lo spazio più grande e sgombro che hai, controlla il soffitto e sposta qualsiasi cosa possa rompersi. Un giardino o un parco è migliore per grandi rotazioni.","Tieni i prop visibili. Le palle sulla scrivania vengono giocolate durante le chiamate e le pause caffè; un cerchio vicino alla porta viene usato. Meno sforzo ci vuole per iniziare, più spesso lo farai. Una routine di cinque minuti conta, e diverse sessioni brevi al giorno si accumulano rapidamente.","Usa l'app come struttura. Scegli una routine o lascia che l'assistente ne suggerisca una, eseguila e registra il tuo sforzo. Programmi brevi come Zero to Cascade danno a ogni settimana un obiettivo chiaro, evitando che ti allontani tra i trucchi.","Pratica con altri quando puoi. Club di giocolaggio, scuole di circo e flow jam nei parchi esistono in molte città. Guardare qualcuno un passo avanti a te spesso risolve qualcosa che un tutorial non potrebbe, e insegnare a qualcuno un passo indietro a te rende la tua tecnica più chiara. Porta i tuoi prop, chiedi cosa stanno lavorando gli altri e condividi ciò che i conteggi ti hanno insegnato."]},"learning-with-the-app":{"title":"Imparare con l'allenatore 3D","summary":"Rallentalo, riflettilo, attiva il fantasma e le tracce, cambia la telecamera e usa la modalità camera per il feedback.","imageAlt":"Figura 3D che esegue un'isolazione con il bastone con una traccia che mostra il percorso","body":["Ogni movimento in SynthFlow è animato in 3D con lo stesso orologio della musica, quindi la figura è sempre esattamente sul tempo. Usato bene, lo spettatore è un insegnante paziente che non si stanca mai di mostrarti lo stesso lancio.","Rallentalo prima. La scala di progressione di ogni movimento inizia con versioni lente e parziali, poi solo con le mani, poi il movimento completo sul tempo. Mezza velocità mantiene intatte le relazioni temporali mentre dà agli occhi il tempo di seguire.","Rifletti la figura se impari meglio di fronte a un insegnante, e cambia la telecamera quando una vista nasconde qualcosa. Le viste laterali mostrano l'inclinazione del bastone e lo scivolamento del lancio; le viste dall'alto mostrano i piani del cerchio e i percorsi a elicottero. Le tracce disegnano dove ogni prop è stato, trasformando una sfocatura in una forma che puoi studiare. Il fantasma mostra dove il prop sarà sul prossimo battito.","Guarda gli errori comuni. Ogni movimento può mostrare i suoi difetti tipici, come spostarsi in avanti, altezze irregolari o fretta, eseguiti deliberatamente in modo errato sulla figura, con il suggerimento che li corregge. Riconoscere un difetto sul modello rende molto più facile percepirlo nel proprio corpo.","La modalità telecamera fornisce feedback su di te. Con il permesso, traccia le tue mani e il tuo corpo durante la pratica e confronta il tuo tempo con il battito. L'elaborazione avviene sul tuo dispositivo. Non è perfetta, e una buona illuminazione aiuta, ma anche un feedback approssimativo su se sei in anticipo o in ritardo è prezioso.","Infine, a volte chiudi il visualizzatore. Pratica solo con la musica e fidati dei conti. L'obiettivo è un movimento che puoi eseguire senza guardare nulla."]},"music-for-flow":{"title":"Trovare la musica giusta","summary":"Tempi misurati, tempo dimezzato e raddoppiato, percussioni generate e le tue tracce mantengono i conti in linea.","imageAlt":"Figure a 3D che ruotano al petto con le braccia alzate","body":["La musica trasforma la pratica in flusso, ma solo se il battito della musica è lo stesso del battito dei conti. Una traccia a 118 BPM sotto una routine a 120 BPM si allontana in un minuto, e finisci per combattere la musica invece di cavalcarla.","Le tracce incluse in SynthFlow hanno tempi misurati e downbeat, così il giocatore può iniziare ogni passo sul \\"uno\\" della musica e mantenere i conti allineati. Il costruttore elenca per prima le tracce che si adattano al tempo di una sezione, incluse tracce a metà o doppio tempo: una traccia a 140 BPM porta perfettamente un passo di anello a 70 BPM.","La percussioni generate funzionano a qualsiasi tempo. Scegli un set per una sezione e il giocatore sintetizza un battito che corrisponde esattamente, sia che tu stia facendo una scala di tempi o un esercizio lento. È anche la migliore opzione quando vuoi il battito senza che la melodia attiri la tua attenzione.","Puoi analizzare tracce dal tuo dispositivo. L'app stima il tempo e il downbeat e ti permette di verificarli battendo il tempo. Le tracce con un impulso elettronico o acustico costante funzionano meglio; la musica con cambiamenti di tempo, rubato o lunghi intro è più difficile da misurare e più difficile da praticare.","La trasmissione video è disattivata durante la pratica con conti perché il suo tempo non può essere controllato con precisione. Usala per riscaldamenti o gioco libero, dove nulla deve allinearsi."]},"plateaus":{"title":"Pianure e la lunga parte centrale","summary":"Ogni artista del flusso incontra settimane in cui non si migliora nulla; cambia l'esercizio, il tempo o il prop prima di cambiare l'obiettivo.","imageAlt":"3D figure di juggling Mills Mess con braccia incrociate","body":["L'inizio del flusso è meraviglioso: qualcosa di nuovo ogni sessione. Poi, spesso intorno al momento in cui si riesce a far girare una cascata costante o a tenere un cerchio in aria indefinitamente, la progressione sembra fermarsi. Questa lunga fase intermedia è dove la maggior parte delle persone abbandona, e dove avviene l'apprendimento più interessante.","Le piattaforme sono di solito una fase di consolidamento. Il sistema nervoso sta riorganizzando il movimento in modo che richieda meno attenzione, il che non si manifesta con nuovi trucchi. Spesso una capacità che sembrava bloccata per due settimane appare improvvisamente una mattina. Continua a praticare anche durante la fase piatta.","Cambia l'esercizio, non l'obiettivo. Se la cascata non diventa più veloce, esercitati a un ritmo più basso con picchi perfetti, poi con gli occhi fissi su un punto sopra il pattern, poi con una mano sola. Se un movimento con il bastone non arriva, dividilo in due metà e esercitati su ciascuna al ritmo. Nuovi esercizi danno al cervello nuove informazioni sulla stessa abilità.","Allena in modo diverso. Imparare un secondo oggetto spesso sblocca il primo. Far girare il cerchio migliora il ritmo dietro al giocoliere; il lavoro con il bastone insegna i piani che rendono i trucchi con il cerchio puliti. L'albero dei premi per ogni arte è indipendente, quindi la varietà non costa mai progresso.","Sii gentile con te stesso. Confrontati con te stesso di un mese fa, non con i performer online che hanno praticato per dieci anni. La pagina dei progressi tiene un registro onesto di minuti, tempi massimi e movimenti padroneggiati. In una settimana piatta, guardala e vedi quanto l'andamento è già salito."]},"history-of-juggling":{"title":"Una breve storia del giocolaggio","summary":"Da un dipinto tombale egiziano a giocolieri medievali, teatro vario e matematica moderna.","imageAlt":"Figura 3D che giocola una doccia a tre palle in cerchio","body":["Il giocoliere è molto antico. Una delle prime immagini conosciute è un affresco in una tomba del Regno Medio a Beni Hasan in Egitto, di circa quattromila anni fa, che mostra donne che lanciano palle. Testimonianze e immagini dalla Cina, dalla Grecia, da Roma e dal Pacifico suggeriscono che persone di molte culture abbiano trovato il modo di lanciare e prendere per spettacolo e gioco.","Nell'Europa medievale la parola jongleur, da cui deriva \\"giocoliere\\", descriveva artisti itineranti che cantavano, raccontavano storie, eseguivano acrobazie e lanciavano oggetti. Il giocoliere era una delle tante abilità, parte dello strumento del performer piuttosto che un'arte a sé stante.","I vari teatri e circhi del diciannovesimo e del primo ventesimo secolo resero il giocolaggio uno spettacolo di prima pagina. I prestigiatori si specializzarono: giocolieri gentiluomini con cappelli e bastoni, giocolieri con i bastoni, e giocolieri che arrivavano a sette, otto o più palle. Enrico Rastelli, all'inizio del ventesimo secolo, è ancora spesso considerato uno dei più grandi.","A partire dagli anni '70, una cultura del giocolaggio come hobby crebbe intorno a club, festival e convention, con persone che condividevano liberamente trucchi. La matematica si unì negli anni '80 quando la notazione siteswap diede ai giocolieri un modo per scrivere i pattern come numeri, portando a nuovi trucchi scoperti sulla carta prima che qualcuno li lanciasse.","Oggi il giocolaggio si trova al crocevia tra circo, sport, danza e matematica. Alcuni giocolieri competono in base al numero e all'endurance, altri eseguono coreografie con la musica, altri esplorano i pattern per se stessi. Ogni percorso inizia con lo stesso scambio di due palle, che puoi imparare questa settimana."]},"history-of-staff":{"title":"Rotazione del bastone: dallo strumento di combattimento al flusso","summary":"Le arti marziali con bastone, il twirling del bastone e le performance con il fuoco hanno contribuito allo sviluppo del moderno flow staff.","imageAlt":"Figura 3D che esegue una farfalla con il bastone dietro le spalle","body":["Un bastone è uno degli strumenti più antichi che esistano, e farlo girare è una vecchia abilità. Molte tradizioni marziali addestrano con un bastone lungo, tra cui il bō di Okinawa, il gun cinese e il combattimento con il bastone da quarto europeo, e i loro esercizi includono giri veloci e cambi di mano sia per la difesa che per lo spettacolo.","Anche il twirling di bastone ha altre radici. Il twirling del bastone si trasformò in una disciplina competitiva nel ventesimo secolo, con lanci, rotolamenti e giri che i twirlers continuano a prendere in prestito. Teatri, sfilate e spettacoli di strada in tutto il mondo usarono bastoni e pali girati molto prima che qualcuno li chiamasse flow.","La scena moderna del flow staff nacque alla fine del ventesimo secolo insieme alle performance con il fuoco e alla cultura dei festival. I bastoni con il fuoco, con le stoppe ad entrambe le estremità, resero visibile il giro al buio e spinsero l'arte verso movimenti fluidi e continui piuttosto che colpi. I bastoni LED portarono in seguito le stesse immagini all'interno.","Nello stesso periodo, gli artisti del flow iniziarono a descrivere il twirling con una teoria condivisa: piani, giri e antirigiri, isolamenti, tempismo e direzione. Gran parte di questo fu sviluppato nella comunità dei poi e trasferito al bastone, al cerchio e ad altri oggetti, motivo per cui le stesse parole compaiono in tutta l'app.","Il contatto con il bastone, in cui il bastone rotola sul corpo invece di essere afferrato, si è sviluppato in uno stile autonomo con rotolamenti sul collo, sulle spalle e sulle braccia. Oggi la rotazione del bastone va dalla dimostrazione marziale a un flusso meditativo lento e di contatto, tutto basato sulla stessa prima rotazione della ruota."]},"history-of-hoop":{"title":"Il cerchio: dal giocattolo antico all'arte del flusso","summary":"Gli anelli sono stati giocattoli e strumenti per millenni; una mania degli anni '50 e un rinnovamento nei festival hanno trasformato la danza con l'anello in un'arte.","imageAlt":"Figura 3D che cammina con un anello rotante lungo il corpo","body":["Gli anelli sono tra i giocattoli più antichi. I bambini nell'antico Egitto, Grecia e Roma sono descritti o raffigurati mentre fanno rotolare anelli con bastoncini e li fanno girare intorno al corpo, e giochi con gli anelli compaiono in molte culture da allora.","Gli anelli hanno anche un profondo significato culturale in alcune tradizioni. La Danza dell'Anello, eseguita in molte comunità native americane, utilizza più anelli per creare forme come animali e la terra, raccontando storie attraverso il movimento. È una tradizione vivente a sé stante, distinta dalla scena moderna del flusso, e vale la pena impararla dai suoi stessi praticanti.","La mania del hula hoop di plastica della fine degli anni '50, guidata da anelli prodotti in massa negli Stati Uniti, ha portato un anello in milioni di case quasi in un giorno. Per decenni dopo, l'anello è stato visto principalmente come un giocattolo per bambini e un gadget fitness.","Dalla fine degli anni '90 e 2000, gli adulti che usavano l'anello nei festival e nelle comunità online hanno iniziato a considerare l'anello come un partner di danza. Anelli più grandi e pesanti fatti a mano hanno reso più facile l'uso dell'anello sul corpo per gli adulti, mentre anelli più piccoli hanno aperto la strada a trucchi veloci fuori dal corpo. I video condivisi hanno diffuso vocaboli come isolazioni, wedgies e escalators ben oltre qualsiasi singola città.","La danza con l'anello moderna attinge teoria dal bastone e dal poi e ritmo da ogni tipo di musica. È accessibile, gioiosa e profonda: un principiante può trovare il ritmo della vita in un giorno, e un esperto può impiegare anni a perfezionare una singola isolazione."]},"fire-and-led":{"title":"Fuoco, LED e accessori per spettacoli","summary":"I prop di performance cambiano peso, velocità e rischio; impara ogni movimento prima con i prop di pratica e addestra il fuoco separatamente.","imageAlt":"Figura 3D che fa girare un anello in verticale sopra la testa come un laccio","body":["Guardare uno staff di fuoco o un anello LED di notte è spesso ciò che attira le persone nel flusso. I prop di performance sono meravigliosi, ma non sono gli stessi dei prop di pratica, e passare a loro merita un piano.","I prop LED sono di solito più pesanti delle loro versioni di pratica a causa delle batterie e degli elettronici. Questo cambia la quantità di moto: i giri durano più a lungo, i lanci si sentono diversamente e i polsi lavorano di più. Impara ogni movimento prima con il tuo prop di pratica, poi aspettati un breve periodo di adattamento con quello LED. Abbassa il ritmo nelle prime sessioni.","La performance con il fuoco è una disciplina separata. La gestione del combustibile, le aree sicure per i giri, i soccorritori con coperte antincendio, l'abbigliamento adatto e le norme locali sono tutti fattori importanti, e sono meglio appresi di persona da artisti esperti con fuoco. SynthFlow non insegna il fuoco, e nulla nell'app deve essere praticato con oggetti accesi.","Una buona regola usata in molte comunità di flow è eseguire un movimento con un prop da performance solo quando si è in grado di farlo in modo affidabile, molte volte di seguito, con un prop di pratica. Sotto luci o fiamme non c'è spazio per gli esperimenti.","Anche la sequenza cambia in una performance. Il pubblico legge grandi piani, transizioni pulite e momenti chiari di immobilità. Costruisci le routine di performance nel costruttore come qualsiasi altra, visualizzale, e prova con la stessa musica ogni volta in modo che i conteggi diventino coreografia."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"Il giorno in cui la cascata ha fatto scattare","summary":"Tre settimane di inseguimento di palle sul pavimento sono finite nel momento in cui ho smesso di guardare le mie mani e ho iniziato a contare.","body":["Per tre settimane la mia cascata di tre palle durava esattamente quattro lanci. Destra, sinistra, destra, e poi la terza palla era da qualche parte dietro il divano. Ho guardato video, ho rallentato, ho accelerato. Mi sono messo davanti al letto come dicono tutti i tutorial. Niente cambiava, tranne il mio vocabolario.","La soluzione, quando è arrivata, è stata imbarazzantemente semplice. Ho messo una traccia a 90 BPM e ho detto i conteggi ad alta voce: uno, due, tre, quattro, un lancio su ogni battito. All'improvviso i lanci avevano un posto dove andare. Invece di lanciare quando la mano si sentiva pronta, il che significava ogni volta che il panico glielo diceva, ogni lancio aspettava il suo battito. Il pattern diventò più lento, più alto e più calmo.","La seconda soluzione fu dove guardavo. Stavo fissando le mie mani, il che è come leggere un libro guardando le palpebre. Quando ho alzato lo sguardo verso i picchi, i due punti in cima alle traiettorie, le mie mani hanno iniziato a prendere da sole. I picchi mi dicevano se i lanci erano regolari; le mani non avevano bisogno di supervisione.","Dodici lanci divennero venti, poi cinquanta. Una sera ho giocolato attraverso un intero passo di otto battute senza far cadere nulla e ho sorriso al soffitto come uno stupido. L'app lo ha definito un percorso pulito. Io l'ho chiamato la prima volta in cui giocolare è sembrato musica invece di una lotta.","Se sei bloccato a quattro lanci, prova quello che ha funzionato per me: conta ad alta voce, lancia sul battito, guarda i picchi. E lascia cadere senza drammi. Il pavimento è dove ogni cascata inizia."]},"why-we-count-in-bars":{"title":"Perché contiamo in battute, non in secondi","summary":"Una presa di quaranta secondi ha senso per un allungamento; un pattern di giocoleria vive su un battito, quindi misuriamo la pratica in battute.","body":["Quando abbiamo iniziato a costruire SynthFlow, la prima grande decisione è stata come misurare un passo della routine. La nostra app sorella SynthYoga conta le pause in secondi e respiri. Funziona per una posa che si mantiene. Non funziona per un pattern che si ripete sul battito.","Un lancio di giocoleria, mezzo giro di bastone e un'orbita dell'anello sono tutti cicli. Se la musica va a 100 BPM e la tua cascata va a 103, non stai giocolando con la musica; stai giocolando vicino ad essa, e in un minuto sei un battito indietro. Misurare i passi in battute a una certa tempistica significa che la musica, i conti, la figura 3D e il prossimo passo iniziano tutti sullo stesso battito.","Le battute rendono anche i progressi concreti. \\"Giocola per un minuto\\" è vago: un minuto di cosa, a quale velocità? \\"Otto battute di cascata a 96 BPM\\" è una sfida specifica e ripetibile. Se la gestisci in modo pulito, la sessione successiva può chiedere 104. È così che funzionano le scale di tempistica, ed è per questo che la maestria nell'app dipende da esecuzioni pulite piuttosto che solo dal tempo.","Ci è voluta una seria ingegneria. Ogni animazione è guidata dalla stessa clock audio della musica, programmata in anticipo in modo che nulla si blocchi. Le tracce incluse hanno tempi e battiti misurati. La percussion generata riempie qualsiasi tempistica tu scelga. Le tracce dal tuo dispositivo vengono analizzate e verificate con un test di battito. Il video in streaming viene disattivato nella pratica contata perché non possiamo mantenerlo sul battito.","Il risultato è che il battito diventa un insegnante. Quando ti allontani, lo senti. Quando ti concentri, lo senti. Contare in battute si è rivelato la scelta di progettazione più importante che abbiamo fatto."]},"staff-hit-me-in-the-head":{"title":"Il bastone mi ha colpito in testa (e altre lezioni)","summary":"Ogni giocoliere di bastone si prende un colpo; imbottitura, piani e pazienza trasformano i colpi in progresso.","body":["La mia prima figura a otto è finita con il bastone che rimbalzava sulla mia testa e il cane che lasciava la stanza. La seconda è finita allo stesso modo, senza il cane. Se stai imparando a usare il bastone, ti prenderai un colpo. La domanda è quanto forte, e cosa ne impari.","Lezione uno: l'imbottitura non è codardia. Un bastone da pratica con estremità morbide ha trasformato i colpi da gridi in spalle alzate. Alzare le spalle conta, perché la paura ti fa sussultare, e un polso che sussulta fa uscire il bastone dal suo piano, causando il colpo successivo.","Lezione due: la maggior parte dei colpi proviene da piani inclinati. Quando mi sono filmato di lato, ho visto che il bastone si inclinava verso il mio viso in cima a ogni giro. I polsi ruotavano verso l'interno. La sovrapposizione del piano nella visualizzazione 3D mostrava la versione pulita: il bastone in una superficie piatta accanto al corpo, mai inclinato. Correggendo il polso ho risolto i colpi.","Lezione tre: lento e contando, veloce e speranzoso. Ho abbassato il tempo all'estremo inferiore della gamma della figura a otto e ho contato \\"lato destro, lato sinistro\\" con la musica. A quella velocità riuscivo a sentire il cambio di mano e a mantenere il piano piatto. Una settimana dopo potevo tornare a velocità più elevate.","Lezione quattro: ridi. Far girare il bastone è assurdo e meraviglioso. I colpi fanno parte della storia che tutti nella scena condividono. Indossa un cappello se necessario, libera le luci del soffitto e continua a farlo girare."]},"hooping-for-people-who-cant-hoop":{"title":"Hoop per chi pensa di non saper farlo","summary":"La maggior parte degli adulti che \\"non sanno far girare il cerchio\\" hanno usato un cerchio di dimensioni da bambino; un cerchio più grande e un movimento avanti e indietro risolvono la maggior parte dei problemi.","body":["\\"Non so far girare il cerchio\\" è qualcosa che gli insegnanti di cerchio sentono costantemente, di solito da qualcuno che ha provato con un cerchio giocattolo da bambino. I cerchi piccoli e leggeri girano velocemente e cadono velocemente. Richiedono fianchi veloci e frenetici. Gli adulti con un cerchio di dimensioni adulte spesso lo trovano molto più gestibile.","Inizia grande. Un cerchio che arriva approssimativamente tra la vita e il petto quando è posizionato sul pavimento gira abbastanza lentamente da permetterti di sentire il ritmo. I cerchi più pesanti hanno anche più momento. Puoi passare a cerchi più piccoli in seguito per velocità e trucchi fuori dal corpo.","Pulsare, non girare. L'errore più comune è cercare di fare grandi cerchi con i fianchi. Il cerchio in vita di solito è un piccolo movimento avanti e indietro, o da un lato all'altro, in sincronia con il cerchio. Un piede leggermente avanti aiuta. Il cerchio tocca la parte anteriore e posteriore; spingi delicatamente mentre gira.","Conta. Un ritmo rilassato, un'orbita per battito, dà al tuo corpo un ritmo in cui stabilizzarsi. L'app inizia con il cerchio in vita lento, poi ti permette di salire. Se il cerchio scende, aggiungi un po' di velocità al tuo pulsare, non un movimento più grande.","Aspettati che cada spesso per qualche sessione, poi improvvisamente non cada più. Far girare il cerchio è una di quelle abilità che si attivano. Una volta che succede, c'è un intero mondo di flussi sul corpo e fuori dal corpo che ti aspetta, e molte di queste non richiedono nemmeno la vita."]},"unlocking-is-not-a-race":{"title":"Sbloccare non è una gara","summary":"L'albero dei premi sblocca movimenti più difficili man mano che padroneggi le basi; il punto sono le basi.","body":["I premi di SynthFlow sono movimenti. Masterizza la cascata e si apre la cascata inversa; masterizza la rotazione frontale e appare l'otto. È soddisfacente vedere l'albero illuminarsi, ed è così che l'abbiamo progettato. Ma in ogni sistema di sblocco c'è una trappola, e vale la pena nominarla.","La trappola è trattare la maestria come una casella da spuntare. Puoi tecnicamente registrare le esecuzioni pulite di un movimento in una buona giornata, sbloccarne il successivo e andare avanti con una base che funziona solo quando tutto va bene. Poi i movimenti più difficili sembrano impossibili, perché presuppongono che la base funzioni anche quando le cose vanno storte.","La maestria nel flusso significa che il movimento resiste alle distrazioni: un po' di stanchezza, un ritmo diverso, qualcuno che passa. Ecco perché la maestria richiede esecuzioni pulite attraverso sessioni, non solo in una. Ed è per questo che suggeriamo di tornare regolarmente ai movimenti già padronati. La cascata non è un livello da completare; è la base su cui poggia l'intero albero del giocolaggio.","I movimenti bloccati hanno comunque delle pagine. Puoi leggerne, vederli in 3D e capire cosa richiedono. Guardare avanti è motivante. Praticare in anticipo, senza le basi, è per lo più frustrante.","Quindi goditi gli sblocchi, ma misura te stesso in base a quanto semplici ti sembrano i tuoi movimenti più vecchi. Quando la cascata è noiosa, sei pronto per Mills Mess. Quando Mills Mess è noiosa, l'albero ha ancora qualcosa da offrire."]},"practice-in-ten-minutes":{"title":"Una vera pratica in dieci minuti","summary":"Riscaldamento, un movimento di focus, un collegamento, una breve salita di tempo e un raffreddamento: dieci minuti, ogni giorno.","body":["La ragione più comune che le persone danno per non praticare è il tempo. La verità è che le abilità di flusso rispondono brillantemente a sessioni brevi e frequenti. Ecco la struttura di dieci minuti che usiamo noi stessi.","Minuto uno a due: riscaldamento. Rotazioni di polso, rotazioni di braccio, rotazioni di spalla, qualche rotazione di anca se fai il cerchio. Contate, a un ritmo rilassato, così il tuo tempo si risveglia con le articolazioni.","Minuto tre a cinque: il tuo movimento di focus. Un movimento su cui stai lavorando, a un ritmo che puoi eseguire in modo pulito. Diversi passaggi brevi e contati piuttosto che uno lungo, con un respiro tra di essi.","Minuto sei a sette: un collegamento. Abbinare il movimento di focus con qualcosa in cui fluisce dentro o fuori. Cascata a cascata inversa. Rotazione frontale a otto. Vita a petto. I collegamenti sono ciò che rende la pratica simile al flusso invece che a degli esercizi.","Minuto otto a nove: una piccola salita di tempo. Due o tre gradini, qualche BPM ciascuno, fermarsi prima che la forma si rompa. Terminare su un gradino pulito.","Minuto dieci: raffreddamento. Un movimento lento e facile o un breve riposo. Registra il tuo sforzo. Fatto.","Dieci minuti al giorno equivalgono a più di un'ora a settimana di pratica concentrata, distribuita nel modo preferito dalla coordinazione. Il wizard della pratica crea sessioni di questa durata quando gli dici di avere poco tempo, e le routine brevi integrate seguono la stessa struttura."]},"antispin-broke-my-brain":{"title":"Antispin mi ha fatto perdere la testa (per una settimana)","summary":"Far ruotare il bastone contro il cerchio della mano sembra impossibile finché i conti non danno a ogni petalo un battito.","body":["L'antispin è dove la rotazione del bastone inizia a sembrare compito di geometria. La mano traccia un cerchio in un senso mentre il bastone gira nell'altro, e le estremità disegnano un fiore. La prima volta che ci ho provato, ho ottenuto qualcosa di più simile a un dente di leone appassito.","Ciò che mi ha aiutato è stato rendere la forma contabile. Un antispin a quattro petali ha quattro momenti in cui un'estremità punta dritta fuori dal cerchio. Ho dato a ciascuno un battito: alto, lato, basso, lato. Poi ho rallentato la musica ben al di sotto del mio ritmo normale di rotazione e ho semplicemente mirato alle posizioni sul battito.","Il fantasma nella visualizzazione 3D, che mostra dove il bastone dovrebbe essere sul prossimo battito, è stato il mio migliore amico quella settimana. Lo stesso vale per la scia, che disegnava il mio fiore così potevo vedere quando i petali erano sbilanciati. Di solito il petalo inferiore era schiacciato, perché stavo affrettando la parte inferiore del cerchio.","Dopo circa una settimana, qualcosa è cambiato. Ho smesso di pensare alla mano e al bastone come a due cose separate e ho iniziato a sentire il fiore come una forma unica. Il ritmo è tornato da solo.","Se l'antispin ti fa impazzire, è normale. Dai a ogni petalo un battito, rallenta la musica e lascia che il tuo corpo lo risolva. È una delle sensazioni migliori nel flusso quando succede."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps per chi odia la matematica","summary":"Non devi amare la matematica per usare i siteswap; devi solo sapere che i numeri più grandi vanno più in alto.","body":["La notazione siteswap ha la reputazione di spaventare le persone. I giocolieri diranno allegramente \\"prova 531\\" come se spiegasse qualcosa. Lo fa, ma solo dopo che sai un paio di cose, e queste cose sono più semplici di quanto sembrino.","Ecco quasi tutto ciò che ti serve. Ogni numero è un lancio. I numeri più grandi vanno più in alto. I numeri dispari passano all'altra mano; i numeri pari tornano alla stessa mano. Un 3 è un lancio normale in cascata. Un 1 è un rapido passaggio. Un 2 di solito è solo tenere la palla.","Questo è sufficiente per leggere 441: due lanci più alti che rimangono sul loro lato, poi un passaggio attraverso. Ora puoi provarlo senza leggere un'altra parola. Lancio, lancio, passaggio, sul battito.","Se vuoi un altro pezzo: somma i numeri e dividi per quanti sono, e ottieni il numero di palle. 4 + 4 + 1 = 9, diviso per 3 fa 3 palle. Se la risposta non è un numero intero, il pattern non può essere giocolato. Questo è tutto il famoso teorema della media.","In SynthFlow, ogni movimento di giocoleria ha un siteswap, e il motore 3D anima direttamente da esso. Ciò significa che la figura lancia sempre esattamente le altezze descritte dai numeri, sui battiti esatti. Guardare un siteswap animato lentamente è il modo più veloce che conosciamo per far sì che i numeri abbiano senso. Non è richiesto un diploma in matematica."]},"music-that-fights-you":{"title":"Quando la musica ti combatte","summary":"Una traccia che si discosta dai tempi rende ogni movimento più difficile; tempi misurati e battiti generati lo risolvono.","body":["Probabilmente l'hai già sentito: una canzone che ami, un movimento che conosci, e in qualche modo tutto sembra sbagliato. Ti affretti, lasci cadere, ti incolpi. Spesso il problema non sei tu. È che il tempo della canzone non corrisponde al movimento.","Ogni movimento di flusso ha una gamma di tempo confortevole. Al di sotto, le prop in rotazione si bloccano; al di sopra, i lanci diventano bassi e frenetici. Una traccia a 128 BPM sotto un movimento con anello che preferisce 90 ti chiede di scegliere tra la musica e l'anello. La buona notizia è che il tempo dimezzato e raddoppiato aiutano: 128 può portare un movimento a 64, un ciclo ogni due battiti.","Il problema più sottile è lo slittamento. Se la musica dice 120 ma i tempi dicono 116, i due si allontanano nel giro di un minuto, e il tuo corpo non può seguire entrambi. Ecco perché SynthFlow utilizza tempi misurati per le sue tracce incluse, genera percussioni a qualsiasi tempo esatto e verifica le tracce dal tuo dispositivo con un test di battito.","Quando una traccia ti resiste, non reagire. Passa al battito generato per il passo, o lascia che il costruttore suggerisca una traccia nella gamma giusta. Tieni le canzoni che ami per il gioco libero, dove nulla deve allinearsi.","La musica dovrebbe sentirsi come un partner. Se sembra un avversario, cambia la musica, non il tuo movimento."]},"learning-alongside-my-kid":{"title":"Imparare a giocolare insieme a mio figlio","summary":"Due principianti, un sacchetto di palle e una regola: celebriamo le cadute con altrettanto entusiasmo delle prese.","body":["Mia figlia ha chiesto di imparare a giocolare, e ho capito che nemmeno io sapevo farlo. Così abbiamo imparato insieme, dieci minuti dopo cena, con tre sacchetti di fagioli ciascuno e una regola: festeggiamo le cadute con altrettanto entusiasmo delle prese.","La regola sembra sciocca. Si è rivelata la parte più importante. I bambini, e gli adulti, si irrigidiscono quando pensano che un errore sia imbarazzante. La tensione peggiora i lanci. Festeggiare ogni caduta ha trasformato il pavimento in parte del gioco e ci ha tenuti entrambi rilassati.","Abbiamo iniziato con una palla, lanciandola da una mano all'altra al ritmo, con picchi all'altezza degli occhi. Per circa tre sessioni è sembrato troppo facile, poi all'improvviso è diventato importante, perché gli scambi con due palle funzionano solo se i lanci singoli sono costanti. Lei ha capito lo scambio prima di me ed è stata insopportabile al riguardo.","La musica ritmata ci ha aiutato a praticare insieme. Stesso tempo, stessa battuta, due persone che lanciano in sincronia. Quando uno di noi perdeva il ritmo, l'altro continuava, e chi perdeva riprendeva al prossimo \\"uno\\".","Dopo quattro settimane, entrambi abbiamo una cascata traballante. Ma soprattutto, abbiamo una routine a cui entrambi guardiamo con entusiasmo. Se hai un bambino che vuole imparare qualcosa, impara con lui. Essere principianti insieme è sottovalutato."]},"why-your-throws-drift-forward":{"title":"Perché i tuoi lanci si spostano in avanti","summary":"Se finisci ogni cascata a tre passi da dove sei partito, i tuoi lanci si stanno inclinando lontano da te. Ecco come riportarli a casa.","body":["Ogni giocoliere conosce la camminata. Inizi la cascata nel mezzo della stanza e la finisci con il naso contro il muro, inseguendo il pattern di un passo alla volta. Sembra che le palle ti stiano tirando. Non è così. Le stai lanciando in avanti, di pochi centimetri alla volta, e poi cammini per raggiungerle.","La causa è quasi sempre i gomiti. Quando ti irrigidisci, gli avambracci si inclinano in avanti e le mani rilasciano la palla leggermente davanti al corpo. Ogni lancio atterra un po' più lontano, quindi il prossimo rilancio avviene più lontano, quindi il lancio successivo parte più lontano. Si accumula rapidamente.","La soluzione che insegno per prima è la piegatura dei gomiti. Tieni i gomiti vicino alle costole, gli avambracci approssimativamente orizzontali, e lancia le palle dritte verso l'alto oltre gli occhi, piuttosto che in avanti. All'inizio sembra stretto. Poi sembra calmo.","La seconda soluzione è un muro. Mettiti di fronte a esso, a circa un avambraccio di distanza, e giocola. Se i lanci si spostano, il muro te lo fa sapere immediatamente e forte. Dieci minuti di pratica con il muro insegnano al corpo cosa significa un pattern verticale più velocemente di qualsiasi cosa io possa dire.","La modalità fotocamera di SynthFlow rileva anche lo spostamento. Monitora quanto più grande appare il tuo busto alla telecamera in un passo, il che significa che stai camminando verso di essa, e ti dà un piccolo suggerimento. Il coach 3D può anche mostrare l'ombra di un lancio in avanti accanto a quello pulito, così puoi vedere la differenza invece di sentirla solo.","Lo spostamento non è un difetto di carattere. È un'abitudine di tensione, e le abitudini cambiano con la ripetizione. Piega i gomiti, lancia in alto e non in avanti, e lascia che il muro ti tenga onesto."]},"practising-to-a-click":{"title":"Praticare con un clic","summary":"Un metronomo sembra la cosa meno divertente del mondo. Si è rivelata la cosa che ha fatto sentire il mio flusso come una danza.","body":["Ho resistito al click per anni. La musica era il punto centrale delle flow arts per me, e un metronomo sembrava compito. Poi un'amica che suona la batteria mi ha visto giocolare e ha detto, gentilmente, che acceleravo ogni volta che mi eccitavo e rallentavo ogni volta che avevo paura. Aveva ragione, e io non lo sapevo.","Così ho provato una settimana di pratica solo con un click. La prima scoperta è stata che un battito costante è più difficile di quanto sembri. Il mio pattern due-in-una-mano voleva affrettarsi. La mia figura a otto con il bastone voleva trascinarsi sul lato debole. Il click non si curava di come mi sentivo; teneva semplicemente il tempo.","La seconda scoperta è stata che il click rendeva la musica più facile. Dopo una settimana, quando ho rimesso le tracce reali, potevo sentire dove si trovava il ritmo all'interno del suono. Ho smesso di combattere le canzoni con un tempo sciolto e ho iniziato a scegliere quale parte del groove bloccare.","La percussion generata da SynthFlow è una versione più amichevole del click. Scegli un set, da un click semplice a tamburi a mano, e suona a qualsiasi tempo, così un pattern può vivere esattamente alla velocità che riesci a mantenere. Può anche funzionare in modo silenzioso sotto una traccia musicale come guida. Lo uso ancora da solo per i primi minuti di ogni sessione.","Se vuoi provare questo, scegli un pattern e un tempo che sembrano leggermente troppo lenti. Conta ad alta voce per quattro battute, poi smetti di contare e ascolta solo. Quando il pattern e il click sembrano un suono solo, aggiungi quattro BPM. Questo è l'intero metodo."]},"staff-in-a-small-apartment":{"title":"Staff in un piccolo appartamento","summary":"Un bastone di 1,4 metri e un soffitto di 2,4 metri possono convivere. Devi solo scegliere i tuoi piani.","body":["Il mio appartamento ha soffitti bassi, un lampadario di cui sono affezionato e un vicino di sotto che lavora di notte. Niente di tutto ciò è ideale per la rotazione del bastone. Ho praticato nei parchi per un anno prima di capire che gran parte della mia formazione poteva avvenire in casa.","Il trucco sono i piani. Le rotazioni nel piano della ruota, quelle grandi accanto al corpo, richiedono l'altezza totale del bastone sopra la testa. Il lavoro nel piano della parete davanti al corpo richiede larghezza ma meno altezza. Le rotazioni nel piano del pavimento, come l'elicottero, richiedono spazio sopra la testa ma niente intorno alle caviglie. Ogni stanza supporta movimenti diversi.","Nel mio soggiorno posso fare isolazioni, giri frontali e figure a 8 lente con le braccia basse. Nel corridoio non posso fare nulla, quindi il corridoio è riservato agli riscaldamenti dei polsi. La camera da letto ha il soffitto più alto, quindi lì faccio i movimenti con la ruota, lentamente, con la lampada rimossa e riposta in un cassetto.","Anche i bastoni corti aiutano. Un bastone da pratica più corto di una mano rispetto al bastone da esibizione ha trasformato molti quasi fallimenti in passaggi facili. Il tempo cambia un po', quindi controllo il bastone lungo fuori casa una volta alla settimana.","Per i vicini: tappetini da pratica e bastoni con estremità morbide. Una caduta su un tappetino da yoga produce un tonfo sordo invece di uno schiocco. Mantengo anche le sessioni indoor entro routine contate di dieci minuti, il che limita il rumore e mantiene la pratica concentrata.","SynthFlow ti permette di segnare i movimenti che non puoi fare a casa come non graditi, così il generatore li esclude dalle routine indoor. Gli spazi piccoli non fermano il progresso. Ti rendono solo molto bravi negli isolamenti."]},"hooping-after-40":{"title":"Hoop dopo i 40","summary":"Ho preso in mano un cerchio per la prima volta a 43 anni. La mia schiena, le mie ginocchia e il mio orgoglio avevano tutte delle opinioni. Ecco cosa ha funzionato.","body":["Ho comprato il mio primo cerchio da adulto per impulso dopo un festival, convinto che sarei stato pessimo. Ero pessimo. Ma entro un mese stavo già facendo il cerchio in vita per intere canzoni, e entro sei mesi eseguivo movimenti semplici fuori dal corpo. L'età non mi ha fermato. Ha solo cambiato il modo in cui dovevo praticare.","La grande lezione è stata di riscaldarsi correttamente. Cerchi delle anche, torsioni del tronco e saltellamenti delicati delle ginocchia richiedono tre minuti e rendono il primo cerchio della sessione fluido invece che scricchiolante. SynthFlow inserisce i riscaldamenti all'inizio di ogni routine per una ragione, e ho smesso di saltarli dopo una mattina rigida.","La seconda lezione è stata la dimensione del cerchio. Un cerchio più grande e leggermente più pesante gira più lentamente, il che ti dà più tempo e richiede meno sforzo alla parte bassa della schiena. Ho iniziato con un cerchio che arrivava tra la vita e il petto quando era in piedi sul pavimento, e lo uso ancora per le sessioni di pratica lunghe.","Terza: pulsare, non girare. I principianti spesso muovono i fianchi in cerchio, il che fa torcere la colonna vertebrale più del necessario. Un pulsare avanti e indietro, o da un lato all'altro se il cerchio gira in quel modo, mantiene il cerchio in alto con meno sforzo. L'allenatore 3D mostra chiaramente questo se guardi i fianchi piuttosto che il cerchio.","Infine, breve e spesso batte lungo e occasionale. Dieci minuti quattro volte a settimana hanno fatto di più per me di un'ora la domenica. Il mio corpo si riprendeva tra le sessioni, e i movimenti si fissavano.","Se hai più di 40 anni e sei curioso, inizia. Il cerchio non sa quanti anni hai."]},"fire-and-the-beginner":{"title":"Fuoco e il principiante","summary":"La rotazione del fuoco è la parte più visibile delle flow arts e quella di cui i principianti chiedono di più. La risposta onesta è: non ancora, e non da soli.","body":["Ogni settimana qualcuno ci chiede quando SynthFlow insegnerà a usare il fuoco. È una domanda giusta. Il fuoco è bellissimo, e molti giocolieri sono entrati in scena dopo aver visto un cerchio di fuoco di notte. Ma non addestreremo mai nessuno a accendere un oggetto, e questo post spiega perché.","Il fuoco aggiunge rischi che non hanno nulla a che fare con la bravura: gestione del carburante, abbigliamento, vento, spettatori, ustioni e spegnimento. Questi aspetti si imparano da persone esperte di persona, con una persona di sicurezza addestrata presente e l'attrezzatura adeguata pronta. Un'app non può controllare il tuo deposito di carburante, i tuoi vestiti di cotone o il tuo asciugamano di sicurezza.","Ciò che l'app può fare è aiutarti a sviluppare le abilità necessarie per il fuoco prima di avvicinarti anche solo a esso. Ciò significa movimenti che puoi eseguire in modo affidabile per un intero brano, a un ritmo costante, senza cadute. Se un pattern ti sorprende ancora a casa con un oggetto di pratica, non è pronto per il fuoco.","Un test utile della comunità del fuoco: riesci a eseguire la routine con gli occhi semichiusi, al buio, mentre qualcuno ti parla? Il fuoco è luminoso, caldo e rumoroso, e richiede la tua attenzione. Il tuo corpo deve conoscere i movimenti senza supervisione.","Gli oggetti con LED sono un ottimo passo intermedio. Ti danno l'aspetto notturno, le tracce e la reazione del pubblico senza il rischio. Il pacchetto di stile LED di SynthFlow mostra come appariranno i tuoi pattern illuminati, il che è anche un buon modo per individuare piani scadenti.","Quando sarai pronto, trova una jam di fuoco locale, presentati e chiedi di imparare prima la sicurezza. Continua a girare oggetti di pratica fino ad allora. Il fuoco sarà ancora lì."]},"four-balls-taught-me-patience":{"title":"Quattro palle mi hanno insegnato la pazienza","summary":"Passare da tre palle a quattro mi ha richiesto più tempo di quanto ne abbia impiegato per imparare tre, e ha cambiato il modo in cui penso alla pratica.","body":["Tre palle mi hanno richiesto cinque settimane. Quattro ne hanno richieste cinque mesi. Nessuno mi aveva avvertito di questo, quindi lo avverto io: quattro palle non sono tre palle più una. È un modello completamente diverso, e il tuo corpo deve impararlo da zero.","In una fontana di quattro palle, ogni mano giocola due palle da sola, e le palle non si incrociano mai. Le mani di solito si alternano, ma non c'è alcuno scambio tra di loro. Tutto ciò che avevo imparato sul prendere una palla dall'altra mano era improvvisamente inutile.","Così sono tornato a una mano. Due palle nella mano destra, in colonne, poi in cerchi, finché non sono riuscito a fare cinquanta lanci senza pensare. Poi la mano sinistra, che ha richiesto tre volte più tempo. Poi entrambe le mani insieme, prima in sincronia, poi alternando. La scala di tempo in SynthFlow mi ha aiutato: ogni settimana iniziavo dalla parte bassa della gamma della fontana e salivo solo dopo una serie pulita.","La lezione sulla pazienza è arrivata dalle piattaforme. Alcune settimane non c'era alcun miglioramento. Registravo comunque i cali e le serie pulite, e il grafico mostrava un progresso lento anche quando sembrava non ce ne fosse. I dati rendevano sopportabili le settimane noiose.","L'altra lezione riguardava il riposo. Quattro palle affaticavano i miei avambracci in un modo che tre non avevano mai fatto. Quando praticavo ogni giorno, peggioravo. Quando praticavo ogni due giorni, miglioravo. I muscoli della presa hanno bisogno di recupero come tutti gli altri.","Se sei bloccato tra tre e quattro, dividi il problema, fidati delle settimane lente e concedi un giorno di riposo ai tuoi avambracci. Arriverà."]},"the-escalator-and-hand-traffic":{"title":"La scala mobile e l'arte del traffico manuale","summary":"I movimenti con l'anello tra le mani sembrano magia finché non vedi che sono solo una gestione attenta del traffico tra due mani.","body":["La prima volta che ho visto una scala mobile, l'anello sembrava salire lungo le braccia dell'esecutore e poi scendere di nuovo, all'infinito, senza una presa evidente. Ho pensato che ci volessero anni di pratica. Ne sono servite circa tre settimane, una volta capito che è solo un modello di passaggi di mano.","Quasi ogni movimento con l'anello fuori dal corpo riguarda quale mano tiene l'anello, quando lo lascia andare e dove l'altra mano lo incontra. Se il tempo tra le mani è incerto, l'anello vacilla fuori dal suo piano e il movimento va in pezzi. Se il tempo è preciso, l'anello sembra muoversi da solo.","Così ho iniziato a dare un nome ai passaggi di mano. Sulla base del conto di SynthFlow, ho detto ad alta voce le mani invece dei numeri: destra, sinistra, destra, sinistra, una per battito. Dirle con la musica mi ha costretto a notare quando la mia mano sinistra afferrava in anticipo. I preafferramenti erano la causa di quasi ogni vacillio.","La seconda chiave era mantenere l'anello nel suo piano. Una mano che si torce mentre afferra inclina l'anello, e un anello inclinato cade mezzo secondo dopo. L'overlay del piano aiuta qui, così come la pratica davanti a uno specchio a tempi lenti.","Una volta che la scala mobile si è sentita affidabile, sono arrivati più velocemente gli altri movimenti con le mani. Isolazioni, passaggi e lassos usano tutti la stessa idea: passaggi chiari, piani piatti, tempismo costante. La magia è solo gestione del traffico."]},"behind-the-back-without-fear":{"title":"Dietro la schiena senza paura","summary":"I pass di bastone dietro la schiena sono quelli in cui la maggior parte dei giocolieri si blocca. Il problema di solito non è la capacità, ma l'impulso di guardare.","body":["Per mesi il mio passaggio dietro la schiena è stato un passaggio frontale con una svolta speranzosa. Iniziavo il movimento, entravo in panico quando il bastone usciva dalla mia vista, e lo riportavo davanti a me. Il bastone non andava mai davvero dietro la schiena. Il mio cervello non me lo permetteva.","La svolta è arrivata accettando che non potevo vedere il movimento. Non puoi guardare un passaggio dietro la schiena. Devi sentire dove si trova il bastone dalla mano che lo lascia andare e fidarti della mano che aspetta.","Ho allenato quella sensazione a slow motion. Senza girare affatto, ho passato il bastone dietro la schiena, mano a mano, con gli occhi rivolti in avanti. Poi con una mezza rotazione lenta. Poi alla base della gamma di velocità del movimento, contando. Ogni passo sembrava sciocco. Ogni passo funzionava.","L'allenatore 3D è stato sorprendentemente utile perché potevo ruotare la vista e guardare il movimento da dietro. Vedere dove si incontrano le mani e come il bastone rimane nel piano della parete mentre gira, ha dato al mio corpo una mappa che non poteva ottenere dalla parte anteriore.","La seconda paura era colpirmi. Un bastone da pratica con estremità morbide e uno spazio ampio e sgombro hanno risolto il problema. Una volta che ho capito che un errore avrebbe causato solo un leggero urto invece di un livido, ho smesso di sussultare, e il sussulto era stato la causa degli errori.","Se dietro la schiena ti spaventa ancora, rallenta tutto, elimina la rotazione e tieni gli occhi rivolti in avanti. Le tue mani sanno più di quanto pensi."]},"why-reverse-feels-wrong":{"title":"Perché il cascade inverso sembra sbagliato","summary":"La cascata inversa utilizza le stesse mani, le stesse palle e lo stesso ritmo della cascata. Allora perché sembra di ricominciare da capo?","body":["Quando ho imparato la cascata inversa, mi aspettavo che ci avrebbe messo un pomeriggio. Sono le stesse tre palle, le stesse mani alternate e lo stesso ritmo della cascata. Ci sono volute tre settimane, e non riuscivo a capire perché.","La risposta è la direzione. In una cascata normale, ogni palla viene lanciata dall'interno del modello e catturata all'esterno. In una cascata inversa, la palla viene lanciata dall'esterno, sopra la palla in arrivo, e catturata all'interno. Le tue mani fanno lo stesso ritmo ma forme completamente diverse.","La nuova forma rompe il tuo tempo. Nella cascata, lanci proprio quando la palla in arrivo inizia a cadere. Nella inversa, devi lanciare un po' prima in modo che la tua palla superi la cima dell'altra. Lancia al vecchio momento e le palle si scontrano.","L'ho risolto prima con due palle. Due palle, cambio direzione, conto sul ritmo, finché non è diventato automatico. Poi tre palle a ritmo lento, con i conti detti ad alta voce. La sovrapposizione fantasma di SynthFlow mi ha mostrato un errore tipico, un lancio troppo basso che taglia l'altra palla, e ho potuto vedere che stavo esattamente facendo quello.","Una volta che ha funzionato, ha aperto molte porte. Mescolare cascade e reverse è la base di molti trucchi, e la forma reverse ricompare in Mills Mess. Essere stato pessimo per tre settimane ne è valsa la pena."]},"making-a-prop-stand-still":{"title":"Isolazioni: far stare fermo un oggetto","summary":"Un'isolazione è una mossa in cui il prop sembra rimanere in un punto mentre tu ti muovi intorno ad esso. È l'illusione più soddisfacente nelle arti del flusso.","body":["La prima volta che ho eseguito un'isolazione con il bastone, il mio amico mi ha chiesto come facesse il bastone a fluttuare. Naturalmente non stava fluttuando. Le mie mani si muovevano in un cerchio accurato in modo che un punto del bastone rimanesse fisso in aria. Ma dall'esterno sembrava impossibile, ed è questo sentimento che mi fa amare le isolazioni.","Ogni isolazione funziona allo stesso modo. Scegli un punto sul prop, di solito il centro o un'estremità, e mantieni quel punto fermo mentre il resto del prop ruota. Le tue mani devono muoversi esattamente in modo opposto a come il prop vuole muoversi. È controintuitivo e leggermente ipnotico.","La parte più difficile è che il tuo corpo si muove troppo. I fianchi si spostano, le spalle ruotano, e ogni piccolo movimento si manifesta come un traballamento nel punto fisso. Ho praticato davanti a uno specchio con un pezzo di nastro sulla vetrata che indicava dove doveva essere il punto fisso. Se il centro del prop usciva dal nastro, lo sapevo.","Le isolazioni con l'anello seguono la stessa idea. In SynthFlow attivo le tracce nel visualizzatore 3D e osservo l'allenatore: in un'isolazione pulita, la traccia intorno al punto fisso rimane piccola. Quando ho rallentato il ritmo al massimo e l'ho copiata, ho potuto sentire le mie mani che si spostavano in alto ad ogni cerchio.","Le isolazioni costruiscono anche il controllo che aiuta tutto il resto. Una volta che riesci a tenere fermo un prop, puoi posizionarlo ovunque tu voglia. I piani diventano più piatti, le transizioni più pulite, e il tuo flusso inizia a sembrare intenzionale piuttosto che fortuito.","Inizia piano, segna il punto fisso e osservalo come un falco. Poi mostralo a un amico e goditi la sua reazione."]}}`),i={"zero-to-cascade":{name:`Da zero alla cascata in 4 settimane`,description:`Una palla, poi due, poi si aggiunge la terza. Una breve sessione al giorno è sufficiente: completa la routine della settimana per padroneggiare il movimento e sbloccare il prossimo.`,weeks:[{label:`Settimana 1 · Un pallino`},{label:`Settimana 2 · Due pallini`},{label:`Settimana 3 · Il terzo pallino`},{label:`Settimana 4 · Cascata`}]},"beyond-the-cascade":{name:`Oltre la cascata`,description:`Quattro settimane di varietà con tre palle: tennis e artigli, poi lanci sul corpo, poi schemi sincroni con due palle alla volta.`,weeks:[{label:`Settimana 1 · Tennis e artigli`},{label:`Settimana 2 · Mezza doccia`},{label:`Settimana 3 · Lanci corpo`},{label:`Settimana 4 · Colonne`}]},"first-clubs":{name:`Primi bastoni`,description:`Da un singolo club che gira a una cascata stabile di tre club, poi doppie per altezza e controllo della rotazione.`,weeks:[{label:`Settimana 1 · Un bastone`},{label:`Settimana 2 · Scambio`},{label:`Settimana 3 · Cascata`},{label:`Settimana 4 · Doppie`}]},"passing-with-a-partner":{name:`Passaggio con un partner`,description:`Due giocolieri, faccia a faccia. Una palla in traverso, poi due ciascuno su un ritmo condiviso, poi il sei-count, il quattro-count e il due-count con tre palle ciascuno.`,weeks:[{label:`Settimana 1 · Un pallone in traverso`},{label:`Settimana 2 · Due palle ciascuno`},{label:`Settimana 3 · Sei conti e quattro conti`},{label:`Settimana 4 · Due conti`}]},"staff-foundations":{name:`Fondamenti del bastone`,description:`Rotazioni e giri anteriori, l'otto e il passaggio: i quattro movimenti da cui è costruito quasi ogni flusso con il bastone.`,weeks:[{label:`Settimana 1 · Ruota`},{label:`Settimana 2 · Rotazione frontale`},{label:`Settimana 3 · Figura 8`},{label:`Settimana 4 · Passaggio`}]},"staff-contact":{name:`Contatto con il bastone`,description:`Allentare la presa settimana dopo settimana: volante e coda di pesce, poi rotolii di mano, poi il bastone che gira sul polso.`,weeks:[{label:`Settimana 1 · Volante`},{label:`Settimana 2 · Coda di pesce`},{label:`Settimana 3 · Rotolamento a mano`},{label:`Settimana 4 · Rotolamento avambraccio`}]},"double-staff-start":{name:`Inizio doppio bastone`,description:`Da due bastoni in passo a tempo diviso e ruote su entrambi i lati.`,weeks:[{label:`Settimana 1 · Allo stesso tempo`},{label:`Settimana 2 · Tempo diviso`},{label:`Settimana 3 · Ruote`},{label:`Settimana 4 · Ruote divise`}]},"hoop-body-ladder":{name:`Scala del cerchio corpo`,description:`Hoop in vita in entrambe le direzioni, poi giù verso i fianchi e le cosce e su verso il petto.`,weeks:[{label:`Settimana 1 · Entrambe le direzioni`},{label:`Settimana 2 · Anca`},{label:`Settimana 3 · Cosce`},{label:`Settimana 4 · Sollevamento petto`}]},"hoop-doubles-start":{name:`Inizio doppio cerchio`,description:`Un anello in ogni mano: rotazioni riflesse, rotazioni sfalsate, rotazioni laterali, poi uno in vita e uno in mano.`,weeks:[{label:`Settimana 1 · Giri specchiati`},{label:`Settimana 2 · Giri sfalsati`},{label:`Settimana 3 · Giri laterali`},{label:`Settimana 4 · Vita e mano`}]},"off-body-hoop":{name:`Cerchio fuori corpo`,description:`Dalla rotazione dell'anello su una mano a lassos, passaggi, wedgies e l'isolamento che fa sembrare l'anello galleggiare.`,weeks:[{label:`Settimana 1 · Giro a mano`},{label:`Settimana 2 · Lasso e passaggio`},{label:`Settimana 3 · Wedgie`},{label:`Settimana 4 · Isolamento`}]},"first-poi":{name:`Primo poi`,description:`Un poi, poi una coppia: rotazioni a muro in entrambe le direzioni, ruote ai lati, poi divisione del tempo.`,weeks:[{label:`Settimana 1 · Un poi`},{label:`Settimana 2 · Rotazioni a parete`},{label:`Settimana 3 · Ruote`},{label:`Settimana 4 · Tempo diviso`}]},"poi-weave-ladder":{name:`Scala intrecciata dei poi`,description:`Dalla caccia al sole alla tre-battuta intrecciata in entrambe le direzioni, poi l'intreccio più veloce a due battiti.`,weeks:[{label:`Settimana 1 · Inseguire il sole`},{label:`Settimana 2 · Intreccio a tre battiti`},{label:`Settimana 3 · Intreccio inverso`},{label:`Settimana 4 · Intreccio a due battiti`}]},"poi-antispin-start":{name:`Inizio antispin`,description:`Estensioni e isolazioni prima, poi antispin con un poi e il fiore a quattro petali con due.`,weeks:[{label:`Settimana 1 · Estensioni`},{label:`Settimana 2 · Isolamento`},{label:`Settimana 3 · Antispin con un poi`},{label:`Settimana 4 · Fiore antispin`}]}},a={"sf-ambient-70":{name:`Orbita lenta`},"sf-world-75":{name:`Passi del mercato`},"sf-ambient-80":{name:`Deriva della lanterna`},"sf-world-85":{name:`Ruota del deserto`},"sf-handdrum-90":{name:`Tamburo Circolare`},"sf-funk-95":{name:`Caviglie Sciolte`},"sf-handdrum-100":{name:`Mani alla Luce del Fuoco`},"sf-world-105":{name:`Campane del Fiume`},"sf-funk-110":{name:`Cascata in Tasca`},"sf-handdrum-115":{name:`Ritmo del Cortile`},"sf-electronic-120":{name:`Bastone al Neon`},"sf-funk-125":{name:`Schema Rimbalzo`},"sf-electronic-130":{name:`Anello Pixel`},"sf-handdrum-135":{name:`Djembe al Tramonto`},"sf-electronic-140":{name:`Tracce LED`},"sf-funk-145":{name:`Ciclo di Rotazione`},"sf-electronic-150":{name:`Flusso al Lampeggio`},"sf-handdrum-155":{name:`Palme Veloci`},"sf-electronic-160":{name:`Giratore Notturno`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};